int y[MAX_N];

void solve(int a, int b, int x) {
	if(x==0) {
		if(a==1) printf("R");
		else if(a==-1) printf("L");

		if(b==1) printf("U");
		else if(b==-1) printf("D");

		if(a==0 && b==0) printf("UD");

		printf("\n");
		return;
	}

	int d = 1<<x;
	if(a>=d) {
		if(b>=d) {
			printf("UR");
			solve(a-d, b-d, x-1);
		} else if(b>-d) {
			printf("RR");
			solve(a-d-d, b, x-1);
		} else {
			printf("DR");
			solve(a-d, b+d, x-1);
		}
	} else if(a>-d) {
		if(b>=d) {
			printf("UU");
			solve(a, b-d-d, x-1);
		} else if(b>-d) {
			printf("UD");
			solve(a, b, x-1);
		} else {
			printf("DD");
			solve(a, b+d+d, x-1);
		}
	} else {
		if(b>=d) {
			printf("LU");
			solve(a+d, b-d, x-1);
		} else if(b>-d) {
			printf("LL");
			solve(a+d+d, b, x-1);
		} else {
			printf("LD");
			solve(a+d, b+d, x-1);
		}
	}
}

