using namespace std;
using ll = long long;

ll N;
vector<pair<ll, ll>> xy;

void input() {
    cin >> N;
    xy.resize(N);
    for (ll i = 0; i < N; i++) {
        ll x, y;
        cin >> x >> y;
        xy[i] = {x, y};
    }
}

void solve() {
    vector<ll> parities;
    set<ll> pset;
    for (auto pair : xy) {
        auto p = abs(pair.first + pair.second) % 2;
        parities.push_back(p);
        pset.insert(p);
    }
    if (pset.size() != 1) {
        cout << -1 << endl;
        return;
    }

    vector<ll> arms;
    if (pset.find(0) != pset.end()) {
        arms.push_back(1);
    }
    for (ll i = 0; i < 32; i++) {
        arms.push_back(1ull << i);
    }

    auto M = arms.size() - (parities[0] == 0 ? 1 : 0);
    cout << M << endl;
    for (auto arm : arms) {
        cout << arm << ' ';
    }
    cout << endl;

    for (ll i = 0; i < N; i++) {
        string dirs;
        string dir_type = "LDUR";
        auto x = xy[i].first, y = xy[i].second;
        if (parities[i] == 0) {
            x--;
            dirs.push_back('R');
        }
        auto u = ((x + y) >> 1) + (1ull << 31);
        auto v = ((x - y) >> 1) + (1ull << 31);
        for (ll r = 0; r < M; r++) {
            dirs.push_back(dir_type[(u>>r & 1)*2 + (v>>r & 1)]);
        }
        {// check
            if (parities[0] == 0)
                x++;
            ll cx = 0, cy = 0;
            for (ll n = 0; n < dirs.size(); n++) {
                auto len = arms[n];
                auto dir = dirs[n];
                if (dir == 'L' or dir == 'D') {
                    if (dir == 'L') {
                        cx-=len;
                    } else {
                        cy-=len;
                    }
                } else {
                    if (dir == 'U') {
                        cy+=len;
                    } else {
                        cx+=len;
                    }
                }
            }
            if (cx != x or cy != y) {
                cerr << "error: ";
                cerr << x << ' ' << y << ' ' << cx << ' ' << cy << endl;
            }
        }

        cout << dirs << endl;
    }
}


int main() {
    input();
//    cout << solve() << endl;
    solve();

    return 0;
}

