void solve(){
    i64 N;
    cin >> N;

    vector<i64> X(N),Y(N);
    rep(i,0,N) cin >> X[i] >> Y[i];

    rep(i,0,N) if(((X[i]+Y[i])%2+2)%2!=((X[0]+Y[0])%2+2)%2){
        cout << -1 << endl;
        return;
    }

    vector<i64> U(N),V(N);
    rep(i,0,N){
        U[i]=X[i]+Y[i];
        V[i]=X[i]-Y[i];
    }

    i64 m=32;
    vector<i64> d(m);
    d[0]=1;
    rep(i,1,m) d[i]=d[i-1]*2;
    reverse(begin(d),end(d));

    if((X[0]+Y[0])%2==0){
        d.push_back(1);
        ++m;
    }

    vector<string> ans(N);
    rep(i,0,N){
        vector<i64> s(m),t(m);
        i64 u=U[i],v=V[i];
        rep(j,0,m){
            i64 u1=u-d[j],u2=u+d[j];
            if(abs(u1)<=abs(u2)){
                u=u1;
                s[j]=-1;
            }else{
                u=u2;
                s[j]=1;
            }
        }
        rep(j,0,m){
            i64 v1=v-d[j],v2=v+d[j];
            if(abs(v1)<=abs(v2)){
                v=v1;
                t[j]=-1;
            }else{
                v=v2;
                t[j]=1;
            }
        }

        string tmp;
        rep(j,0,m){
            if(s[j]==-1 and t[j]==-1) tmp+='L';
            else if(s[j]==1 and t[j]==1) tmp+='R';
            else if(s[j]==-1 and t[j]==1) tmp+='D';
            else tmp+='U';
        }

        ans[i]=tmp;
    }

    cout << m << endl;
    rep(i,0,m){
        cout << d[i];
        if(i==m-1) cout << endl;
        else cout << " ";
    }

    rep(i,0,N) cout << ans[i] << endl;
}

