string calc(long long val){
	string ans = "";
	long long cur = val;
	if(val % 2 != 0){
		for(int i = 0; i + 1 < D.size(); ++i){
			long long nxt;
			long long nxtm = cur - D[i];
			if(nxtm % (D[i] * 4) != 0){
				ans = ans + "+";
				nxt = nxtm;
			}else{
				ans = ans + "-";
				nxt = cur + D[i];
			}
			cur = nxt;
		}
		if(cur < 0) ans = ans + "-";
		else ans = ans + "+";
	}else{
		cur++;
		ans = "-";
		for(int i = 1; i + 1 < D.size(); ++i){
			long long nxt;
			long long nxtm = cur - D[i];
			if(nxtm % (D[i] * 4) != 0){
				ans = ans + "+";
				nxt = nxtm;
			}else{
				ans = ans + "-";
				nxt = cur + D[i];
			}
			cur = nxt;
		}
		if(cur < 0) ans = ans + "-";
		else ans = ans + "+";
	}
	return ans;
}

string restoreArm(long long x, long long y){
	string s1 = calc(x + y);
	string s2 = calc(x - y);
	string ans = "";
	for(int i = 0; i < s1.size(); ++i){
		pair<char, char> p = make_pair(s1[i], s2[i]);
		if(p == P('+', '+')) ans += "R";
		if(p == P('+', '-')) ans += "U";
		if(p == P('-', '+')) ans += "D";
		if(p == P('-', '-')) ans += "L";
	}
//	printf("%lld %lld:\n", x, y);
//	printf("%s %s\n", s1.c_str(), s2.c_str());
	return ans;
}

