    if ( ((x[0] + y[0]) & 1) != 1 ) {
        d.push_back(1);
        for (int i=0; i<N; i++) {
            y[i]--;
            s[i].push_back('U');
        }
    }

    long long int step = 1;
    while( step < (1LL << 33) ) {
        d.push_back(step);
        for(int i=0; i<N; i++) {
            if ( ((x[i] + y[i]) & 1) != 1 ) {
                cout << -1 << endl;
                return 0;
            }
            if ( x[i] & 1 ) {
                if (((x[i] - 1) & 2 ) == (y[i] & 2)) {
                    x[i]++;
                    s[i].push_back('L');
                } else {
                    x[i]--;
                    s[i].push_back('R');
                }
            } else {
                if (((y[i] - 1) & 2 ) == (x[i] & 2)) {
                    y[i]++;
                    s[i].push_back('D');
                } else {
                    y[i]--;
                    s[i].push_back('U');
                }
            }
            x[i] /= 2;
            y[i] /= 2;
        }
        step <<= 1;
    }
