int get(int x, int y) {
    return (((x + y) % 2) + 2) % 2;
}

void solve() {
    int n;
    cin >> n;
    vector<long long> x(n), y(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        if (i > 0 && get(x[i - 1], y[i - 1]) != get(x[i], y[i])) {
            cout << -1; return;
        }
    }
    int parity = get(x[0], y[0]);
    cout << 30 + (parity == 0) << "\n";
    if (!parity) cout << 1 << ' ';
    for (int i = 29; i >= 0; i--) {
        cout << (1 << i) << ' ';
    }
    cout << "\n";
    for (int i = 0; i < n; i++) {
        string s;
        if (!parity) s.push_back('U'), y[i]++;
        for (int j = 29; j >= 0; j--) {
            for (int k = 0; k < 4; k++) {
                long long nx = x[i] + 1LL * dx[k] * (1LL << j), ny = y[i] + 1LL * dy[k] * (1LL << j);
                if (abs(nx) + abs(ny) <= (1LL << j) - 1) {
                    x[i] = nx, y[i] = ny;
                    s.push_back(dir[k])
                    break;
                }
            }
        }
        reverse(s.begin(), s.end());
        cout << s << "\n";
    }
}

