#define NMAX 1001
using point = pair <int, int>;

point v[NMAX];
string sol[NMAX];

bool impossible(const int n) {
    const int p = abs((v[1].first + v[1].second) % 2);
    for (int i = 2; i <= n; i++) {
        if (p != abs((v[i].first + v[i].second) % 2))
            return true;
    }
    return false;
}

int find_k(const int n) {
    int k = 0;
    while (1) {
        const long long M = (1LL << (k + 1)) - 1LL;
        int can = true;
        for (int i = 1; i <= n; i++) {
            long long dist = 0LL + abs(v[i].first) + abs(v[i].second);
            if (dist > M) {
                can = false;
                break;
            }
        }
        if (can) {
            break;
        }
        k++;
    }
    return k;
}

bool is_possible(const long long x, const long long y, const int k) {
    if (k < 0) {
        return x == 0 && y == 0;
    }
    long long M = (1LL << (k + 1)) - 1LL;
    long long dist = 0LL + abs(x) + abs(y);
    return dist <= M;
}

string solve(long long x, long long y, const int k) {
    assert(abs((x + y) % 2) == 1);
    assert(is_possible(x, y, k));

    int dx[] = {0, 0, 1, 0, -1};
    int dy[] = {0, 1, 0, -1, 0};
    char D[] = {'A', 'U', 'R', 'D', 'L'};
    string moves;

    for (int i = k; i >= 0; i--) {
        long long dist = (1LL << i);
        int m;
        for (m = 1; m <= 4; m++) {
            long long xp = x - dist * dx[m];
            long long yp = y - dist * dy[m];
            if (is_possible(xp, yp, i - 1))
                break;
        }
        assert(m <= 4);
        moves.push_back(D[m]);
        x = x - dist * dx[m];
        y = y - dist * dy[m];
    }
    reverse(moves.begin(), moves.end());
    return moves;
}

int main()
{
    ios::sync_with_stdio(false);

    int n;
    // ifstream cin("code.in");
    cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> v[i].first >> v[i].second;
    }

    if (impossible(n)) {
        cout << "-1\n";
        return 0;
    }

    const int par = abs((v[1].first + v[1].second) % 2);
    if (par == 0) {
        for (int i = 1; i <= n; i++) {
            v[i].second++;
        }
    }
    const int k = find_k(n);
    if (par == 0) {
        cout << k + 2 << '\n' << 1 << " ";
    } else {
        cout << k + 1 << '\n';
    }
    for (int i = 0; i <= k; i++) {
        cout << (1LL << i) << " ";
    }
    cout << '\n';
    for (int i = 1; i <= n; i++) {
        sol[i] = solve(v[i].first, v[i].second, k);
    }
    for (int i = 1; i <= n; i++) {
        if (par == 0)
            cout << "D";
        cout << sol[i] << '\n';
    }

    return 0;
}

