bool is_in (ll c_x, ll c_y, ll x, ll y, ll r)
{
	return (abs (c_x + c_y - (x + y)) <= r && abs (c_x - c_y - (x - y)) <= r);
}

string find (ll x, ll y)
{
	string s;

	if (even)
	{
		s += 'U';
		y++;
	}

	ll sum = 0;

	for (ll i = 34; i >= 0; i--)
		sum += (1LL << i);

