	for (ll i = 34; i >= 0; i--)
	{
		//cout << x << ' ' << y << ' ' << c_x << ' ' << c_y << endl;

		sum -= (1LL << i);

		if (is_in (c_x, c_y + (1LL << i), x, y, sum))
		{
			s += 'U';
			c_y += (1LL << i);
		}
		else if (is_in (c_x + (1LL << i), c_y, x, y, sum))
		{
			s += 'R';
			c_x += (1LL << i);
		}
		else if (is_in (c_x, c_y - (1LL << i), x, y, sum))
		{
			s += 'D';
			c_y -= (1LL << i);
		}
		else if (is_in (c_x - (1LL << i), c_y, x, y, sum))
		{
			s += 'L';
			c_x -= (1LL << i);
		}
	}

