string calc(long long x,long long y,long long k){//2^0,2^1,...,2^k
    if(k==-1)return "";
    long long f1=x<0,f2=y<0;
    x=abs(x),y=abs(y);
    string s;
    if(x>y)s='R'+calc(x-(1<<k),y,k-1);
    else s='U'+calc(x,y-(1<<k),k-1);
    if(f1)for(auto & c:s){
        if(c=='L')c='R';
        else if(c=='R')c='L';
    }
    if(f2)for(auto & c:s){
        if(c=='U')c='D';
        else if(c=='D')c='U';
    }
    return s;
}

void check(string s,vector<int> d,pair<int,int> p){
    assert(s.size() == d.size());
    long long px=0,py=0;
    for(long long i=0;i<s.size();i++){
        if(s[i]=='L')px-=d[i];
        if(s[i]=='R')px+=d[i];
        if(s[i]=='U')py+=d[i];
        if(s[i]=='D')py-=d[i];
        //printf("%d %d\n",px,py);
    }
    assert(px==p.fi && py==p.se);
}
