using namespace std;

int x[1003], y[1003];
vector<int> arms;

bool insq(int px, int py, int i, int sz) {
	int sumdist = abs(y[i] - py) + abs(x[i] - px);
	if (sumdist <= sz)
		return true;
	return false;
}

int main() {
	ios::sync_with_stdio(0);
	int n;
	cin >> n;
	for (int i = 0; i < n; i++)
		cin >> x[i] >> y[i];
	int mx = -1;
	int xyp = (abs(x[0]) + abs(y[0])) & 1;
	bool failed = false;
	for (int i = 0; i < n; i++) {
		int axy = abs(x[i]) + abs(y[i]);
		if (axy & 1 != xyp)
			failed = true;
		mx = max(axy, mx);
	}
	if (failed) {
		cout << "-1\n";
		return 0;
	}
	int cl = 1;
	int sxy = 0;
	if (mx == 0) {
		cout << "2\n1 1\n";
		for (int i = 0; i < n; i++)
			cout << "LR\n";
		return 0;
	}else if (xyp == 1) {
		while (sxy < mx) {
			sxy += cl;
			arms.push_back(cl);
			cl *= 2;
		}
	}
	else {
		while (sxy < mx - 1) {
			sxy += cl;
			arms.push_back(cl);
			cl *= 2;
		}
		arms.push_back(1);
		sxy++;
	}
	reverse(arms.begin(), arms.end());
	int asz = (int)arms.size();
	cout << asz << "\n";
	for (auto it : arms)
		cout << it << " ";
	cout << "\n";
	for (int i = 0; i < n; i++) {
		int px = 0, py = 0, p = 0, sz = sxy;
		while (p<asz) {
			sz -= arms[p];
			if (insq(px - arms[p], py, i, sz)) {
				px -= arms[p];
				cout << "L";
			}
			else if (insq(px + arms[p], py, i, sz)) {
				px += arms[p];
				cout << "R";
			}
			else if (insq(px, py - arms[p], i, sz)) {
				py -= arms[p];
				cout << "D";
			}
			else {
				py += arms[p];
				cout << "U";
			}
			p++;
		}
		cout << "\n";
	}
	//system("pause");
	return 0;
}

