template<int E, long long... A>
struct Seq{
    static constexpr auto value = Seq<E-1,(1ll<<E),A...>::value;
};

template<long long... A>
struct Seq<0,A...>{
    static constexpr long long value[] = {1ll,A...};
};

template<long long... A>
constexpr long long Seq<0,A...>::value[];

constexpr auto *d = Seq<m>::value;

string calc(ll u,ll v){
    string ret;
    for(int i=m-1;i>=0;i--){
        if(u >= cx and v >= cy){
            u -= d[i];
            v -= d[i];
            ret.push_back('R');
        }else if(u >= cx and v < cy){
            u -= d[i];
            v += d[i];
            ret.push_back('U');
        }else if(u < cx and v < cy){
            u += d[i];
            v += d[i];
            ret.push_back('L');
        }else{
            u += d[i];
            v -= d[i];
            ret.push_back('D');
        }
    }
    reverse(all(ret));
    return ret;
}

