                long long cur = abs(x[i] - dx[k] * (1LL << j)) + abs(y[i] - dy[k] * (1LL << j));
                if (cur < best) {
                    best = cur;
                    opt = k;
                }
            }
            x[i] -= dx[opt] * (1LL << j);
            y[i] -= dy[opt] * (1LL << j);
            s += dir[opt];
        }
        assert(x[i] == 0 && y[i] == 0);
        cout << s << '\n';
    }
    return 0;
}

