		else flag1 = 1;
		pmax = max(pmax, ABS(X[i]) + ABS(Y[i]));
	}
	if (flag0 == 1 && flag1 == 1)
	{
		cout << -1 << endl;
		return 0;
	}
	ll sum = 0; int pos = 0;
	if (flag0 == 1) { d[pos++] = 1; sum += 1; }
	for (ll k = 0; k < 50; k++)
	{
		sum += (ll(1) << k);
		d[pos++] = (ll(1) << k);
		if (sum >= pmax)break;
	}
	cout << pos << endl;
	for (int i = pos - 1; i >= 0; i--)
		cout << d[i] << ' ';
	cout << endl;

	for (int i = 1; i <= N; i++)
		solve(i, pos);
	return 0;
}

