using namespace std;


class Solution {
    public:
        vector<string> solve(vector<long long>& X, vector<long long>& Y, vector<long long>& A) {
            int n = X.size();
            for (int i = 0; i < n; ++i) {
                if ((abs(X[i]) + abs(Y[i])) % 2 != (abs(X[0]) + abs(Y[0])) % 2) {
                    return {};        
                }
            }

            int h = 32;
            A.clear();
            for (int i = h - 1; i >= 0; --i) {
                A.emplace_back(1LL << i);
            }
            if ((abs(X[0]) + abs(Y[0])) % 2 == 0) {
                A.emplace_back(1);
            }


            string dir = "LRUD";
            vector<int> DX{-1, 1, 0, 0};
            vector<int> DY{0, 0, 1, -1};

            vector<string> res;

            for (int i = 0; i < n; ++i) {
                long long x = X[i], y = Y[i];
                string s;
                for (int j = 0; j < A.size(); ++j) {
                    long long nx = 0, ny = 0;
                    long long dis = 1LL << 60;
                    int d = -1;

                    for (int k = 0; k < 4; ++k) {
                        long long dx = DX[k ^ 1];
                        long long dy = DY[k ^ 1];
                        long long tx = x + dx * A[j], ty = y + dy * A[j];
                        if (abs(tx) + abs(ty) < dis) {
                            dis = abs(tx) + abs(ty);
                            nx = tx, ny = ty;
                            d = k;
                        }
                    }

                    s += dir[d];
                    x = nx, y = ny;
                }
                assert(x == 0 && y == 0);
                res.emplace_back(s);
            }

            return res;
        }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);


    int n;
    cin >> n;
    vector<long long> X(n);
    vector<long long> Y(n);
    for (int i = 0; i < n; ++i) {
        cin >> X[i] >> Y[i];
    }


    vector<long long> A;
    Solution sol;
    auto res = sol.solve(X, Y, A);
    if (res.empty()) {
        cout << "-1\n";
    } else {
        cout << A.size() << "\n";
        for (int i = 0; i < A.size(); ++i) {
            cout << A[i] << (i + 1 == A.size() ? '\n' : ' ');
        }
        for (auto& s : res) {
            cout << s << "\n";
        }
    }

    return 0;
}

