pair<int, int> a[1001];
pair<int, int> b[1001];
vector<vector<int>> vt;
int main()
{
	int n;
	scanf("%d", &n);
	int cnt = 0, cnt1 = 0;
	vt.resize(n + 1);
	for (int i = 0; i < n; i++)
	{
		scanf("%d %d", &a[i].first, &a[i].second);
		if ((a[i].first + a[i].second) % 2)cnt++;
		else cnt1++;
	}
	if (cnt&&cnt1)
	{
		puts("-1");
		return 0;
	}
	while (1) {
		int ch = 0;
		for (int i = 0; i < n; i++)
		{
			if (check[i]) {
				if (check[i] % 2) {
					vt[i].push_back(1);
					ch++;
				}
				else {
					vt[i].push_back(2);
				}
				check[i]++;
				continue;
			}
			if (a[i].first == b[i].first&&a[i].second == b[i].second) {
				check[i] = 1;
				vt[i].push_back(2);
			}

			else if (a[i].first < b[i].first) {
				b[i].first--;
				vt[i].push_back(1);
			}
			else if (a[i].first > b[i].first) {
				b[i].first++;
				vt[i].push_back(2);
			}
			else if (a[i].second > b[i].second) {
				b[i].second++;
				vt[i].push_back(3);
			}
			else {
				vt[i].push_back(4);
				b[i].second--;
			}
		}
		if (ch == n)break;
	}
	int t = vt[0].size();
	printf("%d\n", t);
	for (int i = 0; i < t; i++)
		printf("1 ");
	printf("\n");
	for (int i = 0; i < n; i++)
	{
		for (int y = 0; y < t; y++)
		{
			if (vt[i][y] == 1)printf("D");
			else if (vt[i][y] == 2)printf("U");
			else if (vt[i][y] == 3)printf("R");
			else printf("L");
		}
		printf("\n");
	}
}

