template <typename _TpInt> inline _TpInt read()       
{
    register _TpInt flag = 1; register char c = getchar();
    while ((c > '9' || c < '0') && c != '-') c = getchar();
    if (c == '-') flag = -1, c = getchar(); register _TpInt init = (c & 15);
    while ((c = getchar()) <= '9' && c >= '0') init = (init * 10) + (c & 15);
    return init * flag;
}

template <typename _TpInt> inline void write(_TpInt x)
{
    if (x < 0) { putchar('-'); write<_TpInt>(~x + 1); } 
    else { if (x > 9) write<_TpInt>(x / 10); putchar(x % 10 + '0'); } 
}

