vector<ll> tf(ll r){
	ll cur = 0;
	vector<ll> res;
	for(int i=0;i<tfs.size();i++){
		if(cur<=r){
			res.pb(1);
			cur += tfs[i];
		}
		else{
			res.pb(-1);
			cur -= tfs[i];
		}
	}
	reverse(res.begin(),res.end());
	return res;
}
