vector<pair<pair<int, int>, string>> produce(pair<pair<int, int>, string> a, int t)
{
    int x = a.first.first; int y = a.first.second; string s = a.second;
    return {mp(mp(x+t, y), s+'R'), mp(mp(x-t, y), s+'L'), mp(mp(x, y+t), s+'U'), mp(mp(x, y-t), s+'D')};
}

pair<pair<int, int>, string> check(pair<pair<int, int>, string> a, vector<int> t, int l)
{
    set<pair<pair<int, int>, string>> kek;
    kek.insert(a);
    for (auto it: t)
    {
        set<pair<pair<int, int>, string>> lol;
        for (auto el: kek)
        {
            for (auto pos: produce(el, it))
            {
                lol.insert(pos);
            }
        }
        kek = lol;
    }
    for (auto it: kek)
    {
        if (it.first.first<=l && it.first.first>=-l && it.first.second<=l && it.first.second>=-l) return it;
    }
}
