using namespace std;

void work(int v, string d, string &s, vector<int> &ans) {
  for (int j = 0; j <= 30; ++j) {
    if ((abs(v) >> j & 1) == 0) {
      continue;
    }
    int cnt = 0;
    for (int k = 0; k < (int)ans.size(); ++k) {
      if (s[k] != '*') {
        continue;
      }
      if ((1 << ans[k]) == (1 << j)) {
        s[k] = d[v > 0];
        ++cnt;
      }
      if (cnt == 1) {
        break;
      }
    }
    if (cnt == 0) {
      for (int k = 0; k < (int)ans.size(); ++k) {
        if (s[k] != '*') {
          continue;
        }
        if ((1 << ans[k]) == (1 << (j - 1))) {
          s[k] = d[v > 0];
          ++cnt;
        }
        if (cnt == 2) {
          break;
        }
      }
      assert(cnt == 2);
    }
  }
}

const int BITS = 39;

int mn[BITS];
int mx[BITS];
int w[BITS];

const int N = 1'009;

int x[N];
int y[N];

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i <= 30; ++i) {
    mn[i] = 3;
    mx[i] = -1;
  }
  for (int i = 0; i < n; ++i) {
    scanf("%d %d", x + i, y + i);
    for (int j = 0; j <= 30; ++j) {
      int cnt = (abs(x[i]) >> j & 1) + (abs(y[i]) >> j & 1);
      mn[j] = min(mn[j], cnt);
      mx[j] = max(mx[j], cnt);
    }
  }
  vector<int> ans;
  for (int i = 0; i <= 30; ++i) {
    for (int j = 0; j < mn[i]; ++j) {
      ans.push_back(i);
    }
    for (int j = 0; j < 2 * (mx[i] - mn[i]); ++j) {
      if (i >= 1) {
        ans.push_back(i - 1);
      } else {
        puts("-1");
        return 0;
      }
    }
  }
  if ((int)ans.size() > 40) {
    puts("-1");
    return 0;
  }
  printf("%d\n", (int)ans.size());
  for (int i = 0; i < (int)ans.size(); ++i) {
    if (i > 0) {
      putchar(' ');
    }
    printf("%d", 1 << ans[i]);
  }
  putchar('\n');
  for (int i = 0; i < n; ++i) {
    string s((int)ans.size(), '*');
    work(x[i], "LR", s, ans);
    work(y[i], "DU", s, ans);
    memset(w, 0, sizeof w);
    for (int j = 0; j < (int)ans.size(); ++j) {
      if (s[j] != '*') {
        continue;
      }
      s[j] = w[ans[j]] == 0 ? 'L' : 'R';
      w[ans[j]] = 1 - w[ans[j]];
    }
    for (int j = 0; j <= 30; ++j) {
      assert(w[j] == 0);
    }
    int cx = 0, cy = 0;
    for (int j = 0; j < (int)s.size(); ++j) {
      cx += ((s[j] == 'R') - (s[j] == 'L')) * (1 << ans[j]);
      cy += ((s[j] == 'U') - (s[j] == 'D')) * (1 << ans[j]);
    }
    assert(cx == x[i] && cy == y[i]);
    puts(s.c_str());
  }
}

