int n,cnt=0;
int dis(int x1, int y1, int x2, int y2) {
    return abs(x1-x2)+abs(y1-y2);
}
void solve(int x, int y) {
    Point now={0,0};
    for (int i=1; i<=cnt; i++) {
        int mi=INF;
        int pos=0;
        for (int j=0; j<4; j++) {
            int tx=now.x+dir[j][0]*d[i],ty=now.y+dir[j][1]*d[i];
            int t=dis(tx,ty,x,y);
            if (mi>t) mi=t,pos=j;
        }
        now.x+=d[i]*dir[pos][0],now.y+=d[i]*dir[pos][1];
        putchar(s[pos]);
    }
    puts("");
}
