pair<ll, ll> check(vector<ll> &ans, string &str) {
  static map<char, int> dx {
    {'D', 0},
    {'U', 0},
    {'L', -1},
    {'R', +1},
  };
  static map<char, int> dy {
    {'D', -1},
    {'U', +1},
    {'L', 0},
    {'R', 0},
  };
  int x = 0, y = 0;
  for(int i = 0; i < D; i++) {
    x += dx[str[i]] * ans[i];
    y += dy[str[i]] * ans[i];
  }
  return {x, y};
}

