vector<char> dir = {'R', 'U', 'L', 'D'};
vll d;

tuple<char, ll, ll> calc(ll x, ll y, int ind) {
  int target = (1 << ind) - 1;
  rep (i, 4) {
    ll prev_x = x - d[ind] * dx[i];
    ll prev_y = y - d[ind] * dy[i];
    ll sumxy = abs(prev_x) + abs(prev_y);
    if (sumxy <= target) {
      return {dir[i], prev_x, prev_y};
    }
  }
  assert(false);
}

