    void dfs(int x, int y, int cur) {
        if(cur == 0) return;
        int chg = 1LL << (cur - 1);
        for(int dir = 0; dir < 4; ++dir) {
            int xf = x + dx[dir] * chg, yf = y + dy[dir] * chg;
            if(abs(xf) + abs(yf) < (1LL << (cur - 1)) ) {
                putchar(dr[dir]);
                dfs(xf, yf, cur - 1);
                break;
            }
        }
    }
    inline void solve() {
        rep(i, n) ham = max(ham, x[i] + y[i]) + 2;
        for(k = 0; (1LL << k) < ham; ++k) ;
        if(even) printf("%lld\n1 ", ++k + 1);
