bool isValid(int x, int y, int p) {
	return abs(x) + abs(y) < (1<<p);
}

string solve_for(int x, int y, int p) {
	if(p < 0) return "";
	if(isValid(x - (1<<p), y, p)) return solve_for(x - (1<<p), y, p-1) + 'R';
	if(isValid(x + (1<<p), y, p)) return solve_for(x + (1<<p), y, p-1) + 'L';
	if(isValid(x, y - (1<<p), p)) return solve_for(x, y - (1<<p), p-1) + 'U';
	if(isValid(x, y + (1<<p), p)) return solve_for(x, y + (1<<p), p-1) + 'D';
	return "";
}

