};

void print(int x, int y, int m) {
    if(m <= 0) {
        cout << "\n";
        return;
    }
    if(y + x >= 0 && y - x >= 0) {
        cout << 'U';
        print(x, y - (1LL << (m - 1)), m - 1);
    } else if(y + x >= 0 && y - x < 0) {
        cout << 'R';
        print(x - (1LL << (m - 1)), y, m - 1);
    } else if(y + x < 0 && y - x >= 0) {
        cout << 'L';
        print(x + (1LL << (m - 1)), y, m - 1);
    } else {
        cout << 'D';
        print(x, y + (1LL << (m - 1)), m - 1);
    }
}

