string solve(int par, pair<long long, long long> XY){
    string ans;
    if(par == 0){
        ans += "L";
        XY.first++;
    }
    long long U = (XY.first+XY.second+((1LL<<31)-1))/2;
    long long V = (XY.first-XY.second+((1LL<<31)-1))/2;
    vector<int> uu(31), vv(31);
    for(int i=0; i<=30; i++){
        uu[i] = (U >> i) & 1;
        vv[i] = (V >> i) & 1;
    }
    for(int i=0; i<=30; i++)
        if(uu[i] == 0 && vv[i] == 0)
            ans += "L";
        else if(uu[i] == 1 && vv[i] == 1)
            ans += "R";
        else if(uu[i] == 0 && vv[i] == 1)
            ans += "D";
        else if(uu[i] == 1 && vv[i] == 0)
            ans += "U";
    return ans;
}

int main(){
    int N;
    cin >> N;
    vector<pair<long long, long long>> XY(N);
    for(int i=0; i<N; i++) cin >> XY[i].first >> XY[i].second;

