i64 power2(i64 a, i64 b) {
    if (a > b) return a;

    i64 k = 1LL;
    while (k <= (b+1LL)) {
        k <<= 1;
    }
    return k;
}

string printMode(ii64 XY, i64 M) {
    vector<char> modes;
    while (M) {
        i64 M2 = M >> 1;
        if (M == 2) M2 = M;
        // cout << M << " "<< XY.first << " " << XY.second << endl;
        if (llabs(XY.first + M) + llabs(XY.second) <= M2) {
            modes.pb('L');
            XY.first += M;
        } else if (llabs(XY.first - M) + llabs(XY.second) <= M2) {
             modes.pb('R');
            XY.first -= M;
        } else if (llabs(XY.first) + llabs(XY.second + M) <= M2) {
            modes.pb('D');
            XY.second += M;
        } else if (llabs(XY.first) + llabs(XY.second - M) <= M2) {
            modes.pb('U');
            XY.second -= M;
        }

        M >>= 1;
    }

    if (XY.first == 1) {
         modes.pb('R');
    } else if (XY.first == -1) {
         modes.pb('L');
    }

    if (XY.second == 1) {
         modes.pb('U');
    } else if (XY.second == -1) {
        modes.pb('D');
    }

    string result = "";
    int l = (int)modes.size(), i;
    rrep(i, 0, l) result += modes[i];

    return result;
}

int count(i64 M) {
    int c = 0;
    while (!(M&1)) {
        M >>= 1;
        c++;
    }
    return c;
}

