typedef long long ll;
bool inv[1005], del[35];
std::pair<std::vector<ll>, std::vector<std::string> > work(int n, int *arr)
{
	for (int i = 0; i < n; i++)
	{
		if (arr[i] < 0)
		{
			arr[i] *= -1;
			inv[i] = true;
		}
		else
			inv[i] = false;
	}
	std::vector<ll> ans, real;
	std::vector<std::string> way(n), realway(n);
	if (arr[0] & 1 ^ 1)
	{
		ans.pb(1);
		for (int i = 0; i < n; i++)
			way[i] += '-';
	}
	for (int i = 0; i < 30; i++)
		ans.pb(1 << i);
	for (int i = 0; i < n; i++)
	{
		for (int j = 0; j < 30; j++)
		{
			if (j == 29 || (arr[i] / 2 & (1 << j)))
				way[i] += '+';
			else
				way[i] += '-';
		}
	}
	memset(del, false, sizeof(del));
	for (int i = 0; i < ans.size(); i++)
	{
		if (del[i])
			continue;
		for (int j = i + 1; j < ans.size(); j++)
		{
			if (del[j])
				continue;
			bool f = true;
			for (int x = 0; x < n && f; x++)
				f &= (way[x][i] ^ way[x][j]) == (way[0][i] ^ way[0][j]);
			if (f)
			{
				del[j] = true;
				if (way[0][i] ^ way[0][j])
					ans[i] -= ans[j];
				else
					ans[i] += ans[j];
			}
		}
	}
	for (int i = 0; i < ans.size(); i++)
	{
		if (del[i])
			continue;
		bool flg = ans[i] < 0;
		real.pb(ans[i] * (flg ? -1 : 1));
		for (int j = 0; j < n; j++)
			realway[j] += way[j][i] ^ (inv[j] ? ('+' ^ '-') : 0) ^ (flg ? ('+' ^ '-') : 0);
	}
	return {real, realway};
}
