const int MAXN = (1 << 20);

#define abs asdsa

int64_t abs(int64_t x) { return x > 0 ? x : -x; }

int n;
pair<int64_t, int64_t> a[MAXN];
set<int> p;

void read()
{
	cin >> n;
	for(int i = 0; i < n; i++)
	{
		cin >> a[i].first >> a[i].second;
		p.insert((abs(a[i].first) + abs(a[i].second)) % 2);	
	}
}

inline int b(int64_t x, int64_t p) { return (x >> p) & 1ll; }

void solve()
{
	if(p.size() != 1)
	{
		cout << -1 << endl;
		return;
	}

	vector<int64_t> d;
	vector<string> ans(n, "");
	if(b(a[0].first, 0) != b(a[0].second, 0))
	{
		d.push_back(1);
		for(int i = 0; i < n; i++)
		{
			a[i].first--;
			ans[i].push_back('R');
		}
	}

	int64_t pw = 1;
	for(int tms = 0; tms < 36; tms++, pw *= 2)
	{
		d.push_back(pw);
		for(int i = 0; i < n; i++)
		{
			if(a[i].first & 1)
			{
				if(b(a[i].first, 1) == b(a[i].second, 1))
				{
					a[i].first++;
					ans[i].push_back('L');
				}
				else
				{
					a[i].first--;
					ans[i].push_back('R');
				}
			}
			else
			{
				if(b(a[i].first, 1) == b(a[i].second, 1))
				{
					a[i].second++;
					ans[i].push_back('D');
				}
				else
				{
					a[i].second--;
					ans[i].push_back('U');
				}
			}

			a[i].first /= 2;
			a[i].second /= 2;
		}
	}

	d.push_back(pw);
	for(int i = 0; i < n; i++)
	{
		if(a[i].first == -1) ans[i].push_back('L');
		if(a[i].first == 1) ans[i].push_back('R');
		if(a[i].second == 1) ans[i].push_back('U');
		if(a[i].second == -1) ans[i].push_back('D');
	}

	cout << d.size() << endl;
	for(int64_t i: d) cout << i << " ";
	for(auto s: ans) cout << s << endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	read();
	solve();
	return 0;
}

