#include <bits/stdc++.h>
using namespace std;
int n,m;
const int N = 1200;
const int k = 33;
//const int offset = 0;
const int offset = 1000000000;
typedef long long ll;
int X[N], Y[N],bits[k][2];

char s[40];
int sn;

vector<ll> vec;

void test(int a, int b) {
    ll x = 0, y = 0;
    assert(sn == m);
    for (int i = 0; i < sn; i++) {
        ll v = vec[i];
        if (s[i] == 'L') x -= v;
        else if (s[i] == 'R') x += v;
        else if (s[i] == 'D') y -= v;
        else y += v;
    }
    assert(a == x && b == y);
}

void add(int j, int sign) {
    if (j == 0) {
        if (sign == -1) s[sn++] = 'L'; else s[sn++] = 'R';   
    }
    else {
        if (sign == -1) s[sn++] = 'D'; else s[sn++] = 'U'; 
    } 
}

void solve1(int i) {
    int *x = bits[i], *nx = bits[i+1];
    //printf("i=%d, x=(%d,%d),nx=(%d,%d),bits[i+1]=(%d,%d)\n",i,x[0],x[1],nx[0],nx[1],bits[i+1][0],bits[i+1][1]);
    for (int j = 0; j < 2; j++) {
        if (x[j] == 2) nx[j] += 1, x[j] = 0;
    }
    int j = x[1] == 1;

    bool op = (nx[0]^nx[1])&1;
    //printf("i=%d, j=%d,op=%d,x=(%d,%d),nx=(%d,%d)\n",i,j,op,x[0],x[1],nx[0],nx[1]);
    if (i + 1 == k - 1) op ^= 1;
    //printf("i=%d, j=%d,op=%d,x=(%d,%d),nx=(%d,%d)\n",i,j,op,x[0],x[1],nx[0],nx[1]);
    if (op) add(j, 1);
    else {
        add(j, -1);
        nx[j] += 1;
    }
}
void solve2(int i) {
    int *x = bits[i];
    if (x[0] == 0) add(0, 1), add(0, -1);
    else add(0, 1), add(1, 1);
}

void solve0(ll x, ll y) {
    sn = 0;
    memset(s,0,sizeof s);
    add(0, -1);
    add(1, -1);
    x += offset;
    y += offset;
    for (int i = 0; i < k; i++) {
        bits[i][0] = x >> i & 1;
        bits[i][1] = y >> i & 1;
        //printf("HaHa: %d, %d, %d, %d\n",x, i,bits[i][0], bits[i][1]);
    }

    int num = bits[0][0] * 2 + bits[0][1];
    if (num == 0) {
        add(0, -1);
        bits[0][0] = 1;
    }
    else if (num == 3) {
        add(0, 1);
        bits[0][0] = 0;
    }
    for (int i = 0; i < k - 1; i++) solve1(i);
    solve2(k - 1);
    printf("%s\n", s);
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d%d", X + i, Y + i);
    }
    bool isodd;

    isodd = (X[0] + Y[0]) & 1;
    for (int i = 1; i < n; i++) {
        if (((X[i] + Y[i]) & 1) != isodd) {
            puts("-1");
            return 0;
        }
    }

    vec.push_back(offset);
    vec.push_back(offset);

    if (!isodd) {
        vec.push_back(1);
    }
    for (int i = 0; i < k; i++) {
        vec.push_back(1LL<<i);
    }
    vec.push_back(1LL<<(k-1));
    m = vec.size();
    printf("%d\n",m);
    for (int i = 0; i < m; i++) {
        printf("%lld%c", vec[i], " \n"[i == m - 1]);
    }
    for (int i = 0; i < n; i++) {
        solve0(X[i], Y[i]);
        test(X[i], Y[i]);
    }
}

