    {
        cout << "-1\n";
        return 0;
    }
    d[1] = 1;
    for(int i = 2
        ; i <= m; i++)
        d[i] = d[i - 1] * 2;
    bool fix = false;
    if(abs(X[1] + Y[1]) % 2 == 0)
    {
        m++;
        d[m] = 1;
        fix = true;
    }
    cout << m << "\n";
    for(int i = 1; i <= m; i++)
        cout << d[i] << " ";
    cout << "\n";
