const int MAX = 36;
long long pow2[40];

void init() {
    pow2[0] = 1;
    for (int i=1; i<=MAX; ++i) {
        pow2[i] = pow2[i-1] * 2;
    }
}

void solve(long long X, long long Y, bool odd) {
    string s = "";
    for (int i=MAX; i>=0; --i) {
        long long ph = odd ? pow2[i]-1 : pow2[i]-2;
        int parm = pow2[i];
        if (!odd && i == 1) {
            ph = 1;
            parm = 1;
        }
        if (abs(X+parm) + abs(Y) <= ph) {
            X += parm;
            s = "L" + s;
        } else if (abs(X-parm) + abs(Y) <= ph) {
            X -= parm;
            s = "R" + s;
        } else if (abs(X) + abs(Y+parm) <= ph) {
            Y += parm;
            s = "D" + s;
        } else if (abs(X) + abs(Y-parm) <= ph) {
            Y -= parm;
            s = "U" + s;
        }
    }
    cout << s << endl;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    init();

    int N;
    cin >> N;

    vector<int> X(N), Y(N);
    int odd = 0, even = 0;
    for (int i=0; i<N; ++i) {
        cin >> X[i] >> Y[i];
        if (abs(X[i]+Y[i]) % 2 == 0) {
            even ++;
        } else {
            odd ++;
        }
    }

    if (even > 0 && odd > 0) {
        cout << -1 << endl;
        return 0;
    }

    cout << MAX << endl;
    for (int i=0; i<=MAX; ++i) {
        cout << pow2[i] << endl;
    }

    for (int i=0; i<N; ++i) {
        solve(X[i], Y[i], abs(X[i]+Y[i]) % 2);
    }

    return 0;
}

