                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "U";
                }

                XX = X;
                YY = Y - arms[i];
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "D";
                }
