    exit(0);
  }

  LL m = 39;
  vector<LL> d;
  for(LL i=0; i<m; ++i) d.emplace_back(1ll<<(m-i-1));
  if(!parity) d.emplace_back(1ll), ++m;

  cout << m << endl;
  for(auto i: d) cout << (i==d.front() ? "" : " ") << i;
  cout << endl;
  for(const auto& p: P) {
    auto x = p.x;
    auto y = p.y;
    for(auto i: d) {
      if(abs(x)<abs(y)) {
        if(y<0) {y += i; cout << "D";}
        else    {y -= i; cout << "U";}
      } else {
        if(x<0) {x += i; cout << "L";}
        else    {x -= i; cout << "R";}
      }
    }
    assert(x==0);
    assert(y==0);
    cout << endl;
  }
}

