vector<char> g(int c, int d) {
  assert(c % 2 != 0 && d % 2 != 0);
  //   op.assign(30, 'x');

  vector<char> op(30);

    for (int i=0,r=1<<29; i<30; ++i,r>>=1) {
    if (c > 0) {
      c -= r;
      if (d > 0) {
        op[i] = 'R';
        d -= r;
      } else {
        op[i] = 'U';
        d += r;
      }
    } else {
      c += r;
      if (d > 0) {
        op[i] = 'D';
        d -= r;
      } else {
        op[i] = 'L';
        d += r;
      }
    }
  }

  reverse(ALL(op));
  return op;
}

vector<char> f(int x, int y) {
  assert((x + y) % 2 != 0);
  return g(x + y, x - y);
}

void check(vi& arms, vector<char>& op, int expected_x, int expected_y) {
  int m = arms.size();
  assert(op.size() == m);
  int x = 0, y = 0;
  rep(i, m) {
    int a = arms[i];
    switch (op[i]) {
      case 'R':
        x += a;
        break;
      case 'L':
        x -= a;
        break;
      case 'U':
        y += a;
        break;
      case 'D':
        y -= a;
        break;
    }
  }
//   fprintf(stderr, "x=%d, expected=%d\n", x, expected_x);
//   fprintf(stderr, "y=%d, expected=%d\n", y, expected_y);
  assert(x == expected_x);
  assert(y == expected_y);
  //   fprintf(stderr, "ok.\n");
}

void even(int N, vi& x, vi& y) {
  vi arms;

  for (int i = 0, a = 1; i < 30; ++i, a *= 2) arms.pb(a);
  arms.pb(1);

  cout << arms.size() << endl;
  print_ar(arms);

  rep(i, N) {
    vector<char> op = f(x[i] - 1, y[i]);
    op.pb('R');
    cout << string(ALL(op)) << endl;
#ifdef DEBUG
    check(arms, op, x[i], y[i]);
#endif
  }
}
void odd(int N, vi& x, vi& y) {
  vi arms;

  for (int i = 0, a = 1; i < 30; ++i, a *= 2) arms.pb(a);

  cout << arms.size() << endl;
  print_ar(arms);

  rep(i, N) {
    vector<char> op = f(x[i], y[i]);
    cout << string(ALL(op)) << endl;
#ifdef DEBUG
    check(arms, op, x[i], y[i]);
#endif
  }
}

void solve(int N, vi& x, vi& y) {
  vi r(2, 0);
  rep(i, N) { r[abs(x[i] + y[i]) % 2]++; }
  if (r[0] == N) {
    even(N, x, y);
  } else if (r[1] == N) {
    odd(N, x, y);
  } else {
    cout << -1 << endl;
  }
}

