void pushAns(int i, int x, int y, int l) {
	if(x == 0 && y == 0) return;
	int k = -1;
	if (x-y > 0 && x+y > 0) k = 0;
	else if (x-y < 0 && x+y > 0) k = 1;
	else if (x-y < 0 && x+y < 0) k = 2;
	else k = 3;
	Ans[i].push_back(k);
	pushAns(i, x-cx[k]*l, y-cy[k]*l, l>>1);
}

