unsigned dis(dot a,dot b){
	return abs(a.x-b.x)+abs(a.y-b.y);
}
dot U(dot a,int len){
	a.y+=len;
	return a;
}
dot D(dot a,int len){
	a.y-=len;
	return a;
}
dot L(dot a,int len){
	a.x-=len;
	return a;
}
dot R(dot a,int len){
	a.x+=len;
	return a;
}
void go(int i,int z,dot &x){	
	unsigned x1=dis(a[z],U(x,1<<i)),x2=dis(a[z],D(x,1<<i)),x3=dis(a[z],L(x,1<<i)),x4=dis(a[z],R(x,1<<i));
	if (x1<=x2&&x1<=x3&&x1<=x4){
		putchar('U');
		x=U(x,1<<i);
	}
	else if (x2<=x3&&x2<=x4){
		putchar('D');
		x=D(x,1<<i);
	}
	else if (x3<=x4){
		putchar('L');
		x=L(x,1<<i);
	}
	else {
		putchar('R');
		x=R(x,1<<i);
	}
}
