int n,m;
ll x,y;
vector<pll> v;
ll dist[35];

string solve(ll x, ll y) {
    string res;
    // cout<<"For ("<<x<<","<<y<<")"<<endl;
    IFOR(i,m,1) {
        int s = dist[i]-1;
        if((abs(x-dist[i]) + abs(y)) <= s && (abs(x-dist[i]) + abs(y))%2 == 1) {
            res += 'R';
            x -= dist[i];
        } else if((abs(x) + abs(y-dist[i])) <= s && (abs(x) + abs(y-dist[i]))%2 == 1) {
            res += 'U';
            y -= dist[i];
        } else if((abs(x+dist[i]) + abs(y)) <= s && (abs(x+dist[i]) + abs(y))%2 == 1) {
            res += 'L';
            x += dist[i];
        } else {
            res += 'D';
            y += dist[i];
        }
        // cout<<x<<" "<<y<<endl;
    }
    if(x == 1) res += 'R', x-=1;
    else if(x == -1) res += 'L', x+=1;
    else if(y == 1) res += 'U', y-=1;
    else res += 'D', y+=1;
    // cout<<x<<" "<<y<<endl;
    // cout<<"------------------------------------"<<endl;
    return res;
}

