			return puts("-1"),0;
		while(v>1<<d)
			++d;
	}
	if(v1)
		for(i=1;i<=d;++i) p[i]=1<<i-1,q[i]=1<<i;
	else{
		p[1]=1;q[1]=2;
		for(i=2;i<=d+1;++i)
			p[i]=1<<i-2,q[i]=1<<i-1;
		++d;
	}
	printf("%d\n",d);
	for(i=1;i<=d;++i) printf("%d ",p[i]);
	puts("");
	for(i=1;i<=n;++i){
		x=ax[i];y=ay[i];
		for(j=d;j;--j)
			if(check(x-p[j],y,q[j-1]))
				x-=p[j],
				ans[j]='R';
			else if(check(x+p[j],y,q[j-1]))
				x+=p[j],
				ans[j]='L';
			else if(check(x,y-p[j],q[j-1]))
				y-=p[j],
				ans[j]='U';
			else
				y+=p[j], 
				ans[j]='D';
		ans[d+1]='\0';
