  int m;

  void set_m() {
    int a = abs(X[0]) + abs(Y[0]);
    rep(i, N) {
      int b = abs(X[i]) + abs(Y[i]);
      if (a % 2 != b % 2) throw exception();
    }
    m = 40 - (a % 2);
  }


  void solve() {
    cin >> N;
    X.resize(N);
    Y.resize(N);
    rep(i, N) cin >> X[i] >> Y[i];

    bool f1 = (-10 <= X.min() && X.max() <= 10); 
