			ll y2 = y + dy[o] * step;
			if (abs(x2) <= L && abs(y2) <= L) {
				if (who == -1) {
					who = o;
					bx = x2;
					by = y2;	
				} else {
					if (abs(bx) + abs(by) > abs(x2) + abs(y2)) {
						who = o;
						bx = x2;
