using namespace std;

const int MX = 30;

int pt2[MX];

int check(int x, int y, int k) {
    return abs(x) + abs(y) <= pt2[k] - 1;
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	#ifdef UTP
	freopen("input.txt", "r", stdin);
	#endif
	int n; cin >> n;
	vector<int> x(n), y(n);
	int ok = 1;
	for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        ok &= ((abs(x[i]) + abs(y[i])) % 2 == (abs(x[0]) + abs(y[0])) % 2);
	}
    if (!ok) {cout << -1 << endl; return 0; }
    for (int i = 0; i < MX; i++)
        pt2[i] = (1 << i);
    cout << MX << endl;
    if ((abs(x[0]) + abs(y[0])) % 2 == 0) cout << 1 << " ";
    for (int i = MX - 1; i >= 0; i--)
        cout << pt2[i] << " ";
    cout << endl;
    for (int j = 0; j < n; j++) {
        string ans;
        int cx = x[j], cy = y[j];
        if ((abs(cx) + abs(cy)) % 2 == 0) {
            ans.push_back('R');
            cx--;
        }
        for (int i = MX - 1; i >= 0; i--) {
            if (check(cx, cy + pt2[i], i)) {
                ans.push_back('D');
                cy += pt2[i];
            } else if (check(cx + pt2[i], cy, i)) {
                ans.push_back('L');
                cx += pt2[i];
            } else if (check(cx, cy - pt2[i], i)) {
                ans.push_back('U');
                cy -= pt2[i];
            } else if (check(cx - pt2[i], cy, i)) {
                ans.push_back('R');
                cx -= pt2[i];
            } else {
                assert(false);
            }
        }
        assert(cx == 0 && cy == 0);
        cout << ans << endl;
    }
	return 0;
}

#include<bits/stdc++.h>
#define MAX 1005
using namespace std;

int main(){
  int n, pls[MAX], mns[MAX], x, y, ev;
  scanf("%d", &n);
  for(int i = 0; i < n; i++){
    scanf("%d%d", &x, &y);
    if(!i) ev = (x+y+1)&1;
    if((x+y)&1 == ev){
      printf("-1\n");
      return 0;
    }
    pls[i] = (x+y)/2 + (1<<30);
    mns[i] = (x-y)/2 + (1<<30);
  }
  printf("%s", ev ? "32\n1 " : "31 ");
  for(int i = 0; i < 31; i++){
    printf("%d", (1<<i));
    printf("%s", i == 30 ? "\n" : " ");
  }
  for(int i = 0; i < n; i++){
    x = y = 0;
    if(ev){
      printf("L");
      x--;
    }
    for(int j = 0; j < 31; j++){
      bool p = pls[i] & (1<<j), m = mns[i] & (1<<j);
      printf("%c", p ? m ? 'R' : 'U' : m ? 'D' : 'L');
    }
    printf("\n");
  }
}

