			is_even = ((X + Y) % 2 == 0);
		}
		else {
			if (!(is_even == ((X + Y) % 2 == 0))) {
				cout << -1 << endl;
				return 0;
			}
		}
		U[i_arm] = (unsigned int)((((ll)X + Y) + maxu) / 2);
