	}

	int m_ans = m;
	if (is_even)
		m_ans++;
	cout << m_ans << endl;
	REP(j, m) {
		cout << (ll)pow(2, j) << " ";
	}
	if (is_even) {
		cout << 1;
	}
	cout << endl;
