class Solver {
 public:
  int n, len;
  vector<LL> x, y;
  vector<string> ans;
  Solver(LL n) : n(n), x(n), y(n), ans(n){};

  void solve() {
    for (int i = 0; i < n; ++i) {
      cin >> x[i] >> y[i];
      if (abs(x[i]) > 10 || abs(y[i]) > 10) assert(false);
    }
    for (int i = 1; i < n; ++i) {
      if ((abs(x[i]) + abs(y[i])) % 2 != (abs(x[0]) + abs(y[0])) % 2) {
        cout << -1 << endl;
        return;
      }
    }
    DBG(x, y)
    if ((x[0] + y[0]) % 2 == 0) {
      len = 40;
      cout << 40 << endl;
      for (int i = 0; i < 39; ++i) {
        cout << 1 << ' ';
      }
      cout << 1 << endl;
    } else {
      len = 39;
      cout << 39 << endl;
      for (int i = 0; i < 38; ++i) {
        cout << 1 << ' ';
      }
      cout << 1 << endl;
    }

    for (int i = 0; i < n; ++i) {
      ans[i] = calc(abs(x[i]), abs(y[i]));
    }
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < len; ++j) {
        if (x[i] < 0) {
          if (ans[i][j] == 'R') {
            ans[i][j] = 'L';
          } else if (ans[i][j] == 'L') {
            ans[i][j] = 'R';
          }
        }
        if (y[i] < 0) {
          if (ans[i][j] == 'U') {
            ans[i][j] = 'D';
          } else if (ans[i][j] == 'D') {
            ans[i][j] = 'U';
          }
        }
      }
      cout << ans[i] << endl;
    }
  }
  string calc(int a, int b) {
    string ret = "";
    for (int i = 0; i < a; ++i) {
      ret += 'R';
    }
    for (int i = 0; i < b; ++i) {
      ret += 'U';
    }
    for (int i = 0; i < (len - a - b) / 2; ++i) {
      ret += "LR";
    }
    return ret;
  }
};

