bool sub(map<ll,int> &mp, ll x,string L,string R,string &op1,string &op2) {
  ll cur = 0;
  while( mp[2] > 0 && llabs(cur-x) >= 2LL ) {
    --mp[2];
    if( x < 0LL ) cur -= 2LL, op2 += L;
    else          cur += 2LL, op2 += R;
  }
  if( !( llabs(cur-x) <= mp[1] ) ) return false;
  while( mp[1] && llabs(cur-x) != 0 ) {
    --mp[1];
    if( x < 0LL ) --cur, op1 += L;
    else          ++cur, op1 += R;
  }
  if( x != cur ) return false;
  return true;
}

bool check(vector<ll> &d,ll x,ll y,string &s) {
  map<ll,int>  mp;
  rep(i,(int)d.size()) ++mp[d[i]];
  s = "";
  string op2 = "";
  string op1 = "";
  if( !sub(mp,x,"L","R",op1,op2) ) return false;
  if( !sub(mp,y,"D","U",op1,op2) ) return false;
  if( !( mp[1] % 2 == 0 ) ) return false;

  if( !( mp[2] % 2 == 0 ) ) return false;
  while( mp[1] ) {
    assert( mp[1] >= 2 );
    op1 += "L";
    op1 += "R";
    mp[1] -= 2;
  }
  while( mp[2] ) {
    assert( mp[2] >= 2 );
    op2 += "L";
    op2 += "R";
    mp[2] -= 2;
  }
  s = op1 + op2;
  return true;
}

