void solveS(int N,vi& x,vi& y) {

    vi _cnt(2, 0);
    int lmax = 0;
    vi ls(N), rs(N);
    rep(i,N){
        int l = abs(x[i]) + abs(y[i]);                       
        ls[i] = l;
