        int rem = m;
        if (x[i] > 0) { // right
            rep(j, x[i]) putchar('R');
            rem -= x[i];
        } else if (x[i] < 0) { // left
          rep(j, -x[i]) putchar('L');
          rem += x[i];
        } else {
          //
        }
        if (y[i] > 0) { // up
          rep(j, y[i]) putchar('U');
          rem -= y[i];
        } else if (y[i] < 0) {  // down
          rep(j, -y[i]) putchar('D');
          rem += y[i];
        } else {
          //
        }
        assert(rem >= 0 && rem%2 == 0);
        for (int j=0; j<rem; j+=2) {
          putchar('R');
          putchar('L');
        }
        putchar('\n');
    }
}


