using namespace std;

typedef long long ll;
ll MOD = 1e9+7;

ll x[1000];
ll y[1000];
ll bit=0;
int arm[21];

int main()
{
	int n;
	int ans=0;
	cin>>n;
	for(int i=0;i<n;i++)
		cin>>x[i]>>y[i];

	bool f=true;
	//座標の合計の偶奇が一致しているかどうか調べる
	if(((ll)abs(x[0])+(ll)abs(y[0]))%2==0)
	{
		for(int i=0;i<n;i++)
		{
			if(((ll)abs(x[i])+(ll)abs(y[i]))%2!=0)
			{
				f=false;
				break;
			}
		}
	}else{
		for(int i=0;i<n;i++)
		{
			if(((ll)abs(x[i])+(ll)abs(y[i]))%2==0)
			{
				f=false;
				break;
			}
		}
	}
	//一致していなければ構成は無理
	if(!f)
	{
		cout<<-1<<endl;
		return 0;
	}
	//一致していれば必要なアーム数を求める
	fill(arm,arm+21,0);
	int armcnt=0;
	//and計算をして、必ず2本必要な場所を求める
	bit=(ll)abs(x[0])&(ll)abs(y[0]);
	for(int i=1;i<n;i++)
	{
		ll temp=(ll)abs(x[i])&(ll)abs(y[i]);
		bit=bit&temp;
	}
	for(int i=0;i<21;i++)
	{
		ll temp=bit&(ll)pow(2,i);
		if(temp>0)
		{
			arm[i]+=2;
			armcnt+=2;
		}
	}
	//xorとand計算をして、必ず1本必要な場所を求める
	bit=(ll)abs(x[0])^(ll)abs(y[0]);
	for(int i=1;i<n;i++)
	{
		ll temp=(ll)abs(x[i])^(ll)abs(y[i]);
		bit=bit&temp;
	}
	for(int i=0;i<21;i++)
	{
		ll temp=bit&(ll)pow(2,i);
		if(temp>0)
		{
			arm[i]+=1;
			armcnt+=1;
		}
	}
	//xor計算をそれぞれして、不足分を補う
	for(int i=0;i<n;i++)
	{
		ll bit=(ll)abs(x[i])^(ll)abs(y[i]);
		//それぞれのbitについて調べる
		for(int i=0;i<21;i++)
		{
			ll temp=bit&(ll)pow(2,i);
			if(temp>0)
			{
				//足りない場合は追加する
				//追加の仕方はd/2を2本
				if(arm[i]%2==0 && arm[i-1]<3)
				{
					arm[i-1]+=2;
					armcnt+=2;
				}
			}
		}
	}
	//ここから答え
	//armcntが40超えてたら構成は無理
	if(armcnt>40)
	{
		cout<<-1<<endl;
		return 0;
	}
	//それ以外ならできるので復号
	cout<<armcnt<<endl;
	for(int i=0;i<21;i++)
	{
		ll leng=(ll)pow(2,i);
		for(int j=0;j<arm[i];j++)
		{
			cout<<leng;
			cout<<" ";
		}
