inline void construct(LL x, LL y)
{
	static vector<char> s;
	s.clear();

	for(int i = m; i >= 1; --i)
	{
		if(abs(x) > abs(y)) { if(x > 0) s.push_back('R'), x -= d[i]; else s.push_back('L'), x += d[i]; }
