using namespace std;

pair<vector<int>, vector<string> > solve(int n, vector<pair<int, int> > const & ps) {
    bool parity = (ps[0].first + ps[0].second) % 2;
    for (auto p : ps) {
        if ((p.first + p.second) % 2 != parity) {
            return make_pair(vector<int>(), vector<string>());
        }
    }

    // construct the graph
    vector<int> ds;
    for (int d = 1 << 30; d >= 2; d >>= 1) {
        ds.push_back(d);
    }
    REP (i, 2) {
        ds.push_back(1);
    }
    if (parity) {
        ds.push_back(1);
    }

    // construct commands
    vector<string> ws;
    for (auto p : ps) {
        int x, y; tie(x, y) = p;
        string w;
        for (int d : ds) {
            if (x + y >= 0 and x - y >= 0) {
                w += 'R';
                x -= d;
            } else if (x + y >= 0) {
                w += 'U';
                y -= d;
            } else if (x - y >= 0) {
                w += 'D';
                y += d;
            } else {
                w += 'L';
                x += d;
            }
        }
        assert (x == 0 and y == 0);
        ws.push_back(w);
    }

    return make_pair(ds, ws);
}

