}

void get_seq(ll x, ll y, ll step)
{
	if(!step) step = 1;
	ll dr = dis(x-step, y), dl = dis(x+step, y);
	ll du = dis(x, y-step), dd = dis(x, y+step);
	ll mnd = min(min(dl, dr), min(dd, du));
	if(step==1 && !x && !y) putchar('\n');
	else if(mnd == dr) putchar('R'), get_seq(x-step, y, step/2);
	else if(mnd == dl) putchar('L'), get_seq(x+step, y, step/2);
	else if(mnd == du) putchar('U'), get_seq(x, y-step, step/2);
	else if(mnd == dd) putchar('D'), get_seq(x, y+step, step/2);
	else assert(0);
}

