ll dis(ll x1, ll y1, ll x2, ll y2){
    return abs(x1-x2) + abs(y1-y2);
}

int main(){
    int n;
    cin>>n;

    vector<array<ll,2>> arr(n);
    ll p = -1;
    int f = 0;
    for(int i = 0; i < n; i++){
        cin>>arr[i][0]>>arr[i][1];
        if(p == -1){
            p = (arr[i][0]+arr[i][1])%2;
            continue;
        }
        if((arr[i][0]+arr[i][1])%2 != p){
            f = 1;
        }
    }

    if(f) {
        cout<<-1;
        return 0;
    }

    ll dx[] = {1,0,-1,0};
    ll dy[] = {0,1,0,-1};
    char mv[] = {'R','U','L','D'};

    vector<ll> D;

    for(int i = 30; i >= 0; i--){
        D.push_back(1LL<<i);
    }
    if(!p) D.push_back(1LL);

    ll INF = 1e18;
    cout<<D.size()<<endl;
    for(int i = 0; i < D.size(); i++){
        cout<<D[i]<<" ";
    }
    cout<<endl;
    for(auto pt : arr){
        ll X = pt[0];
        ll Y = pt[1];
        string s;
        ll x = 0, y = 0;
        for(int i = 0; i < (int)D.size(); i++){
            ll n = INF;
            int bst = 0;
            for(int j = 0; j < 4; j++){
                ll tx = x + dx[j]*(D[i]);
                ll ty = y + dy[j]*(D[i]);
                ll cur = dis(tx,ty,X,Y);
                //ll cur = abs(X - dx[j]*(D[i])) + abs(Y - dy[j]*(D[i]));
                if(cur<n)
                    n = cur,bst = j;
            }
            x += D[i]*dx[bst];
            y += D[i]*dy[bst];
            //X -= dx[bst]*(D[i]);
            //Y -= dy[bst]*(D[i]);
            s+=mv[bst];
        }
        cout<<s<<endl;
    }

}

