int N;
vector<lint> a(40);
void solve(lint xpy, lint xmy)
{
    for (auto d : a)
    {
        if (xpy > 0 && xmy > 0)
        {
            xpy -= d; xmy -= d;
            cout << "R";
        }
        else if (xpy > 0 && xmy <= 0)
        {
            xpy -= d; xmy += d;
            cout << "U";
        }
        else if (xpy <= 0 && xmy > 0)
        {
            xpy += d; xmy -= d;
            cout << "D";
        }
        else if (xpy <= 0 && xmy <= 0)
        {
            xpy += d; xmy += d;
            cout << "L";
        }
    }
    cout << endl;
}

