using ll = long long;
constexpr int DIG = 39;
int main()
{
    int N;
    std::cin >> N;
    using P = std::pair<ll, ll>;
    std::vector<P> p(N);
    for (int i = 0; i < N; i++) { std::cin >> p[i].first >> p[i].second; }
    const ll S = std::abs(p[0].first) + std::abs(p[0].second);
    for (int i = 1; i < N; i++) {
        if (S % 2 != (std::abs(p[i].first) + std::abs(p[i].second)) % 2) { return std::cout << -1 << std::endl, 0; }
    }
    const ll D = (1LL << DIG) - 1;
    const ll NUM = DIG + (S % 2 == 1 ? 0 : 1);
    std::cout << NUM << std::endl;
    for (int i = 0; i < DIG; i++) { std::cout << (1LL << i) << " "; }
    if (S % 2 == 0) { std::cout << 1 << " "; }
    std::cout << std::endl;
    for (int i = 0; i < N; i++) {
        using Q = std::pair<ll, ll>;
        std::vector<Q> log(NUM);
        ll x = p[i].first, y = p[i].second;
        if (x == 0 and y == 0) {
            for (int i = 0; i < DIG - 1; i++) { std::cout << "L"; }
            std::cout << "RL" << std::endl;
            continue;
        }

        if (S % 2 == 0) {
            if (x != 0) {
                x += (x < 0 ? 1 : -1);
                log[NUM - 1] = {0, (x < 0 ? -1 : 1)};
            } else {
                y += (y < 0 ? 1 : -1);
                log[NUM - 1] = {1, (y < 0 ? -1 : 1)};
            }
        }
        ll X = std::abs(x), Y = std::abs(y);
        const ll S = X + Y;
        ll P = (D + S) / 2, M = D - P;
        std::bitset<DIG + 1> ng(M), ok(P);
        for (int i = 0; i < DIG; i++) {
            if (ng[i] and ((X >> i) & 1)) { log[i] = {0, -1 * (x < 0 ? -1 : 1)}, X += (1LL << i); }
            if (ng[i] and ((Y >> i) & 1)) { log[i] = {1, -1 * (y < 0 ? -1 : 1)}, Y += (1LL << i); }
            if (ok[i] and ((X >> i) & 1)) { log[i] = {0, 1 * (x < 0 ? -1 : 1)}, X -= (1LL << i); }
            if (ok[i] and ((Y >> i) & 1)) { log[i] = {1, 1 * (y < 0 ? -1 : 1)}, Y -= (1LL << i); }
        }
        for (int i = 0; i < NUM; i++) {
            if (log[i].first == 0) {
                if (log[i].second == 1) {
                    std::cout << "R";
                } else {
                    std::cout << "L";
                }
            } else {
                if (log[i].second == 1) {
                    std::cout << "U";
                } else {
                    std::cout << "D";
                }
            }
        }
        std::cout << std::endl;
    }
    return 0;
}

