void go(LL x, LL y, LL p) {
    if(!x && !y) return;
    LL step = 1LL << p;
    LL nx, ny;
    for(int dir = 0; dir < 4; dir++) {
        nx = x + dx[dir] * step;
        ny = y + dy[dir] * step;
        if(calc(nx, ny) <= p - 1) {
            ans[len++] = ch[dir ^ 1];
            go(nx, ny, p - 1);
            break;
        }
    }
}

