				int c = 0;
				REP(5, k) {
					if (m % 2)
						c += 1 << k;
					else
						c -= 1 << k;
					m /= 2;
				}
				if (c == y[i]) {
					m = j;
					REP(5, k) {
						if (m % 2)
							cout << 'U';
						else cout << 'D';
						m /= 2;
					}
				}
			}
			cout << endl;
		}
	}
	return 0;
}

