const int MAXQ = 1000;
const int MAXM = 40;

int nq;
int qx[MAXQ], qy[MAXQ];

int v[MAXM], nv;
char qans[MAXQ][MAXM + 1];

int cx[MAXQ], cy[MAXQ];

void make() {

}

char get(int sgn, int axis) { return axis == 1 ? sgn == +1 ? 'R' : 'L' : sgn == +1 ? 'U' : 'D'; }
bool solve() {
	int par = (qx[0] + qy[0]) % 2 == 0 ? 0 : 1;
	FOR(i, 1, nq) { int cur = (qx[i] + qy[i]) % 2 == 0 ? 0 : 1; if (cur != par) return false; }

	nv = 0; int mlt = 1;
	REP(i, nq) cx[i] = qx[i], cy[i] = qy[i];
	if (par == 0) {
		int a = nv; v[nv++] = 1; int b = nv; v[nv++] = mlt; mlt *= 2;
		REP(i, nq) {
			int su = +1, sv = (cx[i] + cy[i]) % 4 == 0 ? +1 : -1;
			int u = 1, v = cx[i] % 2 == 0 ? 1 : 0;
			//printf("(%d,%d) -> su=%d u=%d sv=%d v=%d -> (%d,%d)\n", cx[i], cy[i], su, u, sv, v, cx[i] + su*u + sv*v, cy[i] + su*(1 - u) + sv*(1 - v));
			cx[i] += su*u + sv*v, cy[i] += su*(1 - u) + sv*(1 - v);
			assert(cx[i] % 2 == 0 && cy[i] % 2 == 0 && (cx[i] + cy[i]) % 4 != 0);
			qans[i][a] = get(-su, u), qans[i][b] = get(-sv, v);
			cx[i] /= 2; cy[i] /= 2;
		}
	}
	while(true) {
		bool done = true; REP(i, nq) if (abs(cx[i] + cy[i]) > 1) done = false; if (done) break;
		int a = nv; v[nv++] = mlt; mlt *= 2;
		REP(i, nq) {
			int su = (cx[i] + cy[i] - 1) % 4 == 0 ? +1 : -1, u = cx[i] % 2 != 0 ? 1 : 0;
			//printf("(%d,%d) -> su=%d u=%d -> (%d,%d)\n", cx[i], cy[i], su, u, cx[i] + su*u, cy[i] + su*(1 - u));
			cx[i] += su*u, cy[i] += su*(1 - u);
			assert(cx[i] % 2 == 0 && cy[i] % 2 == 0 && (cx[i] + cy[i]) % 4 != 0);
			qans[i][a] = get(-su, u);
			cx[i] /= 2, cy[i] /= 2;
		}
	}
	{
		int a = nv; v[nv++] = mlt; mlt *= 2;
		REP(i, nq) {
			int su = (cx[i] + cy[i] - 1) % 4 == 0 ? -1 : +1, u = cx[i] % 2 != 0 ? 1 : 0;
			//printf("(%d,%d) -> su=%d u=%d -> (%d,%d)\n", cx[i], cy[i], su, u, cx[i] + su*u, cy[i] + su*(1 - u));
			cx[i] += su*u, cy[i] += su*(1 - u);
			assert(cx[i] == 0 && cy[i] == 0);
			qans[i][a] = get(-su, u);
			cx[i] /= 2, cy[i] /= 2;
		}
	}

	REP(i, nq) qans[i][nv] = '\0';
	return true;
}

void run() {
	scanf("%d", &nq); REP(i, nq) scanf("%d%d", &qx[i], &qy[i]);

	if (!solve()) { printf("-1\n"); return; }
	printf("%d\n", nv); REP(i, nv) { if (i != 0) printf(" "); printf("%d", v[i]); } puts("");
	REP(i, nq) printf("%s\n", qans[i]);
}

int main() {
	run();
	return 0;
}

