typedef long long ll;

string Solve(ll x, ll y, ll at) {
  if (at < 0) return "";
  assert(abs(x) + abs(y) <= (1 << (at + 1)) - 1);
  int r = (1 << at) - 1;
  int d = 1 << at;
  if (abs(x - d) + abs(y) <= r) return Solve(x - d, y, at - 1) + "R";
  if (abs(x + d) + abs(y) <= r) return Solve(x + d, y, at - 1) + "L";
  if (abs(x) + abs(y - d) <= r) return Solve(x, y - d, at - 1) + "U";
  if (abs(x) + abs(y + d) <= r) return Solve(x, y + d, at - 1) + "D";
  assert(false);
}

int main()
{
  int n;
  cin >> n;
  vector<int> x(n), y(n);
  for (int i = 0; i < n; ++i) {
    cin >> x[i] >> y[i];
  }
  for (int i = 0; i < n; ++i) {
    if ((x[i] + y[i] + x[0] + y[0]) % 2 == 1) {
      cout << -1 << endl;
      return 0;
    }
  }

  bool odd = (x[0] + y[0]) % 2 == 0;
  cout << 30 + odd << endl;
  if (odd) cout << "1 ";
  for (int i = 0; i < 30; ++i) {
    cout << (1 << i) << " ";
  }
  cout << endl;

  for (int i = 0; i < n; ++i) {
    string result = Solve(x[i] - odd, y[i], 29);
    if (odd) result = "R" + result;
    cout << result << endl;
  }

  return 0;
}

