        if (xx[i] != 0) {
            d.push_back(abs(xx[i]) / 2);
            d.push_back(abs(xx[i]) / 2);
        }
        if (yy[i] != 0) {
            d.push_back(abs(yy[i]) / 2);
            d.push_back(abs(yy[i]) / 2);
        }
    }

