        stringstream res;
        for (int j = 0; j < N; j++) {
            if (i != j) {
                if (xx[j] != 0) res << "LR";
                if (yy[j] != 0) res << "LR";
            } else {
                if (xx[j] < 0) res << "LL";
                if (xx[j] > 0) res << "RR";
                if (yy[j] < 0) res << "DD";
                if (yy[j] > 0) res << "UU";
            }
        }
        if (x[i] != xx[i]) {
            if (even)
                res << "UR";
            else
                res << "R";
        } else {
            if (even)
                res << "LR";
            else
                res << "U";
        }

        instr[i] = res.str();
    }

    for (int i = 0; i < N; i++) {
        assert(instr[i].size() == d.size());
        int px = 0, py = 0;
        for (int j = 0; j < d.size(); j++) {
            char c = instr[i][j];
            if (c == 'U') py += d[j];
            else if (c == 'D') py -= d[j];
            else if (c == 'R') px += d[j];
            else px -= d[j];
        }
        assert(px == x[i]);
        assert(py == y[i]);
    }

    cout << d.size() << "\n";
    for (int v : d)
        cout << v << " ";
    cout << "\n";
    for (string s : instr)
        cout << s << "\n";

    return 0;
}

