char instr(ll xp, ll yp) {
    if(xp == 1 && yp == 1) return 'U';
    if(xp == 1 && yp == 0) return 'R';
    if(xp == 0 && yp == 1) return 'L';
    if(xp == 0 && yp == 0) return 'D';
    assert(false);
}

bool solve() {
    ll N;
    cin >> N;
    V<PLL> XY(N);
    V<ll> last_one;
    bool is_zero = 0;
    for(PLL &p : XY) {
        ll x, y;
        cin >> x >> y;
        p = PLL(x, y);
        for(ll c : { abs(x - y), abs(x + y) }) {
            for(ll i = 0; i < 40; i++) {
                if(c == 0) {
                    is_zero = 1;
                    break;
                }
                if(c & (1ll << i)) {
                    last_one.push_back(i);
                    break;
                }
            }
        }
    }
    sort(ALL(last_one));
    auto ite = unique(ALL(last_one));
    last_one.erase(ite, last_one.end());
    if(is_zero && last_one[0] == 0) return 0;
    if(last_one.size() + is_zero >= 3) return 0;
    if(last_one.size() == 2 && last_one[0] + 1 != last_one[1]) return 0;
    V<ll> D;
    for(ll i = 32; i >= last_one[0]; i--) D.push_back(1ll << i);
    if(last_one.size() + is_zero >= 2) for(ll i = 0; i < 2; i++) D.push_back(1ll << (last_one[0] - 1));
    V<string> S;
    for(ll i = 0; i < N; i++) {
        ll nowx = XY[i].first - XY[i].second;
        ll nowy = XY[i].second + XY[i].second;
        DEBUG(nowx);
        DEBUG(nowy);
        string s;
        for(ll d : D) {
            bool xp = (nowx >= 0);
            bool yp = (nowy >= 0);
            if(xp) nowx -= d;
            else   nowx += d;
            if(yp) nowy -= d;
            else   nowy += d;
            s += instr(xp, yp);
        }
        DEBUG(nowx);
        DEBUG(nowy);
        DEBUG_SEPARATOR_LINE;
        S.push_back(s);
    }
    cout << D.size() << endl;
    for(ll i = 0; i < D.size(); i++) cout << D[i] << " \n"[i + 1 == D.size()];
    for(const auto &s : S) cout << s << endl;
    return 1;
}

int main() {
    if(!solve()) cout << -1 << endl;
    return 0;
}

