      return 0;
    }
  }

  long long d[40];

  int p = 0;
  if(tmp == 0){
    d[0] = 1;
    p++;
  }
  d[p] = 1;

  int m = 33;

  for(int i = p+1;i < m-1;i++){
    d[i] = d[i-1]*2;
  }

  cout << m << endl;
  for(int i = 0;i < m-1;i++){
    cout << d[i];
    if(i != m-1) cout << " ";
