    stack<char> st;

    long long nx, ny;
    nx = x[i];
    ny = y[i];
    if(tmp == 0) nx++;

    for(int i = 31;i >= (1-tmp);i--){
      long long t = nx + d[i];
      if(abs(t) + abs(ny) > d[i]){
        t = nx - d[i];
        if(abs(t)+abs(ny) > d[i]){
          t = ny+d[i];
          if(abs(t) + abs(nx) > d[i]){
            t = ny-d[i];
            ny = t;
            st.push('U');
