        cin >> X >> Y;
        if(!i) {
            mod = (X + Y) & 1;
        } else {
            if(mod != ((X + Y) & 1)) {
                cout << -1 << endl;
                return 0;
            }
        }
        i64 V = X + Y + S;
        i64 W = X - Y + S;
        string w = "";
        for(int i = 0; i < M; i++) {
            int a = (V >> (i + 1)) & 1, b = (W >> (i + 1)) & 1;
            char c;
            if(a && b) { // Right
                c = 'R';
            } else if(a && !b) { // Up
                c = 'U';
            } else if(b && !a) { // Down
                c = 'D';
            } else { // Left
                c = 'L';
            }
            w.push_back(c);
        }
        ans.push_back(w);
    }
    cout << M << endl;
    for(int i = 0; i < M; i++) {
        cout << (i ? " " : "") << (1ll << i);
    }
    cout << endl;
    for(auto a : ans) {
