    // 実際はd[k] = 2^kで-d[k]かd[k]を選択だが,
    // 下駄を履かせてd[k] = 2^(k+1)で0かd[k]を選択する
    // さらに2で割ることで0か2^kを選択するようにする
    cout << 36 - parity << endl;
    for (int k = 0; k < 35; ++k) {
        cout << (1LL << k) << " ";
    }
    if (parity == 0) cout << 1;
    cout << endl;

    // (X, Y) -> (X - Y, X + Y)に変換
    // さらに2^35-1だけ下駄を履かせ, 2で割る
    for (int i = 0; i < N; ++i) {
        ll tmp = X[i];
        X[i] -= Y[i];
        Y[i] += tmp;

        X[i] += (1LL << 35) - 1;
        X[i] /= 2;
        Y[i] += (1LL << 35) - 1;
        Y[i] /= 2;
    }

    // 各指示に対応する変化
    // L -> -X, -Y  R -> +X, +Y
    // U -> -X, +Y  D -> +X, -Y

    string order = "LDUR";
    for (int i = 0; i < N; ++i) {
        for (int k = 0; k < 35; ++k) {
            int kind = 0;
            if ((X[i] >> k) & 1) kind += 1;
            if ((Y[i] >> k) & 1) kind += 2;
            cout << order[kind];
        }
        if (parity == 0) cout << "L";
        cout << endl;
    }
    return 0;
}

