const int SIZE = 1e6+10;
int x[SIZE],y[SIZE];
int len[SIZE],ln;
int dx[4]={1,0,-1,0};
int dy[4]={0,1,0,-1};
char c[5]="LDRU";
void solve(int x,int y){
    REP(i,ln){
        PLL res;
        LL mi=1e18;
        int id=-1;
        REP(j,4){
            PLL nxt=MP(x+dx[j]*len[i],y+dy[j]*len[i]);
            if(abs(nxt.F)+abs(nxt.S)<mi){
                id=j;
                mi=abs(nxt.F)+abs(nxt.S);
                res=nxt;
            }
        }
        x=res.F;
        y=res.S;
        _W(c[id]);
    }
    assert(x==0&&y==0);
    W("");
}
int main(){
    int n;
    R(n);
    int ty=-1;
    REP(i,n){
        R(x[i],y[i]);
        if(ty==-1)ty=(x[i]+y[i])&1;
        else{
            if(((x[i]+y[i])&1)!=ty){
                W(-1);
                return 0;
            }
        }
    }
    REP(i,10-ty)len[ln++]=1;
    REPP(i,1,31)len[ln++]=1<<i;
    reverse(len,len+ln);
    W(ln);
    W(VI(len,len+ln));
    REP(i,n){
        solve(x[i],y[i]);
    }
    return 0;
}

