using namespace std;

const int MX = 30;

int pt2[MX];

int check(int x, int y, int k) {
    return abs(x) + abs(y) <= pt2[k] - 1;
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	#ifdef UTP
	freopen("input.txt", "r", stdin);
	#endif
	int n; cin >> n;
	vector<int> x(n), y(n);
	int ok = 1;
	for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        ok &= ((abs(x[i]) + abs(y[i])) % 2 == (abs(x[0]) + abs(y[0])) % 2);
	}
    if (!ok) {cout << -1 << endl; return 0; }
    int even = (abs(x[0]) + abs(y[0])) % 2 == 0;
    for (int i = 0; i < MX; i++)
        pt2[i] = (1 << i);
    cout << MX + even << endl;
    if (even) cout << 1 << " ";
    for (int i = MX - 1; i >= 0; i--)
        cout << pt2[i] << " ";
    cout << endl;
    for (int j = 0; j < n; j++) {
        string ans;
        int cx = x[j], cy = y[j];
        if (even) {
            ans.push_back('R');
            cx--;
        }
        for (int i = MX - 1; i >= 0; i--) {
            if (check(cx, cy + pt2[i], i)) {
                ans.push_back('D');
                cy += pt2[i];
            } else if (check(cx + pt2[i], cy, i)) {
                ans.push_back('L');
                cx += pt2[i];
            } else if (check(cx, cy - pt2[i], i)) {
                ans.push_back('U');
                cy -= pt2[i];
            } else if (check(cx - pt2[i], cy, i)) {
                ans.push_back('R');
                cx -= pt2[i];
            } else {
                assert(false);
            }
        }
        assert(cx == 0 && cy == 0);
        cout << ans << endl;
    }
	return 0;
}

