const int dx[] = {-1, 0, 1, 0};
const int dy[] = {0, 1, 0, -1};
const char *str = "LURD";

void Solve(li x, li y, int id) {
  // printf("solve %lld %lld\n", x, y);
  if (id == ans.size()) {
    if (x != 0 || y != 0) throw;
    return;
  }

  int best = -1;
  li min_d = 1e18, d = ans[id];

  for (int i = 0; i < 4; ++i) {
    li new_d = abs(x - d * dx[i]) + abs(y - d * dy[i]);
    if (new_d < min_d) min_d = new_d, best = i;
  }

  putchar(str[best]);
  x -= d * dx[best];
  y -= d * dy[best];

  Solve(x, y, id + 1);
}

