using namespace std;

const int MAXN = 1007;

pair <int, int> a[MAXN];

void solve(int x, int y) {
    string ans;

    if (0 <= x) {
        for (int i = 0; i < x; ++i) ans += 'R';
    }
    else {
        for (int i = 0; i < abs(x); ++i) ans += 'L';
    }
    if (x % 2 == 0) {
        for (int i = 0; i < (20 - abs(x)) / 2; ++i) ans += "LR";
    }
    else {
        for (int i = 0; i < (19 - abs(x)) / 2; ++i) ans += "LR";
    }

    if (0 <= y) {
        for (int i = 0; i < y; ++i) ans += 'U';
    }
    else {
        for (int i = 0; i < abs(y); ++i) ans += 'D';
    }
    if (y % 2 == 0) {
        for (int i = 0; i < (20 - abs(y)) / 2; ++i) ans += "DU";
    }   
    else {
        for (int i = 0; i < (19 - abs(y)) / 2; ++i) ans += "DU";
    }

    if (x % 2 && y % 2) ans += "LR";

    cout << ans << '\n';
}

