        ch=getchar();
    if(ch=='-'){
        flagg=-1;
        ch=getchar();
    }
    while(ch>='0'&&ch<='9'){
        xx=xx*10+ch-'0';
        ch=getchar();
    }
    return xx*flagg;
}
void pus(long long xx,long long flagg){
    if(xx<0){
        putchar('-');
        xx=-xx;
    }
    if(xx>=10)
        pus(xx/10,0);
    putchar(xx%10+'0');
    if(flagg==1)
        putchar(' ');
    if(flagg==2)
        putchar('\n');
    return;
}
long long n,i,x[1005],y[1005],flag;
void gz(long long u,long long v,long long w){
	if(w<0)
		return;
	if(abs(u)>abs(v)){
		if(u>0){
			putchar('R');
			gz(u-(1LL<<w),v,w-1);
		}
		else{
			putchar('L');
			gz(u+(1LL<<w),v,w-1);
		}
	}
	else{
		if(v>0){
			putchar('U');
			gz(u,v-(1LL<<w),w-1);
		}
		else{
			putchar('D');
			gz(u,v+(1LL<<w),w-1);
		}
	}
	if(w==0)
		putchar('\n');
}
