void play2() {
	if (vec[0] == 'A') {
		vec[0] = 'B';
		return;
	}

	if (vec.back() == 'B') {
		vec.back() = 'A';
	}
	for (int i = 1; i < vec.size(); i++) {
		if (vec[i - 1] == vec[i]) {
			if (vec[i - 1] == 'A') {
				vec[i - 1] = 'B';
			}
			else {
				vec[i - 1] = 'A';
			}
		}
	}
}

void play() {
	if (vec[0] == 'A') {
		vec[0] = 'B';
		return;
	}
	ll x = 0, side = 1;
	while (x >= 0 && x < vec.size()) {
		if (side == 1) {
			if (vec[x] == 'A') {
				side = 0;
				vec[x] = 'B';
				x--;
			}
			else {
				side = 1;
				vec[x] = 'A';
				x++;
			}

		}
		else {
			if (vec[x] == 'A') {
				side = 1;
				vec[x] = 'B';
				x++;
			}
			else {
				side = 0;
				vec[x] = 'A';
				x--;
			}
		}
	}

	/*for (auto cur : vec) cout << cur;
	if (x < 0) {
		cout << " front";
