int dist(int x, int y, int tx, int ty) {
  return abs(x - tx) + abs(y - ty);
}

int main() {
  scanf("%d", &n);
  int sig = 0, par = 0;
  for (int i = 1; i <= n; i++) {
    scanf("%d %d", &x[i], &y[i]);
    sig |= ((x[i] ^ y[i]) & 1);
    par |= !((x[i] ^ y[i]) & 1);
  }
  if (sig && par) {
    puts("-1");
    return 0;
  }
  if (par) {
    printf("32\n1 ");
  } else {
    printf("31\n");
  }
  for (int i = 30; i >= 0; i--) {
    printf("%d ", (int)pow(2, i));
  }
  puts("");
  for (int i = 1; i <= n; i++) {
    int sx = 0, sy = 0;
    if (par) {
      putchar('L');
      sx--;
    }
    for (int j = 30; j >= 0; j--) {
      for (int k = 0; k < 4; k++) {
        int nx = sx + dx[k] * pow(2, j);
        int ny = sy + dy[k] * pow(2, j);
        if (dist(nx, ny, x[i], y[i]) <= pow(2, j) - 1) {
          sx = nx;
          sy = ny;
          putchar(dir[k]);
          break;
        }
      }
    }
    puts("");
  }
  return 0;
}

