typedef enum {
  Left = 'L',
  Right = 'R',
  Up = 'U',
  Down = 'D',
} Mode;

class Point {
  public:
    Point() = default;
    Point(int _x, int _y) { x = _x; y = _y; }
    int x;
    int y;
    int manhattan() const { return abs(x) + abs(y); }
};

int ngoal;
vector<Point> goal;

bool has_smaller_manhattan(const Point& a, const Point& b)
{
  return a.manhattan() < b.manhattan();
}

bool is_solvable(const vector<Point>& g)
{
  bool parity = g.at(0).manhattan() % 2 == 0;
  for (int i = 1; i < (int)g.size(); i++) {
    if (parity != (g.at(i).manhattan() % 2 == 0)) {
      return false;
    }
  }
  return true;
}

int main()
{
  cin >> ngoal;
  goal.resize(ngoal);
  for (int i = 0; i < ngoal; i++) {
    cin >> goal.at(i).x >> goal.at(i).y;
  }
  if (!is_solvable(goal)) {
    cout << "-1" << endl;
    return 0;
  }

  // print arm
  int len = max_element(goal.begin(), goal.end(), has_smaller_manhattan)->manhattan();
  cout << len << '\n';
  cout << '1';
  for (int i = 1; i < len; i++) {
    cout << " 1";
  }
  cout << '\n';

  for (const auto& g : goal) {
    int x = g.x;
    int y = g.y;
    int cnt = 0;
    while (0 < x) {
      cout << 'R';
      x--;
      cnt++;
    }
    while (x < 0) {
      cout << 'L';
      x++;
      cnt++;
    }
    while (0 < y) {
      cout << 'U';
      y--;
      cnt++;
    }
    while (y < 0) {
      cout << 'D';
      y++;
      cnt++;
    }
    while (cnt < len) {
      cout << "UD";
      cnt += 2;
    }
    cout << '\n';
    assert(cnt == len);
  }
  return 0;
}

