      continue;
    }
    int cnt = 0;
    for (int k = 0; k < (int)s.size(); ++k) {
      if (s[k] != '*') {
        continue;
      }
      if (ans[k] == j) {
        s[k] = d[v > 0];
        ++cnt;
      }
      if (cnt == 1) {
        break;
      }
    }
    if (cnt == 0) {
      for (int k = 0; k < (int)s.size(); ++k) {
        if (s[k] != '*') {
          continue;
        }
        if (ans[k] == j - 1) {
          s[k] = d[v > 0];
          ++cnt;
        }
        if (cnt == 2) {
          break;
        }
      }
      //assert(cnt == 2);
    }
  }
}

