const double pi = acos(-1);

struct Point {
    typedef lint T;
    T x, y;

    Point() {}

    Point(T x, T y): x(x), y(y) {}

    Point operator +(Point other) const {
        return Point(x + other.x, y + other.y);
    }

    Point operator -(Point other) const {
        return Point(x - other.x, y - other.y);
    }

    Point operator *(double k) const {
        return Point(x * k, y * k);
    }

    Point operator /(double k) const {
        return Point(x / k, y / k);
    }

    T scl(Point other) const {
        return x * other.x + y * other.y;
    }

    T vect(Point other) const {
        return x * other.y - y * other.x;
    }

    Point rotate(double alpha) const {
        double new_x = x * cos(alpha) - y * sin(alpha);
        double new_y = x * sin(alpha) + y * cos(alpha);
        return Point(new_x, new_y);
    }

    double len() const {
        return sqrt(this->scl(*this));
    }

    T len2() const {
        return this->scl(*this);
    }

    bool operator ==(Point other) const {
        //return eq(x, other.x) && eq(y, other.y);
        return x == other.x && y == other.y;
    }

    bool collinear_to(Point other) const {
        //return eq(vect(other), 0);
        return vect(other) == 0;
    }

    bool on_line(Point A, Point B) const {
        //return eq((A - *this).vect(B - *this), 0);
        return (A - *this).vect(B - *this) == 0;
    }

    bool on_segment(Point A, Point B) const {
        //return on_line(A, B) && le((A - *this).scl(B - *this), 0);
        return on_line(A, B) && (A - *this).scl(B - *this) <= 0;
    }

    double dist_to(Point A) const {
        return (A - *this).len();
    }

    friend istream & operator >>(istream & input, Point & cur) {
        input >> cur.x >> cur.y;
        return input;
    }

    friend ostream & operator <<(ostream & output, const Point & cur) {
        output << cur.x << ' ' << cur.y;
        return output;
    }
};

