void getp(int x, int y) {
    for(int i = m; i; i--) {
        int now = d[i];
        for(int j = 0; j < 4; j++) {
            ll curx = x + d[i] * dx[j], cury = y + d[i] * dy[j];
            if(abs(curx) + abs(cury) < now) {
                cout << dc[j];
                x = curx, y = cury;
                break;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> n;
