        if((abs(X[i] + Y[i]) & 1) != (abs(X[i - 1] + Y[i - 1]) & 1))
            sign = 0;
        mx = max(mx, abs(X[i]) + abs(Y[i]));
    }
    if(!sign) {cout << -1; return 0;}
