#define EPS (1e-8)
#define equals(a,b) (fabs((a)-(b))<EPS)

using namespace std;

typedef long long ll;
bool LTE(double a,double b) { return equals(a,b) || a < b; }
bool LT(double a,double b) { return !equals(a,b) && a < b; }

#define MAX 1010
int n, x[MAX], y[MAX];

bool check() {
  int parity = ( x[0] + y[0] ) & 1;
  REP(i,1,n) if( parity != ( ( x[i] + y[i] ) & 1 ) ) return false;
  return true;
}

char op[50];

vector<ll> d;

void second_solve(ll v, char L, char R) {
  ll cur = 0;
  for(int i=(int)d.size()-1;i>=0;--i) {
    if( op[i] != '?' ) continue;
    if( cur <= v ) {
      cur += d[i];
      op[i] = R;
    } else {
      cur -= d[i];
      op[i] = L;
    }
  }
}

void first_solve(ll v, char L, char R) {
  assert( v != 0 );
  for(int i=(int)d.size()-1;i>=0;--i) {
    if( op[i] != '?' ) continue;
    if( v > 0 ) {
      if( d[i]     == v ) { op[i] = R; return; }
      if( d[i] + 1 == v ) { op[0] = op[i] = R; return; }
    } else {
      int w = v * -1;
      if( d[i]     == w ) { op[i] = L; return; }
      if( d[i] + 1 == w ) { op[0] = op[i] = L; return; }      
    }
  }
  assert(false);
}

void compute() {
  if( !check() ) { puts("-1"); return; }
  int parity = ( x[0] + y[0] ) & 1;
  if( parity == 0 ) d.push_back(1);
  rep(i,38) d.push_back(1LL<<i);
  cout << (int)d.size() << endl;
  rep(i,(int)d.size()) {
    if( i ) printf(" ");
    cout << d[i];
  } puts("");
  rep(i,n) {
    if( x[i] == 0 && y[i] == 0 ) {
      rep(j,(int)d.size()) {
	if( j + 1 == (int)d.size() ) cout << "R";
	else cout << "L";
      } puts("");
      continue;
    }
    rep(j,(int)d.size()) op[j] = '?';
    if( x[i] != 0 && y[i] != 0 ) {
      first_solve(x[i],'L','R');
      second_solve(y[i],'D','U');
    } else if( x[i] == 0 ) {
      second_solve(y[i],'D','U');
    } else {
      second_solve(x[i],'L','R');
    }
    rep(j,(int)d.size()) {
      cout << op[j];
    } puts("");
  }
}

int main() {
  cin >> n;
  rep(i,n) cin >> x[i] >> y[i];
  compute();
  return 0;
}

