int n,x[N],y[N];
void input()
{
	n=read<int>();
	For(i,1,n)x[i]=read<int>(),y[i]=read<int>();
}
void solve(int x,int y)
{
	Fordown(i,30,0)
	{
		int now=1<<i;
		if(x>=now)putchar('R'),x-=now;
		else if(x<=-now)putchar('L'),x+=now;
		else if(y>=now)putchar('U'),y-=now;
		else if(y<=-now)putchar('D'),y+=now;
		else
		{
			if(abs(x)>abs(y))
			{
				if(x>0)putchar('R'),x-=now;
				else putchar('L'),x+=now;
			}
			else
			{
				if(y>0)putchar('U'),y-=now;
				else putchar('D'),y+=now;
			}
		}
	}
	assert(x==0&&y==0);
}
void work()
{
	int res=abs(x[1]+y[1])&1;
	For(i,2,n)if((abs(x[i]+y[i])&1)!=res){puts("-1");return;}
	write(32-res,'\n');
	Fordown(i,30,0)write(1<<i,' ');
	if(!res)
	{
		write(1,' ');
		For(i,1,n)x[i]+=1;
	}
	cout<<endl;
	For(i,1,n)
	{
		solve(x[i],y[i]);
		if(!res)putchar('L');
		cout<<endl;
	}
}
int main()
{
