const int MAX = 36;
long long pow2[40];

void init() {
    pow2[0] = 1;
    for (int i=1; i<=MAX; ++i) {
        pow2[i] = pow2[i-1] * 2;
    }
}

string solve(long long X, long long Y, bool odd) {
    string s = "";
    for (int i=MAX; i>=0; --i) {
        long long parm = odd ? pow2[i] : pow2[max(0, i-1)];
        long long ph = odd ? parm-1 : (i == 0 ? 0 : parm);

        if (abs(X+parm) + abs(Y) <= ph) {
            X += parm;
            s = "L" + s;
        } else if (abs(X-parm) + abs(Y) <= ph) {
            X -= parm;
            s = "R" + s;
        } else if (abs(X) + abs(Y+parm) <= ph) {
            Y += parm;
            s = "D" + s;
        } else if (abs(X) + abs(Y-parm) <= ph) {
            Y -= parm;
            s = "U" + s;
        }
    }
    return s;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    init();

    int N;
    cin >> N;

    vector<int> X(N), Y(N);
    int odd = 0, even = 0;
    for (int i=0; i<N; ++i) {
        cin >> X[i] >> Y[i];
        if (abs(X[i]+Y[i]) % 2 == 0) {
            even ++;
        } else {
            odd ++;
        }
    }

    if (even > 0 && odd > 0) {
        cout << -1 << endl;
        return 0;
    }

    vector<long long> v;
    for (int i=0; i<=MAX; ++i) {
        if (odd > 0) {
            v.push_back(pow2[i]);
        } else {
            v.push_back(pow2[max(0, i-1)]);
        }
    }

    cout << MAX+1 << endl;
    for (int i=0; i<=MAX; ++i) {
        cout << v[i] << endl;
    }

    for (int i=0; i<N; ++i) {
        string s = solve(X[i], Y[i], odd > 0);
        cout << s << endl;

        long long x = 0, y = 0;
        for (int j=0; j<s.size(); ++j) {
            if (s[j] == 'L') x -= v[j];
            if (s[j] == 'R') x += v[j];
            if (s[j] == 'U') y += v[j];
            if (s[j] == 'D') y -= v[j];
        }
    }

    return 0;
}

