		}
		if(even){
			--u[i];
			--v[i];
		}
	}
	const int m = 32;
	cout << (m + (even ? 1 : 0)) << endl;
	for(int i = m - 1; i >= 0; --i){
		cout << (1ll << i) << " ";
	}
