		for(int j = m - 1; j >= 0; --j){
			const ll d = (2ll << j);
			int dmask = 0;
			if(cu - d >= -base){
				cu -= d;
				dmask |= 1;
			}
			if(cv - d >= -base){
				cv -= d;
				dmask |= 2;
			}
			solution.push_back("LUDR"[dmask]);
		}
		if(even){ solution.push_back('R'); }
		solution.push_back('\0');
