signed main() {
	INIT;

	VAR(int, n);
	VEC_ROW(int, n, x, y);

	std::vector<int> d;
	std::vector<std::string> s(n);
	while (true) {
		int ma = 0, ma2 = 0;
		bool zero = false;
		REP(i, n) {
			if (x[i] != 0) CHMAX(ma2, std::abs(y[i]));
			if (y[i] != 0) CHMAX(ma2, std::abs(x[i]));
			CHMAX(ma, std::abs(x[i]));
			CHMAX(ma, std::abs(y[i]));
			if (x[i] == 0 && y[i] == 0) zero = true;
		}
		if (ma2 != 0) ma = ma2;
		else {
			if (zero) ma = (ma + 1) / 2;
		}
		d.emplace_back(ma);
		bool conti = false;
		REP(i, n) {
			if (std::abs(x[i]) >= std::abs(y[i])) {
				if (x[i] >= 0) s[i] += 'R', x[i] -= ma;
				else s[i] += 'L', x[i] += ma;
			}
			else {
				if (y[i] >= 0) s[i] += 'U', y[i] -= ma;
				else s[i] += 'D', y[i] += ma;
			}
			if (x[i] != 0 || y[i] != 0) conti = true;
		}
		if (!conti) break;
		if (d.size() > 40) break;
	}

	if (d.size() > 40) {
		OUT(-1)BR;
		return 0;
	}

	std::reverse(ALL(d));
	REP(i, n) std::reverse(ALL(s[i]));

	int m = d.size();
	OUT(m)BR;
	REP(i, m) { OUT(d[i])SPBR(i, m); }
	REP(i, n) { OUT(s[i])BR; }

	return 0;
}

