    ds.push_back(1ll << i);
  }

  auto type = [&](bool X, bool Y) {
    if (X && Y) return 'R';
    if (X && !Y) return 'U';
    if (!X && Y) return 'D';
    if (!X && !Y) return 'L';
    assert(0);
  };
  vector<string> anss;
  REP (i, N) {
    string ans;
    int tmp_x = Xs[i] + ((1ll << MAX_I + 1) - 1);
    int tmp_y = Ys[i] + ((1ll << MAX_I + 1) - 1);
    // debug(tmp_x);
    // debug(tmp_y);
    for (int d: ds) {
      ans += type(tmp_x >= 2 * d, tmp_y >= 2 * d);
      if (tmp_x >= 2 * d) tmp_x -= 2 * d;
      if (tmp_y >= 2 * d) tmp_y -= 2 * d;
    }
    // debug(tmp_x);
    // debug(tmp_y);
    if (Xs[0] % 2 == 0) {
      ans += "R";
    }
    anss.push_back(ans);
  }
