int md(int x) {
    return (x % 3 + 3) % 3;
}
void solve(int x, int y, int dep = 1) {
    if(dep == 20) {
        //if(x != 1 && x != -1 && y != 1 && y != -1) assert(0);
        if(x == 1) write('L');
        else if(x == -1) write('R');
        else if(y == 1) write('D');
        else if(y == -1) write('U');
        return;
    }
    if(md(x) == 0 && md(y) == 0) write('L', 'R');
    else if(md(x) == 0 && md(y) == 1) write('U', 'U'), y += 2;
    else if(md(x) == 0 && md(y) == 2) write('D', 'D'), y -= 2;
    else if(md(x) == 1 && md(y) == 0) write('R', 'R'), x += 2;
    else if(md(x) == 1 && md(y) == 1) write('L', 'D'), x--, y--;
    else if(md(x) == 1 && md(y) == 2) write('L', 'U'), x--, y++;
    else if(md(x) == 2 && md(y) == 0) write('L', 'L'), x--, x--;
    else if(md(x) == 2 && md(y) == 1) write('R', 'D'), x++, y--;
    else if(md(x) == 2 && md(y) == 2) write('R', 'U'), x++, y++;
    solve(x / 3, y / 3, dep + 1);
}

