ll aa(ll a){
	if(a<0)return -a;
	else return a;
}
bool check(ll cx,ll cy,ll ml){
//	printf("cx %d cy %d num %d\n",cx,cy,ml);
	if(aa(cx)+aa(cy)<=(1<<ml)-1)return true;
	else return false;
}
void dfs(int id,int xx,int yy)
{
	ll cx=xx,cy=yy;
	for(int j=id;j>=1;j--)
	{
//		printf("cx %d cy %d\n",cx,cy);
		for(int i=0;i<4;i++){
			ll nx=cx+length[j]*dx[i];
			ll ny=cy+length[j]*dy[i];
			if(check(nx,ny,j-1)){
				ans[j]=i^1;
				cx=nx;cy=ny;
				break;
			}
		}
	}
}

