    REP(i, M) dist[i] = pow(2, i);
    if (parity == 1){
        cout << M << "\n";
        REP(i, M) cout << dist[i] << " ";
        cout << "\n";
        REP(i, N) {
            operation(dist, coor[i]);
        }
    }
    else {
        cout << M+1 << "\n";
        cout << 1 << " ";
        REP(i, M) cout << dist[i] << " ";
        cout << "\n";
        pair<ll, ll> offset = make_pair(0, 1);
        REP(i, N) {
