	VAR(int, n);
	VEC_ROW(int, n, x, y);

	std::vector<int> d;
	std::vector<std::string> s(n);
	while (true) {
		int ma = 0;
		bool zero = false;
		REP(i, n) {
			CHMAX(ma, std::abs(x[i]));
			CHMAX(ma, std::abs(y[i]));
			if (x[i] == 0 && y[i] == 0) zero = true;
		}
		if (zero) {
			int t = ma;
			ma = std::ceil(ma * 2 / 3.);
			if (t == ma) --ma;
		}
		d.emplace_back(ma);
		bool conti = false;
		REP(i, n) {
			if (std::abs(x[i]) >= std::abs(y[i])) {
				if (x[i] >= 0) s[i] += 'R', x[i] -= ma;
				else s[i] += 'L', x[i] += ma;
			}
			else {
				if (y[i] >= 0) s[i] += 'U', y[i] -= ma;
				else s[i] += 'D', y[i] += ma;
			}
			if (x[i] != 0 || y[i] != 0) conti = true;
