	if(p < 0) return "";
	if(isValid(x - (1LL<<p), y, p)) return solve_for(x - (1LL<<p), y, p-1) + 'R';
	if(isValid(x + (1LL<<p), y, p)) return solve_for(x + (1LL<<p), y, p-1) + 'L';
