        if (mask & (1 << j)) {
          res.first += 1ll * sign[j] * ans[j];
        } else {
          res.second += 1ll * sign[j] * ans[j];
        }
      }
      mp[res] = mask;
    }

    int rem = sz(ans) - mid;
    for (int mask = 0; mask < (1 << rem); mask++) {
      pair<long long, long long> res;
      for (int j = mid; j < sz(ans); j++) {
        if (mask & (1 << (j - mid))) {
          res.first += 1ll * sign[j] * ans[j];
