void solve3(const vector<ll>& a, const vector<ll>& up, const vector<pii>& q) {
    int n = q.size();
    int m = a.size();
    for (int i = 0; i < n; ++i) {
        string s = "";
        pll p = q[i];
        for (int j = m - 1; j >= 0; --j) {
            pll pl(p.first - a[j], p.second);
            pll pr(p.first + a[j], p.second);
            pll pu(p.first, p.second + a[j]);
            pll pd(p.first, p.second - a[j]);
            if (ok(pl, up[j])) {
                s.push_back('L');
                p = pl;
                continue;
            }
            if (ok(pr, up[j])) {
                s.push_back('R');
                p = pr;
                continue;
            }
            if (ok(pu, up[j])) {
                s.push_back('U');
                p = pu;
                continue;
            }
            if (ok(pd, up[j])) {
                s.push_back('D');
                p = pd;
                continue;
            }
        }
        reverse(s.begin(), s.end());
        cout << s << "\n";
        //cout << p.first << " " << p.second << endl;
    }
}


