    scanf("%d", &N);
    vector<LL> x(N), y(N);
    for(int i = 0; i < N; i++) scanf("%lld %lld", &x[i], &y[i]);
    vector<LL> d;
    vector<string> s(N, "");
    if((x[0] & 1) == (y[0] & 1)){
        d.push_back(1);
        for(int i = 0; i < N; i++){
            s[i].push_back('U');
            y[i]--;
        }
    }

    LL step = 1;
    while(step < (1LL << 33)){
        d.push_back(step);
        for(int i = 0; i < N; i++){
            if((x[i] & 1) == (y[i] & 1)){
                printf("%d\n", -1);
                return 0;
            }
            if(x[i] & 1){
                if(((x[i] - 1) & 2) != (y[i] & 2)){
                    x[i]--;
                    s[i].push_back('R');
                }else{
                    x[i]++;
                    s[i].push_back('L');
                }
            }else{
                if(((y[i] - 1) & 2) != (x[i] & 2)){
                    y[i]--;
                    s[i].push_back('U');
                }else{
                    y[i]++;
                    s[i].push_back('D');
                }
            }
            x[i] /= 2;
            y[i] /= 2;
        }
        step <<= 1;
    }

    d.push_back(step);
    for(int i = 0; i < N; i++){
        assert(x[i] * x[i] + y[i] * y[i] == 1);
        s[i].push_back(x[i] == 1 ? 'R' : (x[i] == -1 ? 'L' : (y[i] == 1 ? 'U' : 'D')));
    }

    int m = (int) d.size();
    printf("%d\n", m);
    for(int i = 0; i < m; i++){
        if(i > 0) printf(" ");
        printf("%lld", d[i]);
    }
    printf("\n");
    for(int i = 0; i < N; i++){
        int l = s[i].size();
        for(int j = 0; j < l; j++) printf("%c", s[i][j]);
        printf("\n");
    }
    return 0;

}

