using namespace std;

long long dx[] = {0, 1, 0, -1};
long long dy[] = {1, 0, -1, 0};
char dir[] = {'R', 'U', 'L', 'D'};

int get(int x, int y) {
    return ((x + y) % 2 + 2) % 2;
}

void solve() {
    int n;
    cin >> n;
    vector<long long> x(n), y(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        if (i > 0 && get(x[i - 1], y[i - 1]) != get(x[i], y[i])) {
            cout << -1; return;
        }
    }
    int parity = get(x[0], y[0]);
    cout << 30 + (parity == 0) << "\n";
    if (!parity) cout << 1 << ' ';
    for (int i = 29; i >= 0; i--) {
        cout << (1 << i) << ' ';
    }
    cout << "\n";
    for (int i = 0; i < n; i++) {
        if (!parity) cout << 'U', y[i]++;
        for (int j = 29; j >= 0; j--) {
            for (int k = 0; k < 4; k++) {
                long long nx = x[i] + dx[k] * (1LL << j), ny = y[i] + dy[k] * (1LL << j);
                if (abs(nx) + abs(ny) <= (1LL << j) - 1) {
                    x[i] = nx, y[i] = ny;
                    cout << dir[k];
                    break;
                }
            }
        }
        cout << "\n";
    }
}

int main() {
    ios::sync_with_stdio(NULL), cin.tie(0), cout.tie(0);
    cout.setf(ios::fixed), cout.precision(20);
    solve();
}

