  m = len;
  fill_n((int*)d, m, 1);
  for (int i = 0; i < N; i++) {
    int px = 0, py = 0;
    for (int j = 0; j < m; j++) {
      if (px > X[i]) {
        w[i] += "L";
        px--;
      } else if (px < X[i]) {
        w[i] += "R";
        px++;
      } else if (py > Y[i]) {
