#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int maxn = 1e3;
const ll inf = (1ll << 33) - ll(2e9);
int n, a[maxn + 10], b[maxn + 10];;
ll x[maxn + 10], y[maxn + 10], d[maxn + 10];
ll bkx[maxn + 10], bky[maxn + 10];

void update(ll v, int *a) {
	a[1] = 1; v -= d[1];
	for (int i = 2; i <= 34; ++i)
		v += d[i];
	assert(v % 2 == 0);
	v /= 2;
	assert(v >= 0 && (v < (1ll << 33)));
	for (int i = 34; i >= 2; --i)
		if (d[i] <= v) {
			v -= d[i]; a[i] = 1;
		} else a[i] = -1;
}

void getans(int x, int y) {
	if (x == 1 && y == 1) printf("R");
	else if (x == 1 && y == -1) printf("U");
	else if (x == -1 && y == 1) printf("D");
	else printf("L");
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i <= n; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		bkx[i] = a; bky[i] = b;
		x[i] = a + b; y[i] = a - b;
	}
	for (int i = 1; i <= n; ++i)
		if ((x[i] + x[1]) % 2 || (y[i] + x[1]) % 2) {
			printf("-1"); return 0;
		}
	if (x[1] & 1) d[1] = inf;
	else d[1] = inf - 1;
	for (int i = 2; i <= 34; ++i) d[i] = 1ll << (i - 2);
	printf("%d\n", 34);
	for (int i = 1; i <= 34; ++i)
		printf("%lld ", d[i]);
	printf("\n");
	for (int i = 1; i <= n; ++i) {
		update(x[i], a);
		update(y[i], b);
		ll nowx = 0, nowy = 0;
		for (int j = 1; j <= 34; ++j) {
			getans(a[j], b[j]);
			if (a[j] == 1 && b[j] == 1) nowx += d[j];
			else if (a[j] == 1 && b[j] == -1) nowy += d[j];
			else if (a[j] == -1 && b[j] == 1) nowy -= d[j];
			else nowx -= d[j];
		}
		assert(nowx == bkx[i] && nowy == bky[i]);
		printf("\n");
	}
}

