Int m = 2;
vector<Int> d(m);

string solve(Int x,Int y){
  string res;
  Int fa = (x + y) < 0? -1:1;
  Int fb = (x - y) < 0? -1:1;
  Int u = abs(x + y), v = abs(x - y);

  auto getCmd = [](Int a,Int b){
    if(a == -1 && b == -1) return 'L';
    if(a == 1 && b == 1) return 'R';
    if(a == -1 && b == 1) return 'D';
    if(a == 1 && b == -1) return 'U';
    assert(0);
  };

  Int M = 0;
  for(Int i=0;i<m;i++) M += d[i];
  for(Int i=0;i<m-1;i++){
    Int a = fa, b = fb;
    if((M - u) & d[i+1]) a *= -1;
    if((M - v) & d[i+1]) b *= -1;
    res += getCmd(a, b);
  }
  res += getCmd(fa, fb);
  return res;
}

void check(Int targetX,Int targetY, string cmd){
  assert((Int)cmd.size() == m);
  Int x = 0, y = 0;
  for(Int i=0;i<m;i++){
    if(cmd[i] == 'L') x -= d[i];
    if(cmd[i] == 'R') x += d[i];
    if(cmd[i] == 'D') y -= d[i];
    if(cmd[i] == 'U') y += d[i];
  }
  //pr(d);
  //pr(targetX, targetY, x, y);
  assert(x == targetX && y == targetY);
}

