  if(mod[0] && mod[1]){
    cout<<-1<<endl;
    return 0;
  }

  for(Int i=0;i<m;i++) d[i] = 1LL<<i;
  if(mod[0]) d.insert(d.begin(), 1);
  m = d.size();

  vector<string> Ans;
  for(Int i=0;i<n;i++){
    string str = solve(X[i], Y[i]);
