/*
check answer's existence by parity

we could reach all (x,y) which x+y < 2^k
proof : induction (the area we could reach is a Manhattan rectangle)

construct paths by bit -- reduce the maximum absolute values of coordinates
*/

#include <bits/stdc++.h>
using namespace std;

int X[1001], Y[1001];
int d[33], n;

int main() {
	scanf("%d", &n);
	bool exi[2] = {false, false};
	for(int i = 1; i <= n; ++ i) {
		scanf("%d%d", X+i, Y+i);
		exi[(X[i] + Y[i]) & 1] = true;
	}
	if(exi[0] and exi[1]) return puts("-1"), 0;

	int m = 0;
	if(exi[0]) d[++m] = 1;
	for(int i = 30; i >= 0; -- i) d[++m] = 1 << i;
	printf("%d\n", m);
	for(int i = 1; i <= m; ++ i) printf("%d ", d[i]);
	putchar(10);

	for(int c = 1; c <= n; ++ c) {
		int x = X[c], y = Y[c];
		for(int i = 1; i <= m; ++ i)
			if(abs(x) >= abs(y))
				if(x >= 0) x -= d[i], putchar('R');
				else x += d[i], putchar('L');
			else
				if(y >= 0) y -= d[i], putchar('U');
				else y += d[i], putchar('D');
		putchar(10);
	}
	return 0;
}

