void Solve() {
	read(N);
	for(int i = 1 ; i <= N ; ++i) {
		read(X[i]);read(Y[i]);
	}
	for(int i = 2 ; i <= N ; ++i) {
		if((abs(X[i]) + abs(Y[i])) % 2 != (abs(X[1]) + abs(Y[1])) % 2)  {
