const int dx[4] = {1, -1, 0, 0};
const int dy[4] = {0, 0, 1, -1};
const char dir[4] = {'R', 'L', 'U', 'D'};

ll dist(ll x, ll y, ll tx, ll ty) {
  return abs(x - tx) + abs(y - ty);
}

int main() {
  scanf("%d", &n);
  int sig = 0, par = 0;
  for (int i = 1; i <= n; i++) {
    scanf("%d %d", &x[i], &y[i]);
    sig |= ((x[i] ^ y[i]) & 1);
    par |= !((x[i] ^ y[i]) & 1);
  }
  if (sig && par) {
    puts("-1");
    return 0;
  }
  if (par) {
    printf("32\n1 ");
