using ll = long long;

const int BITS = 31;

struct P {
    int x, y;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    /*  all points must have same parity of manhattan dist 
     * 
     * 
     *  to get to point (x, y):
     *          
     * 
     *          m = L + R + U + D (m <= 40)
     *
     */
    int n;
    cin >> n;
    vector<P> a(n);
    for(int i = 0; i < n; i++) {
        cin >> a[i].x >> a[i].y;
    }

    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(((a[i].x+a[i].y)%2+2)%2 != ((a[j].x+a[j].y)%2+2)%2) {
                cout << "-1\n";
                exit(0);
            }
        }
    }

    bool even = (a[0].x + a[0].y) % 2 == 0;

    vector<int> d(BITS);
    for(int i = 0; i < BITS; i++) {
        d[i] = 1<<i;
    }
    if(even) {
        d.push_back(1);
    }
    int m = d.size();
    cout << m << '\n';
    for(int i = 0; i < m; i++) {
        cout << d[i] << " \n"[i==m-1];
    }

    for(int i = 0; i < n; i++) {
        P p = a[i];
        if(even) {
            p.x--;
        }
        string ans;
        int x = p.x, y = p.y;
        for(int b = BITS-1; b >= 0; b--) {
            int take = 1<<b;
            int need = (1<<b)-1;
            debug() nav(x) nav(y) nav(need);
            if(abs(x-take) + abs(y) <= need) {
                ans.push_back('R');
                x -= take;
            } else if(abs(x+take) + abs(y) <= need) {
                ans.push_back('L');
                x += take;
            } else if(abs(x) + abs(y-take) <= need) {
                ans.push_back('U');
                y -= take;
            } else if(abs(x) + abs(y+take) <= need) {
                ans.push_back('D');
                y += take;
            }
            else {
                assert(false); // :( so sad
            }
        }
        reverse(ans.begin(), ans.end());
        if(even) {
            ans.push_back('R');
        }
        cout << ans << '\n';
    }

}

