using namespace std;

const int BITS = 32;

char flip(char dir) {
    if (dir == 'L' || dir == 'R')
        return 'L' + 'R' - dir;

    return 'U' + 'D' - dir;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> X(N), Y(N);

    for (int i = 0; i < N; i++) {
        cin >> X[i] >> Y[i];

        if (abs(X[i] + Y[i]) % 2 != abs(X[0] + Y[0]) % 2) {
            cout << -1 << '\n';
            return 0;
        }
    }

    vector<long long> D;

    for (int p = BITS; p >= 0; p--)
        D.push_back(1LL << p);

    if (abs(X[0] + Y[0]) % 2 == 0)
        D.push_back(1);

    int M = D.size();
    cout << M << '\n';

    for (int i = 0; i < M; i++)
        cout << D[i] << (i < M - 1 ? ' ' : '\n');

    for (int i = 0; i < N; i++) {
        long long x = X[i], y = Y[i];

        for (long long d : D) {
            long long best_sum = abs(x - d) + abs(y);
            char best_dir = 'L';

            long long current = abs(x + d) + abs(y);
            if (current < best_sum) {
                best_sum = current;
                best_dir = 'R';
            }

            current = abs(x) + abs(y - d);
            if (current < best_sum) {
                best_sum = current;
                best_dir = 'D';
            }

            current = abs(x) + abs(y + d);
            if (current < best_sum) {
                best_sum = current;
                best_dir = 'U';
            }

            cout << flip(best_dir);

            if (best_dir == 'L')
                x -= d;
            else if (best_dir == 'R')
                x += d;
            else if (best_dir == 'D')
                y -= d;
            else if (best_dir == 'U')
                y += d;
            else
                assert(false);
        }

        assert(x == 0 && y == 0);
        cout << '\n';
    }
}

