        cout << "\n";

        if (x != 0) {
            cout << (x > 0 ? 'R' : 'L');
        }
        if (y != 0) {
            cout << (y > 0 ? 'U' : 'D');
        }
        cout << "\n";

        return 0;
    }

    vector<pair<int, int>> vec(n);
    auto total_parity = -1;
    auto max_odds = 0;
    auto good = true;
    int64_t max_dist = 0;

    for (auto &p : vec) {
        cin >> p.first >> p.second;
        max_dist = max(max_dist, DistFromOrigin(p));

        auto odds = abs(p.first) % 2 + abs(p.second) % 2;
        max_odds = max(max_odds, odds);

        if (total_parity == -1) {
            total_parity = (odds % 2);
        } else if (good) {
            good = (total_parity == (odds % 2));
        }
    }

    if (!good) {
        cout << "-1\n";
        return 0;
    }

    auto segs = GetSegs(max_odds, max_dist);
    cout << segs.size() << "\n";

    for (const auto &len : segs) {
        cout << len << " ";
    }
    cout << "\n";

    for (const auto &p : vec) {
        auto modes = GetModes(segs, p);
        cout << modes << "\n";
    }

    return 0;
}

