void calc(int X,int Y,int c){
	if(c<0)return;
	//printf("%d %d %d\n",X,Y,c);
	int len=1<<(max(0,c-1));
	if(X>=len){
		calc(X-len,Y,c-1);
		in[c]='R';
	}else if(Y>=len){
		calc(X,Y-len,c-1);
		in[c]='U';
	}else if(X>Y){
		calc(len-X,Y,c-1);
		for(int i=0;i<c;i++){
