			else if(in[i]=='R')in[i]='L';
		}
		in[c]='R';
	}else{
		calc(X,len-Y,c-1);
		for(int i=0;i<c;i++){
			if(in[i]=='U')in[i]='D';
			else if(in[i]=='D')in[i]='U';
