using namespace std;

const int BITS = 39;

bool bad[BITS];

void work(int v, string d, string &s, vector<int> &ans) {
  for (int j = 0; j <= 30; ++j) {
    if ((abs(v) >> j & 1) == 0) {
      continue;
    }
    if (!bad[j]) {
      for (int k = 0; k < (int)ans.size(); ++k) {
        if (s[k] != '*') {
          continue;
        }
        if ((1 << ans[k]) == (1 << j)) {
          s[k] = d[v > 0];
          break;
        }
      }
    } else {
      int cnt = 0;
      for (int k = 0; k < (int)ans.size(); ++k) {
        if (s[k] != '*') {
          continue;
        }
        if ((1 << ans[k]) == (1 << (j - 1))) {
          s[k] = d[v > 0];
          ++cnt;
        }
        if (cnt == 2) {
          break;
        }
      }
    }
  }
}

int need[BITS];
int w[BITS];

const int N = 1'009;

int x[N];
int y[N];

int main() {
  int n;
  scanf("%d", &n);
  memset(bad, false, sizeof bad);
  memset(need, 0, sizeof need);
  bool sub = true;
  for (int i = 0; i < n; ++i) {
    scanf("%d %d", x + i, y + i);
    if (abs(x[i]) > 10 || abs(y[i]) > 10) {
      sub = false;
    }
    for (int j = 0; j <= 30; ++j) {
      int cnt = (abs(x[i]) >> j & 1) + (abs(y[i]) >> j & 1);
      if (cnt == 0) {
        bad[j] = true;
      } else {
        need[j] = max(need[j], cnt);
      }
    }
  }
  if (bad[0] && need[0] != 0) {
    puts("-1");
    return 0;
  }
  vector<int> ans;
  for (int i = 0; i <= 30; ++i) {
    if (!bad[i]) {
      for (int j = 0; j < need[i]; ++j) {
        ans.push_back(i);
      }
    } else {
      for (int j = 0; j < 2 * need[i]; ++j) {
        ans.push_back(i - 1);
      }
    }
  }
  if ((int)ans.size() > 40) {
    assert(!sub);
    puts("-1");
    return 0;
  }
  printf("%d\n", (int)ans.size());
  for (int i = 0; i < (int)ans.size(); ++i) {
    if (i > 0) {
      putchar(' ');
    }
    printf("%d", 1 << ans[i]);
  }
  putchar('\n');
  for (int i = 0; i < n; ++i) {
    string s((int)ans.size(), '*');
    work(x[i], "LR", s, ans);
    work(y[i], "DU", s, ans);
    memset(w, 0, sizeof w);
    for (int j = 0; j < (int)ans.size(); ++j) {
      if (s[j] != '*') {
        continue;
      }
      s[j] = w[ans[j]] == 0 ? 'L' : 'R';
      w[ans[j]] = 1 - w[ans[j]];
    }
    for (int j = 0; j <= 30; ++j) {
      assert(w[j] == 0);
    }
    int cx = 0, cy = 0;
    for (int j = 0; j < (int)s.size(); ++j) {
      cx += ((s[j] == 'R') - (s[j] == 'L')) * (1 << ans[j]);
      cy += ((s[j] == 'U') - (s[j] == 'D')) * (1 << ans[j]);
    }
    assert(cx == x[i] && cy == y[i]);
    puts(s.c_str());
  }
}

