void solve(ll x, ll y) {
	for(int t = LOGX-1; t >= 0; t--) {
		for(int k = 0; k < 4; k++) {
			if(labs(x - dx[k]*p2[t]) + labs(y - dy[k]*p2[t]) <= (p2[t]-1)) {
				printf("%c", dir[k]);
				x -= dx[k]*p2[t];
				y -= dy[k]*p2[t];
				break;
			}
		}
	}
	printf("\n");
}

