void print(lint dist, char neg, char pos) {
	if (dist == 0)
		return;
	char cur = pos;
	if (dist < 0)
		cur = neg;
	For(i, abs(dist))
		printf("%c", cur);
}

void solve() {
	int n;
	scanf("%d", &n);
	vector<pair<lint, lint> > pts(n);
	For(i, n) {
		scanf("%lld%lld", &pts[i].first, &pts[i].second);
	}
	lint oddity = abs(pts[0].first + pts[0].second) % 2;
	For(i, n) {
		if (abs(pts[i].first + pts[i].second) % 2 != oddity) {
			printf("-1");
			return;
		}
	}

	lint max_sum = 0;
	For(i, n) {
		max_sum = max(max_sum,
			abs(pts[i].first) + abs(pts[i].second)
		);
	}

	printf("%lld\n", max_sum);
	For(i, max_sum) {
		printf("1 ");
	}
	printf("\n");
	for (auto p : pts) {
		auto to_move = (abs(p.first) + abs(p.second));
		For(i, (max_sum - to_move) / 2) {
			printf("UD");
		}
		print(p.first, 'L', 'R');
		print(p.second, 'D', 'U');
		printf("\n");
	}
}

