void solve(vector < pair < int, int > > all) {
    bool ok = true;
    for (int i = 0; i < all.size(); i++) {
        if (abs(all[i].first) > 1 || abs(all[i].second) > 1) {
            ok = false;
            break;
        }
    }
    if (ok) {
        d.push_back(1);
        for (int j = 0; j < n; j++) {
            if (all[j].first == 1) {
                ans[j] += 'R';
            }
            if (all[j].first == -1) {
                ans[j] += 'L';
            }
            if (all[j].second == 1) {
                ans[j] += 'U';
            }
            if (all[j].second == -1) {
                ans[j] += 'D';
            }
        }
        return ;
    }
    vector < pair < int, int > > nall;
    for (int i = 0; i < n; i++) {
        int mn = 2 * (int)1e9;
        pair < int, int > opt;
        for (int t1 = -2; t1 <= 2; t1++) {
            for (int t2 = -2; t2 <= 2; t2++) {
                int p1 = (all[i].first + t1) / 2;
                int p2 = (all[i].second + t2) / 2;
                if (abs(p1 + p2) % 2 == 0) continue;
                if (abs(2 * p1 - all[i].first) > 1) continue;
                if (abs(2 * p2 - all[i].second) > 1) continue;
                if (mn > abs(p1) + abs(p2)) {
                    mn = abs(p1) + abs(p2);
                    opt = make_pair(p1, p2);
                }
            }
        }
        nall.push_back(opt);
    }
    solve(nall);
    for (int i = 0; i < d.size(); i++) d[i] *= 2;
    d.push_back(1);
    for (int i = 0; i < all.size(); i++) {
        pair < int, int > prv = nall[i];
        pair < int, int > cur = all[i];
        int dif1 = cur.first - 2 * prv.first;
        int dif2 = cur.second - 2 * prv.second;
        if (dif1 == 1) {
            ans[i] += 'R';
        }
        if (dif1 == -1) {
            ans[i] += 'L';
        }
        if (dif2 == 1) {
            ans[i] += 'U';
        }
        if (dif2 == -1) {
            ans[i] += 'D';
        }
    }
}
