                ans.push_back('L');
                cx += pt2[i];
            } else if (check(cx, cy - pt2[i], i)) {
                ans.push_back('U');
                cy -= pt2[i];
            } else if (check(cx - pt2[i], cy, i)) {
                ans.push_back('R');
                cx -= pt2[i];
            } else {
                assert(false);
            }
        }
        cout << ans << endl;
    }
