void solve(int k,int pos)
{
	ll XX = X[k]; ll YY = Y[k];
	ll x = 0; ll y = 0;
	for (int i = pos - 1; i >= 0; i--)
	{
		if (ABS(XX - x) > ABS(YY - y))
		{
			if (XX > x) { cout << 'R'; x += d[i]; }
			else if (XX < x) { cout << 'L'; x -= d[i]; }
		}
		else if(ABS(XX-x)<ABS(YY-y))
		{
			if (YY > y) { cout << 'U'; y += d[i]; }
			else if (YY < y) { cout << 'D'; y -= d[i]; }
		}
		else
		{
			if (XX >= x) { cout << 'R'; x += d[i]; }
			else if (XX < x) { cout << 'L'; x -= d[i]; }
		}
	}
	cout << endl;
}

