#include <bits/stdc++.h>
#define MAXN 1005
using namespace std;

int n;
pair<int, int> v[MAXN];
set<int> vals;
map<int, vector<int>> valCode;
vector<int> d;
long long sumd;

void getds(int maxval) {
    if (maxval & 1) {
        int k;
        for (k = 0; ; ++k) {
            if ((1LL << (k + 1)) - 1 >= maxval)
                break;
        }

        sumd = (1LL << (k + 1)) - 1;
        for (int i = 0; i <= k; ++i)
            d.push_back(1 << i);
    }
    else {
        int k;
        for (k = 1; ; ++k) {
            if ((1LL << (k + 1)) - 2 >= maxval)
                break;
        }

        sumd = (1LL << (k + 1)) - 2;
        for (int i = 0; i <= k; ++i)
            d.push_back(1 << i);
        d.back()--;
    }
}

vector<int> getValCode(int x) {
    vector<int> ans(d.size(), 1);

    long long crtS = sumd;
    for (int i = (int) d.size() - 1; i >= 0; --i) {
        if (crtS - 2LL * d[i] >= x) {
            crtS -= 2LL * d[i];
            ans[i] = -1;
        }
    }

    assert(crtS == x);
    return ans;
}

vector<int> swapSigns(const vector<int> &v) {
    vector<int> ans;
    for (auto x: v)
        ans.push_back((x == 1) ? -1 : 1);
    return ans;
}

string getSol(int x, int y) {
    const vector<int> &sumCode = valCode[x + y];
    const vector<int> &difCode = valCode[x - y];

    string ans;

    for (int i = 0; i < (int) sumCode.size(); ++i) {
        int xcode = (sumCode[i] + difCode[i]) >> 1;
        int ycode = (sumCode[i] - difCode[i]) >> 1;

        assert(xcode == 0 || ycode == 0);
        if (xcode == 0)
            ans.push_back(ycode == 1 ? 'U' : 'D');
        else
            ans.push_back(xcode == 1 ? 'R' : 'L');
    }

    return ans;
}

