    ios::sync_with_stdio(0);

    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> v[i].first >> v[i].second;
        vals.insert(abs(v[i].first + v[i].second));
        vals.insert(abs(v[i].first - v[i].second));
    }

    int par = *vals.begin() & 1;
    for (auto x: vals) {
        if ((x & 1) != par) {
            cout << "-1\n";
            return 0;
        }
    }

    getds(*vals.rbegin());
    for (auto x: vals) {
        valCode[x] = getValCode(x);
        valCode[-x] = swapSigns(valCode[x]);
    }

    cout << d.size() << "\n";
    for (auto x: d)
        cout << x << " ";
    cout << "\n";

    for (int i = 1; i <= n; ++i)
        cout << getSol(v[i].first, v[i].second) << "\n";

    return 0;
}

