					dp[i + 1][j + d[i] + 100][k + 100] |= dp[i][j + 100][k + 100];
					dp[i + 1][j - d[i] + 100][k + 100] |= dp[i][j + 100][k + 100];
					dp[i + 1][j + 100][k + d[i] + 100] |= dp[i][j + 100][k + 100];
					dp[i + 1][j + 100][k - d[i] + 100] |= dp[i][j + 100][k + 100];
