#include <bits/stdc++.h>
using namespace std;

typedef enum {
  Left = 'L',
  Right = 'R',
  Up = 'U',
  Down = 'D',
} Mode;

class Point {
  public:
    Point() = default;
    Point(int _x, int _y) { x = _x; y = _y; }
    int x;
    int y;
    int manhattan() const { return abs(x) + abs(y); }
};

int ngoal;
vector<Point> goal;
vector<int> arm;

bool has_smaller_manhattan(const Point& a, const Point& b)
{
  return a.manhattan() < b.manhattan();
}

bool is_solvable(const vector<Point>& g)
{
  bool parity = g.at(0).manhattan() % 2 == 0;
  for (int i = 1; i < (int)g.size(); i++) {
    if (parity != (g.at(i).manhattan() % 2 == 0)) {
      return false;
    }
  }
  return true;
}

void print_arm(const vector<int>& a)
{
  cout << a.size() << '\n';
  cout << a.at(0);
  for (int i = 1; i < (int)a.size(); i++) {
    cout << ' ' << a.at(i);
  }
  cout << '\n';
}

int main()
{
  cin >> ngoal;
  goal.resize(ngoal);
  for (int i = 0; i < ngoal; i++) {
    cin >> goal.at(i).x >> goal.at(i).y;
  }
  if (!is_solvable(goal)) {
    cout << "-1" << endl;
    return 0;
  }

  // prepare arm
  int len = max_element(goal.begin(), goal.end(), has_smaller_manhattan)->manhattan();
  if (len % 2 == 0) {
    arm.push_back(1);
  }
  int sumarm = 0;
  int tmparm = 1;
  while (sumarm < len) {
    sumarm = sumarm | tmparm;
    arm.push_back(tmparm);
    tmparm = tmparm << 1;
  }
  sort(arm.rbegin(), arm.rend());
  print_arm(arm);

  // determine modes
  for (auto& g : goal) {
    for (const auto& a : arm) {
      if (abs(g.x) < abs(g.y)) {
        if (0 < g.y) {
          cout << 'U';
          g.y -= a;
        } else {
          cout << 'D';
          g.y += a;
        }
      } else {
        if (0 < g.x) {
          cout << 'R';
          g.x -= a;
        } else {
          cout << 'L';
          g.x += a;
        }
      }
    }
    assert(g.x == 0);
    assert(g.y == 0);
    cout << '\n';
  }

  return 0;
}

