void pr(int i){
    int distx=vec[i].first;
    int disty=vec[i].second;
    if(distx<0){
        rep(i,abs(distx)){
            printf("L");
        }
    }else if(distx>0){
        rep(i,abs(distx)){
            printf("R");
        }
