	int N; cin >> N;
	vector<P> pos(N);
	rep (i, N){
		cin >> pos[i].first >> pos[i].second;
	} // end rep

	bool ok = true;
	int par = (abs(pos[0].first) + abs(pos[0].second)) % 2;
	for (int i = 1; i < N; ++i){
		int par2 = (abs(pos[i].first) + abs(pos[i].second)) % 2;
		if (par != par2){
			ok = false;
			break;
		} // end if
	} // end for

	if (!ok){
		cout << "-1" << endl;
	}else{
		vector<int> d; d.clear();
		for (int i = 30; i >= 0; --i){
			d.push_back(1<<i);
		} // end for
		if (par % 2 == 0) d.push_back(1);
		cout << (int)d.size() << endl;
		for (int j = 0; j < (int)d.size(); ++j){
			cout << d[j] << (j != (int)d.size() - 1 ? ' ' : '\n');
		} // end for
		rep (i, N){
			int xdir, ydir;
			int xsum = 0, ysum = 0;
			for (int j = 0; j < (int)d.size(); ++j){
				if (xsum <= pos[i].first){
					xdir = 1, xsum += d[j];
				}else{
					xdir = -1, xsum -= d[j];
				} // end if
				if (ysum <= pos[i].second){
					ydir = 1, ysum += d[j];
				}else{
					ydir = -1, ysum -= d[j];
				} // end if
				if (xdir == -1 && ydir == -1){
					cout << "R";
				}else
				if (xdir == 1 && ydir == -1){
					cout << "U";
				}else
				if (xdir == -1 && ydir == -1){
					cout << "L";
				}else{ // if (xdir == 1 && ydir == 1)
					cout << "D";
				} // end if
			} // end for
			cout << endl;
		} // end rep
	} // end if

	return 0;
}

