std::vector<int> dfs(long long d, long long x)
{
  if (d == 0)
    return {};

  std::vector<int> a;

  if (std::abs(d - x) <= std::abs(- d - x)) {
    a = dfs(d / 2, x - d);

    a.push_back(1);
  }
  else {
    a = dfs(d / 2, x + d);

    a.push_back(-1);
  }

  return std::move(a);
}


