vector<int64> calc(int64 x) {
	int64 xx = abs(x);
	int64 sgn = x < 0 ? 1 : 0;
	vector<int64> v;
	int64 bef = 0;
	for (int64 i = 32; i >= 0; i--) {
		if (xx >> i & 1) {
			if (bef) {
				v.push_back(1-sgn);
			} else {
				v.push_back(sgn);
			}
			bef = 0;
		} else {
			if (bef) {
				v.push_back(1- sgn);
			} else {
				v.push_back(sgn);
			}
			bef = 1;
		}
	}
	return v;
}

