        ds.push_back(1);
    }
    if (parity) {
        ds.push_back(1);
    }

    // construct commands
    vector<string> ws;
    for (auto p : ps) {
        int x, y; tie(x, y) = p;
        string w;
        for (int d : ds) {
            if (x + y >= 0 and x - y >= 0) {
                w += 'R';
                x -= d;
            } else if (x + y >= 0) {
                w += 'U';
                y -= d;
            } else if (x - y >= 0) {
