vector<int64> fen;
int64 fen_sum(int r) {
    int64 result = 0;
    for (; r >= 0; r = (r & (r + 1)) - 1) {
        result += fen[r];
    }
    return result;
}
void fen_inc(int i, int64 delta) {
    for (; i < fen.size(); i = (i | (i + 1))) {
        fen[i] += delta;
    }
}
void fen_init(size_t n) {
    fen.assign(n, 0);
}
void fen_init(const vector<int64> &data) {
    fen_init(data.size());
    for (int i = 0; i < data.size(); i++) {
        fen_inc(i, data[i]);
    }
}


int64 gcd (int64 a, int64 b) {
    int64 r;
    while (b != 0){
        r = a % b;
        a = b;
        b = r;
    }
    return a;
}


