	for (int i = 1;i <= n;i++)
		for (int j = 30;j >= 0;j--)
		{
			if (ok(j - 1,x[i] - (1 << j),y[i]))
			{
				x[i] -= 1 << j;
				ans[i] += "R";
			}
			else if (ok(j - 1,x[i] + (1 << j),y[i]))
			{
				x[i] += 1 << j;
				ans[i] += "L";
			}
			else if (ok(j - 1,x[i],y[i] - (1 << j)))
			{
				y[i] -= 1 << j;
				ans[i] += "U";
			}
			else
			{
				y[i] += 1 << j;
				ans[i] += "D";
			}
		}
