	for (int i = 1;i <= m;i++)
		printf("%d ",d[i]);
	printf("\n");
	for (int i = 1;i <= n;i++)
	{
		reverse(ans[i].begin(),ans[i].end());
		puts(ans[i].c_str());
	}
	return 0;
}

