inline int check(int x,int y,char opt,int d){
	switch(opt){
		case 'L':
			return y <= d - 1&& y >= -d + 1&& x - d  <= d - 1&& x - d >= -d + 1;
		case 'R':
			return y <= d - 1&& y >= -d + 1&& x + d  <= d - 1&& x + d >= -d + 1;
		case 'D':
			return y - d <= d - 1&& y - d >= -d + 1&& x <= d - 1&& x >= -d + 1;
		case 'U':
			return y + d <= d - 1&& y + d >= -d + 1&& x <= d - 1&& x >= -d + 1; 
	}
}
inline void nxt(int& x,int& y,char opt,int d){
	switch(opt){
		case 'L':
			x -= d;break;
		case 'R':
			x += d;break;
		case 'D':
			y -= d;break;
		case 'U':
			y += d;break;
	}
}
