    cout << (1 << i) << " ";
  }
  cout << endl;

  for (int i = 0; i < n; ++i) {
    string result = Solve(x[i] - odd, y[i], 30);
    if (odd) result = "R" + result;
    cout << result << endl;
  }

  return 0;
}

