string calc(int x,int y,int k){//2^0,2^1,...,2^k
    if(k==-1)return "";
    int f1=x<0,f2=y<0;
    x=abs(x),y=abs(y);
    string s;
    if(x>y)s='R'+calc(x-(1<<k),y,k-1);
    else s='U'+calc(x,y-(1<<k),k-1);
    if(f1)for(auto & c:s){
        if(c=='L')c='R';
        else if(c=='R')c='L';
    }
    if(f2)for(auto & c:s){
        if(c=='U')c='D';
        else if(c=='D')c='U';
    }
    return s;
}

