            int x = pts[i].first;
            int y = pts[i].second;
            string res;
            for (int j = 0; j < m; j++) {
                char cur;
                if (x > 0) {
                    x--;
                    cur = 'R';
                } else if (x < 0) {
                    x++;
                    cur = 'L';
                } else if (y > 0) {
                    y--;
                    cur = 'U';
                } else {
                    y++;
                    cur = 'D';
                }
                res += cur;
            }
            cout << res << "\n";
        }
    } else {
        cout << -1 << endl;
    }
}

