	vint V,W;
	for(int i=0;i<N;i++){
		V.pb(X[i]+Y[i]);
		W.pb(X[i]-Y[i]);
	}
	int arms=31;
	vint A={1};
	if(!flag)
		A.pb(1);
	for(int i=1;i<arms;i++)
		A.pb(A.back()*2);
	reverse(A.begin(),A.end());
	cout<<A.size()<<endl;
	for(int i=0;i<A.size();i++)
		cout<<A[i]<<(i==A.size()-1?'\n':' ');
	for(int i=0;i<N;i++){
		int v=0,w=0;
		for(int j=0;j<A.size();j++){
			if(v<=V[i] && w<=W[i]){
				cout<<'R';
				v+=A[j],w+=A[j];
			}
			else if(v<=V[i] && w>W[i]){
				cout<<'U';
				v+=A[j],w-=A[j];
			}
			else if(v>V[i] && w<=W[i]){
				cout<<'D';
				v-=A[j],w+=A[j];
			}
			else{
				cout<<'L';
				v-=A[j],w-=A[j];
			}
		}
		cout<<endl;
	}
	return 0;
}

