long long len[102];

void solve(long long x, long long y) {
    for (int i = 1; i <= cnt; ++i)
        (abs(x) > abs(y)) ? ((x < 0) ? (x += len[i], putchar('L'))
                                     : (x -= len[i], putchar('R')))
                          : ((y < 0) ? (y += len[i], putchar('D'))
                                     : (y -= len[i], putchar('U')));
    puts("");
}

