	template<class T>using pair = std::pair<T, T>;
	template<class T>constexpr T pow(T base, std::size_t p)
	{
		if (p <= 2)
		{
			return
				p == 0 ? T(1) :
				p == 1 ? base : base * base;
		}	
		auto r = lib::pow(lib::pow(base, p / 2), 2);
		if (p % 2 != 0)
		{
			r *= base;
		}
		return r;
	}

	template<class T>constexpr T gcd(T a, T b)
	{
