void solve(ll X,ll Y,int m){
  ll x0=0,y0=0;
  for(int i=m-1;i>=0;i--){
    if(abs(X-x0)>=abs(Y-y0)){
      if(X>x0){
	x0+=d[i];
	c[i]='R';
      }else{
	x0-=d[i];
	c[i]='L';
      }
    }else{
      if(Y>y0){
	y0+=d[i];
	c[i]='U';
      }else{
	y0-=d[i];
	c[i]='D';
      }
    }
  }
  //  cout<<"target:("<<X<<","<<Y<<"), result:("<<x0<<","<<y0<<")";
  cout<<c<<endl;
}

