#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
typedef long long ll;

struct P {
  ll x, y;
};
P ps[1000+10];
int n;
char buf[50];

const int K = 40;

void go(const vector<ll> &ds, int ith) {
  ll gX = ps[ith].x + ps[ith].y;
  ll gY = ps[ith].x - ps[ith].y;
  REP(i, ds.size()) {
    int bx, by;
    if(gX > 0) {
      gX -= ds[i];
      bx = 1;
    } else {
      gX += ds[i];
      bx = -1;
    }
    if(gY > 0) {
      gY -= ds[i];
      by = 1;
    } else {
      gY += ds[i];
      by = -1;
    }
    if(bx > 0 && by > 0) {
      buf[i] = 'R';
    } else if(bx > 0 && by < 0) {
      buf[i] = 'U';
    } else if(bx < 0 && by > 0) {
      buf[i] = 'D';
    } else {
      buf[i] = 'L';
    }
  }
  assert(gX == 0);
  assert(gY == 0);
}

void solve(void) {
  int parity = (ps[0].x + ps[0].y) & 1;
  REP(i, n) {
    if(((ps[i].x + ps[i].y) & 1) != parity) {
      puts("-1");
      return;
    }
  }
  vector<ll> ds;
  ds.push_back(1);
  REP(i, K-2) {
    ds.push_back(1LL << (i+1LL));
  }
  if(parity == 0) {
    ds.push_back(1);
  }
  sort(ds.begin(), ds.end());
  reverse(ds.begin(), ds.end());
  printf("%d\n", (int)ds.size());
  REP(i, ds.size()) {
    printf("%lld%c", ds[i], i == (int)ds.size()-1 ? '\n' : ' ');
  }
  REP(i, n) {
    go(ds, i);
    puts(buf);
  }
};

int main(void) {
  scanf("%d", &n);
  REP(i, n) {
    scanf("%lld %lld", &ps[i].x, &ps[i].y);
  }
  solve();

  return 0;
}

