int n,x[N],y[N];
int dx[4]={-1,1,0,0};
int dy[4]={0,0,-1,1};
char op[4]={'R','L','U','D'};
void solve(int x,int y){
    // 2^k  [0,2^{k+1}-1]
    string ans=""; 
    bool fg=0;
    if((x+y)%2==0)--x,fg=1;
    for(int k=30;k>=0;k--){
        for(int i=0;i<4;i++){
            int nx=x+dx[i]*(1<<k);
            int ny=y+dy[i]*(1<<k);
            if(abs(nx)+abs(ny)<=((1<<k)-1)) {
                //printf("k=%d\n", k);
                x=nx, y=ny; ans=ans+op[i];
                break;
            }
        }
    }   
    //printf("%d %d\n", x, y);
    if(fg){
        ans=ans+'R';
    }
    cout<<ans<<endl;
}
