[[noreturn]] void impossible() {
    PRINTLN(-1);
    exit(0);
}

void solve() {
    i64 N = RD();
    auto P = RD_VEC<pair<i64,i64>>(N);
    for(const auto& p : P) {
        i64 x,y; tie(x,y) = p;
        ASSERT(-10 <= x && x <= 10);
        ASSERT(-10 <= y && y <= 10);
    }

    bool even0 = (P[0].first+P[0].second)%2 == 0;
    {
        FOR(i, 1, N) {
            i64 x,y; tie(x,y) = P[i];
            bool even = (x+y)%2 == 0;
            if(even0 != even) impossible();
        }
    }

    vector<i64> D;
    for(i64 i = 30; i >= 0; --i)
        D.emplace_back(1LL << i);
    if(even0) D.emplace_back(1);
    i64 M = SIZE(D);

    PRINTLN(M);
    PRINTLN(D);

    for(const auto& p : P) {
        i64 x,y; tie(x,y) = p;

        i64 s =  x+y;
        i64 t = -x+y;

        string ans;
        for(i64 d : D) {
            if(s >= 0 && t >= 0) {
                s -= d;
                t -= d;
                ans.push_back('U');
            }
            else if(s >= 0 && t < 0) {
                s -= d;
                t += d;
                ans.push_back('R');
            }
            else if(s < 0 && t >= 0) {
                s += d;
                t -= d;
                ans.push_back('L');
            }
            else {
                s += d;
                t += d;
                ans.push_back('D');
            }
        }
        ASSERT(s == 0 && t == 0);

        PRINTLN(ans);
    }
}

