void work(int v, string d, string &s, vector<int> &ans) {
  //for (int j = 0; j <= 30; ++j) {
  for (int j = 30; j >= 0; --j) {
    if ((abs(v) >> j & 1) == 0) {
      continue;
    }
    int cnt = 0;
    for (int k = 0; k < (int)s.size(); ++k) {
      if (s[k] != '*') {
        continue;
      }
      if (ans[k] == j) {
        s[k] = d[v > 0];
        ++cnt;
      }
      if (cnt == 1) {
        break;
      }
    }
    if (cnt == 0) {
      for (int k = 0; k < (int)s.size(); ++k) {
        if (s[k] != '*') {
          continue;
        }
        if (ans[k] == j - 1) {
          s[k] = d[v > 0];
          ++cnt;
        }
        if (cnt == 2) {
          break;
        }
      }
      assert(cnt == 2);
    }
  }
}

