int64 rid[256]={};
int64 dx[4] = {1, -1, 1, -1};
int64 dy[4] = {1, 1, -1, -1};

vector<int64> calc(int64 x) {
	int64 xx = abs(x);
	bool sgn = x/xx < 0;
	vector<int64> v;
	int64 bef = 0;
	for (int64 i = 33; i >= 0; i--) {
		if (xx >> i & 1) {
			if (bef) {
				v.push_back(1-sgn);
			} else {
				v.push_back(sgn);
			}
			bef = 0;
		} else {
			if (bef) {
				v.push_back(sgn);
			} else {
				v.push_back(1-sgn);
			}
			bef = 1;
		}
	}
	return v;
}

