string getway(int x, int y) {
	int cx = 0;
	int cy = 0;
	string res;
	while (cx != x) {
		if (cx > x) {
			res.pb('L');
			cx--;
		} else {
			res.pb('R');
			cx++;
		}
	}
	while (cy != y) {
		if (cy > y) {
			res.pb('D');
			cy--;
		} else {
			res.pb('U');
			cy++;
		}
	}
	while (sz(res) < m) {
		res.pb('L');
		res.pb('R');
	}
	assert(sz(res) == m);
	return res;
}

