    if(calc(x+d,y)<now) {now=calc(x+d,y); ret='R';}
    if(calc(x,y-d)<now) {now=calc(x,y-d); ret='D';}
    if(calc(x,y+d)<now) {now=calc(x,y+d); ret='U';}
