using namespace std;

vector<int64_t> GetSegs(int max_odds)
{
    constexpr auto kMaxSegs = 40;
    vector<int64_t> segs(kMaxSegs);

    for (int i = 0; i < max_odds; i += 1) {
        segs[i] = 1;
    }
    for (int i = max_odds; i < kMaxSegs; i += 1) {
        segs[i] = (1LL << (i - max_odds + 1));
    }

    return segs;
}

int64_t DistFromOrigin(const pair<int64_t, int64_t> &pos)
{
    return abs(pos.first) + abs(pos.second);
}

char GetMode(int64_t len, int64_t next_dist, pair<int64_t, int64_t> &pos)
{
    const vector<char> kChars = {'U', 'D', 'R', 'L'};
    const vector<pair<int, int>> kMods = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

    for (size_t i = 0; i < kMods.size(); i += 1) {
        auto next_pos = make_pair(
            pos.first + kMods[i].first * len,
            pos.second + kMods[i].second * len
        );

        if (DistFromOrigin(next_pos) <= next_dist) {
            pos = next_pos;
            return kChars[i];
        }
    }
    return '\0';
}

string GetModes(const vector<int64_t> &segs, pair<int64_t, int64_t> pos)
{
    string modes(segs.size(), '\0');
    auto max_dist = accumulate(segs.begin(), segs.end(), 0);

    for (int i = segs.size() - 1; i >= 0; i -= 1) {
        modes[i] = GetMode(segs[i], max_dist - segs[i], pos);
        max_dist -= segs[i];
    }

    return modes;
}

int main()
{
    int n;
    cin >> n;

    vector<pair<int, int>> vec(n);
    auto total_parity = -1;
    auto max_odds = 0;
    auto good = true;

    for (auto &p : vec) {
        cin >> p.first >> p.second;

        auto odds = abs(p.first) % 2 + abs(p.second) % 2;
        max_odds = max(max_odds, odds);

        if (total_parity == -1) {
            total_parity = (odds % 2);
        } else if (good) {
            good = (total_parity == (odds % 2));
        }
    }

    if (!good) {
        cout << "-1\n";
        return 0;
    }

    auto segs = GetSegs(max_odds);
    cout << segs.size() << "\n";

    for (const auto &len : segs) {
        cout << len << " ";
    }
    cout << "\n";

    for (const auto &p : vec) {
        auto modes = GetModes(segs, p);
        cout << modes << "\n";
    }

    return 0;
}

