    cin >> N;

    vector<i64> X(N),Y(N);
    rep(i,0,N) cin >> X[i] >> Y[i];

    rep(i,0,N) if(((X[i]+Y[i])%2+2)%2!=((X[0]+Y[0])%2+2)%2){
        cout << -1 << endl;
        return;
    }

    vector<i64> U(N),V(N);
    rep(i,0,N){
        U[i]=X[i]+Y[i];
        V[i]=X[i]-Y[i];
    }

    i64 m=32;
    vector<i64> d(m);
    d[0]=1;
    rep(i,1,m) d[i]=d[i-1]*2;
