        rep(j,0,m){
            i64 u1=u-d[j],u2=u+d[j];
            if(abs(U[i]-u1)<=abs(U[i]-u2)){
                u=u1;
                s[j]=-1;
            }else{
                u=u2;
                s[j]=1;
            }
        }
        rep(j,0,m){
            i64 v1=v-d[j],v2=v+d[j];
            if(abs(V[i]-v1)<=abs(V[i]-v2)){
                v=v1;
                t[j]=-1;
            }else{
                v=v2;
                t[j]=1;
            }
        }

        string tmp;
        rep(j,0,m){
            if(s[j]==-1 and t[j]==-1) tmp+='L';
            else if(s[j]==1 and t[j]==1) tmp+='R';
            else if(s[j]==-1 and t[j]==1) tmp+='D';
            else tmp+='U';
        }

        ans[i]=tmp;
    }

    cout << m << endl;
    rep(i,0,m){
        cout << d[i];
        if(i==m-1) cout << endl;
        else cout << " ";
    }

    rep(i,0,N) cout << ans[i] << endl;
}

