		if(x[u]==0&&y[u]==-1)Move[u][++Move[u][0]]=3;
		return;
	}
	x[u]-=(1<<d);
	if(in(u,d-1)){
		Move[u][++Move[u][0]]=0;
		return;
	}
	x[u]+=(1<<d);
	x[u]+=(1<<d);
	if(in(u,d-1)){
		Move[u][++Move[u][0]]=1;
		return;
	}
	x[u]-=(1<<d);
	y[u]-=(1<<d);
	if(in(u,d-1)){
