inline void gao(int x,int y,int k)
{
	if(k==-1)return;
	if(abs(x)>=(1<<k)){
		if(x>0){
			cout<<'R';
			x-=(1<<k);
			return gao(x,y,k-1);
		}
		else{
			cout<<'L';
			x+=(1<<k);
			return gao(x,y,k-1);
		}
	}
	if(abs(y)>=(1<<k)){
		if(y>0){
			cout<<'U';
			y-=(1<<k);
			return gao(x,y,k-1);
		}
		else{
			cout<<'D';
			y+=(1<<k);
			return gao(x,y,k-1);
		}
	}
	if(abs(x)>abs(y)){
		if(x>0){
			cout<<'R';
			x-=1<<k;
			return gao(x,y,k-1);
		}
		else{
			cout<<'L';
			x+=1<<k;
			return gao(x,y,k-1);
		}
	}
	else{
		if(y>0){
			cout<<'U';
			y-=1<<k;
			return gao(x,y,k-1);
		}
		else{
			cout<<'D';
			y+=1<<k;
