// AtCoder Beginner Contest 111 - Problem D: Robot Arms (https://beta.atcoder.jp/contests/abc111/tasks/arc103_b)
#include <bits/stdc++.h>

using namespace std;

using ii = pair<int, int>;

#define REP(i, a, b) for (int (i) = (a); (i) <= (b); (i)++)
#define REPN(i, N) for (int (i) = 0; (i) < N; (i)++)
#define DEC(i, b, a) for (int (i) = (b); (i) >= (a); (i)--)
#define DECN(i, N) for (int (i) = N - 1; (i) >= 0; (i)--)

#define LOG(var, sep) (cerr << #var << " = " << (var) << (sep))
#define LOGM(msg) (cerr << (msg))
#define LOGV(vec, sep) { cerr << #vec << " ="; for (const auto& v : (vec)) cerr << " " << v; cerr << (sep); }
#define LOGA(arr, N, sep) { cerr << #arr << " ="; for (int i = 0; i < N; ++i) cerr << " " << (arr)[i]; cerr << (sep); }
#define LOGA2(arr, N, M, sep) { cerr << #arr << " =\n"; for (int i = 0; i < N; ++i) { for (int j = 0; j < M; ++j) cerr << (arr)[i][j] << " "; cerr << endl; } cerr << (sep); }

ostream& operator<<(ostream& os, const ii& p)
{
    os << "(" << p.first << ", " << p.second << ")";
    return os;
}

const int MAX { 1010 };

ii ps[MAX];

void solve(int N)
{
    // A paridade da soma das coordenadas deve ser a mesma da soma dos comprimentos
    auto p = (ps[0].first + ps[0].second) & 1;
    int max_dist = 0;

    REPN(i, N)
    {
        if (((ps[i].first + ps[i].second) & 1) != p)
        {
            cout << -1 << endl;
            return;
        }

        max_dist = max(max_dist, abs(ps[i].first) + abs(ps[i].second));
    }

    int m = 0;
    vector<int> ds;

    while ((1 << m) - 1 < max_dist)
    {
        ds.push_back(1 << m);
        ++m;
    }

    if (p == 0)
    {
        ++m;
        ds.push_back(1);
    }

    cout << m << endl;

    REPN(i, m)
        cout << ds[i] << (i + 1 == m ? "\n" : " ");

    REPN(i, N)
    {
        int x, y;
        tie(x, y) = ps[i];

        string cmds = "";

        for (int k = m - 1; k >= 0; --k)
        {
            auto d = ds[k];
            auto prev = k ? ds[k - 1] : 0;
            auto M = (1 << prev) - 1;

            if (abs(x - d) + abs(y) <= M)
            {
                cmds += 'R';
                x -= d;
            } else if (abs(x + d) + abs(y) <= M)
            {
                cmds += 'L';
                x += d;
            } else if (abs(x) + abs(y - d) <= M)
            {
                cmds += 'U';
                y -= d;
            } else 
            {
                cmds += 'D';
                y += d;
            }
        }

        reverse(cmds.begin(), cmds.end());

        cout << cmds << '\n';
    }
}

int main()
{
    ios::sync_with_stdio(false);

    int N;
    cin >> N;

    REPN(i, N)
        cin >> ps[i].first >> ps[i].second;

    solve(N);

    return 0;
}

