// first subtask
bool done[50][42][42], memo[50][42][42];
int n;
int x[1010], y[1010];
vector<char> order;
bool poss(int a, int x, int y, int save = 0)
{
	if (x < 0 || x < 0 || x > 40 || y > 40) return 0;
	if (!save && done[a][x][y]) return memo[a][x][y];
	done[a][x][y] = 1;
	if (!a)
	{
		if (x == 20 && y == 20) return memo[a][x][y] = 1;
		return memo[a][x][y] = 0;
	}
	if (poss(a-1, x-1, y))
	{
		if (save) order.push_back('R'), poss(a-1, x-1, y, 1);
		return memo[a][x][y] = 1;
	}
	if (poss(a-1, x+1, y))
	{
		if (save) order.push_back('L'), poss(a-1, x+1, y, 1);
		return memo[a][x][y] = 1;
	}
	if (poss(a-1, x, y-1))
	{
		if (save) order.push_back('U'), poss(a-1, x, y-1, 1);
		return memo[a][x][y] = 1;
	}
	if (poss(a-1, x, y+1))
	{
		if (save) order.push_back('D'), poss(a-1, x, y+1, 1);
		return memo[a][x][y] = 1;
	}
	return memo[a][x][y] = 0;
}
