		}
		if (!fails)
		{
			printf("%d\n", len);
			for (int i = 0; i < len; i++)
			{
				printf("%d ", 1);
			}
			printf("\n");
			for (int i = 0; i < n; i++)
			{
				order.clear();
				poss(len, x[i], y[i], 1);
				for (auto a : order) printf("%c", a);
				printf("\n");
			}
			return 0;
		}
	}
	printf("-1\n");
}

