void rec(ll id, ll x, ll y, ll ind) {
    if (ind == 0)
        return;
    if (y > x && y > -x) {
        ans[id][ind] = 'U';
        rec(id, x, y - ln[ind], ind - 1);
    } else if (y > x && y < -x) {
        ans[id][ind] = 'L';
        rec(id, x + ln[ind], y, ind - 1);
    } else if (y < x && y < -x) {
        ans[id][ind] = 'D';
        rec(id, x, y + ln[ind], ind - 1);
    } else {
        ans[id][ind] = 'R';
        rec(id, x - ln[ind], y, ind - 1);
    }
}


