int x[N],y[N],par[N];
vector<char>ans[N];
vector<LL> chos;

int can(LL x,LL y,int plc){
  if((abs(x)+abs(y)<=oL(plc)))return 1;
  return 0;
}

void dfs(LL x,LL y,int plc,int id){
  if(plc<0){
    return;
  }
  if     (can(x+oL(plc),y,plc))ans[id].pb('R'),dfs(x+oL(plc),y,plc-1,id);
  else if(can(x-oL(plc),y,plc))ans[id].pb('L'),dfs(x-oL(plc),y,plc-1,id);
  else if(can(x,y+oL(plc),plc))ans[id].pb('U'),dfs(x,y+oL(plc),plc-1,id);
  else if(can(x,y-oL(plc),plc))ans[id].pb('D'),dfs(x,y-oL(plc),plc-1,id);
}

const int MAXN=32;

void Solve(){
  int n;
  cin>>n;
  rep(i,1,n){
    cin>>x[i]>>y[i];
    x[i]=-x[i],y[i]=-y[i];
    par[i]=((x[i]+y[i])%2+2)%2;
  }
  rep(i,2,n){
    if(par[i]!=par[i-1]){
      cout<<-1<<endl;
      return;
    }
  }
  if(par[1]==0){
    rep(i,1,n){
      if(abs(x[i])>abs(y[i])){
        if(x[i]<0)ans[i].pb('R'),x[i]++;
        else ans[i].pb('L'),x[i]--;
      }
      else{
        if(y[i]<0)ans[i].pb('U'),y[i]++;
        else ans[i].pb('D'),y[i]--;
      }
    }
    chos.pb(1);
  }
  rep(i,0,MAXN){
    chos.pb(oL(i));
  }
  rep(i,1,n){
    dfs(x[i],y[i],MAXN,i);
    reverse(ans[i].begin()+(par[1]==0),ans[i].end());
  }
  cout<<sz(chos)<<endl;
  for(auto p:chos)cout<<p<<" ";cout<<endl;
  rep(i,1,n){
    for(auto p:ans[i])cout<<p;
    cout<<'\n';
  }
}

