        ds[M - 1] = 1;
    }
    outln(ds.size());
    outln(ds);
    const ll D = std::accumulate(ds.begin(), ds.end(), 0LL);
    for (int i = 0; i < N; i++) {
        std::vector<bool> xp(M, true);
        std::vector<bool> yp(M, true);
        const ll x = xs[i], y = ys[i];
        const ll mx = (D - x) / 2, my = (D - y) / 2;
        for (int j = 0; j < M; j++) {
            if (btest(mx, j)) { xp[j] = false; }
            if (btest(my, j)) { yp[j] = false; }
        }
        std::string ans(M, ' ');
        for (int i = 0; i < M; i++) {
            if (xp[i]) {
                if (yp[i]) {
                    ans[i] = 'R';
                } else {
                    ans[i] = 'D';
                }
            } else {
                if (yp[i]) {
                    ans[i] = 'U';
                } else {
                    ans[i] = 'L';
                }
            }
        }
        outln(ans);
        auto check = [&]() {
            ll x = 0, y = 0;
            for (int i = 0; i < M; i++) {
                if (ans[i] == 'R') {
                    x += ds[i];
                } else if (ans[i] == 'D') {
                    y -= ds[i];
                } else if (ans[i] == 'L') {
                    x -= ds[i];
                } else {
                    y += ds[i];
                }
            }
            assert(x == Xs[i] and y == Ys[i]);
        };
        check();
    }
    return 0;
}

