    cin >> x[i] >> y[i];
  }

  bool is_small_case = true;
  for (int i = 0; i < n; i++) {
    is_small_case &= -10 <= x[i] && x[i] <= 10 && -10 <= y[i] && y[i] <= 10;
  }
  if (!is_small_case) {
    return 1;
  }

  bool ok = true;
  for (int i = 1; i < n; i++) {
    ok &= abs(x[0] + y[0]) % 2 == abs(x[i] + y[i]) % 2;
  }
  if (!ok) {
    cout << -1 << endl;
    return 0;
  }

  int m = 20 - (x[0] + y[0]) % 2;
