vector<char> solve(int x, int y){
    vector<char> ANS;
    char R = 'R', L = 'L', U = 'U', D = 'D';
    if(x < 0)swap(R, L);
    if(y < 0)swap(U, D);

    bitset<32> X(abs(x));
    REP(i, 1, 4){
        if(X[i]){
            ANS.push_back(R);
            ANS.push_back(R);
        }else{
            ANS.push_back(R);
            ANS.push_back(L);
        }
    }

    bitset<32> Y(abs(y));
    REP(i, 1, 4){
        if(Y[i]){
            ANS.push_back(U);
            ANS.push_back(U);
        }else{
            ANS.push_back(U);
            ANS.push_back(D);
        }
    }

    if((abs(x) + abs(y)) % 2 == 1){
        if(abs(x) % 2)ANS.push_back(R);
        else ANS.push_back(U);
    }else{
        if(abs(x) % 2 == 1){
            ANS.push_back(R);
            ANS.push_back(U);
        }else{
            ANS.push_back(R);
            ANS.push_back(L);
        }
    }
    return ANS;
}

