string Solve(ll x, ll y, ll at) {
  if (at < 0) return "";
  assert(abs(x) + abs(y) <= (1 << (at + 1)) - 1);
  int r = (1 << at) - 1;
  int d = 1 << at;
  if (abs(x - d) + abs(y) <= r) return Solve(x - d, y, at - 1) + "R";
  if (abs(x + d) + abs(y) <= r) return Solve(x + d, y, at - 1) + "L";
  if (abs(x) + abs(y - d) <= r) return Solve(x, y - d, at - 1) + "U";
  if (abs(x) + abs(y + d) <= r) return Solve(x, y + d, at - 1) + "D";
  assert(false);
}

