		int now = 1 << i;
		if(abs(x) >= now) {
			if(x > 0) x -= now, putchar('R');
			else x += now, putchar('L');
		}
		else if(abs(y) >= now) {
			if(y > 0) y -= now, putchar('U');
			else y += now, putchar('D');
		}
		else {
			if(abs(x) > abs(y)) {
				if(x < 0) x += now, putchar('L');
				else x -= now, putchar('R');
			}
			else {
				if(y < 0) y += now, putchar('D');
