	{
		m++; d[m]=(1LL<<i);
		activate(1LL<<i,1LL<<i);
	}
	if(abs(x[1]+y[1])%2==1)
	{
		m++; d[m]=1;
		activate(1,0);
	}
	cout<<m<<"\n";
	for(i=1 ; i<=m ; i++) cout<<d[i]<<" ";
	for(i=1 ; i<=n ; i++) cout<<order[i]<<"\n";
	return 0;
}

