typedef long long LL;

LL pos[2][100005];

void solve(LL id,LL num){
	LL sgn = 1,tmp = num;
	if(num < 0) sgn = -1,tmp = -num;
	for(LL i = 0;i <= 19;i ++){
		pos[id][i] = tmp % 3;
		tmp /= 3;
	}
	for(LL i = 0;i <= 19;i ++){
		if(pos[id][i] == 2 || pos[id][i] == -2){
			pos[id][i + 1] += pos[id][i] / 2;
			pos[id][i] = - pos[id][i] / 2;
		}
		else if(pos[id][i] == 3 || pos[id][i] == -3){
			pos[id][i + 1] += pos[id][i] / 3;
			pos[id][i] = 0;
		}
	}
	for(LL i = 0;i <= 19;i ++) pos[id][i] *= sgn;
}

