int main()
{
    int N;
    std::cin >> N;
    std::vector<ll> pow(39, 1);
    for (int i = 1; i < 39; i++) { pow[i] = pow[i - 1] * 2; }
    using P = std::pair<ll, ll>;
    std::vector<P> p(N);
    for (int i = 0; i < N; i++) { std::cin >> p[i].first >> p[i].second; }
    const ll S = std::abs(p[0].first) + std::abs(p[0].second);
    for (int i = 1; i < N; i++) {
        if (S % 2 != (std::abs(p[i].first) + std::abs(p[i].second)) % 2) { return std::cout << -1 << std::endl, 0; }
    }
    if (S % 2 == 0) { pow.push_back(1); }
    const ll D = (1LL << 39) - (S % 2 == 1 ? 1 : 0);
    const ll NUM = 39 + (S % 2 == 1 ? 0 : 1);
    std::cout << NUM << std::endl;
    for (int i = 0; i < 39; i++) { std::cout << (1LL << i) << " "; }
    if (S % 2 == 0) { std::cout << 1 << " "; }
    std::cout << std::endl;
    for (int i = 0; i < N; i++) {
        const ll S = std::abs(p[i].first) + std::abs(p[i].second);
        ll P = (D + S) / 2, M = D - P;
        using Q = std::pair<ll, ll>;
        std::vector<Q> log(NUM);
        ll x = p[i].first, y = p[i].second;
        if (S % 2 == 0 and M % 2 == 1) { x += (x < 0 ? -1 : 1), M -= 1; }
        std::bitset<40> ng(M), ok(P);
        ll X = std::abs(p[i].first), Y = std::abs(p[i].second);
        for (int i = 0; i < 39; i++) {
            if (ng[i] and ((X >> i) & 1)) { log[i] = {0, -1 * (x < 0 ? -1 : 1)}, X += (1LL << i); }
            if (ng[i] and ((Y >> i) & 1)) { log[i] = {1, -1 * (y < 0 ? -1 : 1)}, Y += (1LL << i); }
            if (ok[i] and ((X >> i) & 1)) { log[i] = {0, 1 * (x < 0 ? -1 : 1)}, X -= (1LL << i); }
            if (ok[i] and ((Y >> i) & 1)) { log[i] = {1, 1 * (y < 0 ? -1 : 1)}, Y -= (1LL << i); }
        }
        if (S % 2 == 0 and M % 2 == 1) { log[NUM - 1] = {1, (x < 0 ? 1 : -1)}; }
        for (int i = 0; i < NUM; i++) {
            if (log[i].first == 0) {
                if (log[i].second == 1) {
                    std::cout << "R";
                } else {
                    std::cout << "L";
                }
            } else {
                if (log[i].second == 1) {
                    std::cout << "U";
                } else {
                    std::cout << "D";
                }
            }
        }
        std::cout << std::endl;
    }
    return 0;
}

