typedef long long ll;
bool inv[1005], del[35];
std::pair<std::vector<ll>, std::vector<std::string> > work(int n, int *arr)
{
	for (int i = 0; i < n; i++)
	{
		if (arr[i] < 0)
		{
			arr[i] *= -1;
			inv[i] = true;
		}
		else
			inv[i] = false;
	}
	std::vector<ll> ans, real;
	std::vector<std::string> way(n), realway(n);
	if (arr[0] & 1 ^ 1)
	{
		ans.pb(1);
		for (int i = 0; i < n; i++)
			way[i] += inv[i] ? '+' : '-';
	}
	const int mx = 6;
	for (int i = 0; i < mx; i++)
		ans.pb(1 << i);
	for (int i = 0; i < n; i++)
	{
		for (int j = 0; j < mx; j++)
		{
			if (j == mx - 1 || (arr[i] / 2 & (1 << j)))
				way[i] += inv[i] ? '-' : '+';
			else
				way[i] += inv[i] ? '+' : '-';
		}
	}
	return {ans, way};
}
