      A -= 2 * v[i];
      a.push_back(-1);
    }else{
      a.push_back(1);
    }

  }

  reverse( a.begin(), a.end() );

  int B = (1LL<<bit) - 1;

  if( even ) B++;

  vector<int> b;

  for(int i=(int)v.size()-1;i>=0;i--){

    if( B - 2 * v[i] >= V ){
      B -= 2 * v[i];
      b.push_back(-1);
    }else{
      b.push_back(1);
    }

  }

