void solver() {
    int N = input();
    vector< i64 > X(N), Y(N);
    range(i, 0, N) {
        cin >> X[i] >> Y[i];
    }

    range(i, 0, N) {
        i64 x = X[i] + Y[i];
        i64 y = X[i] - Y[i];
        X[i] = x;
        Y[i] = y;
    }

    range(i, 1, N) {
        if ((X[i - 1] & 1) != (X[i] & 1)) {
            cout << -1 << endl;
            return;
        }
    }

    bool f = !(X[0] & 1);

    vector< i64 > d(39, 1);
    range(i, 1, d.size()) d[i] = d[i - 1] * 2;
    if (f) d.push_back(1);

    whole(reverse, d);

    cout << d.size() << endl;
    cout << d << endl;

    range(i, 0, N) {
        i64 x = X[i];
        i64 y = Y[i];
        string ans;

        if (f) {
            ans += 'L';
            x += 1;
            y += 1;
        }

        range(i, f, d.size()) {
            i64 mv = d[i];
            if (x >= 0 && y >= 0) {
                ans += 'R';
                x -= mv;
                y -= mv;
            } else if (x < 0 && y >= 0) {
                ans += 'D';
                x += mv;
                y -= mv;
            } else if (x >= 0 && y < 0) {
                ans += 'U';
                x -= mv;
                y += mv;
            } else {
                ans += 'L';
                x += mv;
                y += mv;
            }
        }

        cout << ans << endl;
    }
}

