        if(tag == 0) dx--, putchar('U');
        for(int i = 1; i < m; i++) {
            long long tt = ((dx + dy) % 4 + 4) % 4;
            if(dx % 2) {
                if(tt == 3) putchar('U'), dx--, dx /= 2, dy /= 2;
                else putchar('D'), dx++, dx /= 2, dy /= 2;
            }
            else {
                if(tt == 3) putchar('R'), dy--, dx /= 2, dy /= 2;
                else putchar('L'), dy++, dx /= 2, dy /= 2;
            }
            // cerr << dx << ' ' << dy << endl;
        }
        if(dx == 1) puts("U");
        else if(dx == -1) puts("D");
        else if(dy == 1) puts("R");
        else puts("L");
    }
    return 0;
}

