#include <bits/stdc++.h>

#define NM 1002
#define ll long long

using namespace std;

ll n, X[NM], Y[NM];

int m = 4;

ll d[32];

ll x[32], y[32];

int main()
{
    cin >> n;
    bool ok = true;
    for(int i = 1; i <= n; i++)
    {
        cin >> X[i] >> Y[i];
        if(abs(X[i] + Y[i]) % 2 != abs(X[1] + Y[1]) % 2)
            ok = false;
    }
    if(!ok)
    {
        cout << "-1\n";
        return 0;
    }
    d[1] = 1;
    for(int i = 2; i <= m; i++)
        d[i] = d[i - 1] * 2;
    bool fix = false;
    if(abs(X[1] + Y[1]) % 2 == 0)
    {
        m++;
        d[m] = 1;
        fix = true;
    }
    cout << m << "\n";
    for(int i = 1; i <= m; i++)
        cout << d[i] << " ";
    cout << "\n";
    for(int i = 1; i <= n; i++)
    {
        x[m] = X[i];
        y[m] = Y[i];
        string ans = "";
        ll p2 = 1;
        for(int j = 1; j <= m - 1; j++)
            p2 *= 2;
        for(int j = m - 1; j >= 0; j--)
        {
            x[j] = x[j + 1];
            y[j] = y[j + 1];
            if(abs(x[j] - d[j + 1]) + abs(y[j]) <= p2 - 1 + fix)
            {
                ans += "R";
                x[j] -= d[j + 1];
            }
            else if(abs(x[j] + d[j + 1]) + abs(y[j]) <= p2 - 1 + fix)
            {
                ans += "L";
                x[j] += d[j + 1];
            }
            else if(abs(y[j] - d[j + 1]) + abs(x[j]) <= p2 - 1 + fix)
            {
                ans += "U";
                y[j] -= d[j + 1];
            }
            else if(abs(y[j] + d[j + 1]) + abs(x[j]) <= p2 - 1 + fix)
            {
                ans += "D";
                y[j] += d[j + 1];
            }
            p2 /= 2;
        }
        reverse(ans.begin(), ans.end());
        cout << ans << "\n";
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
const int N = 1009;
int n, x[N], y[N], vis = -1, maxn, cnt;
ll a[45];
char ans[45], dir[4] = {'L', 'R', 'D', 'U'};
double dis[4];

void read(int &x) {
	char c; int f = 1;
	for (c = getchar(); c < '0' || c > '9'; c = getchar()) if (c == '-') f = 0;
	for (; c >= '0' && c <= '9'; c = getchar()) x = (x << 3) + (x << 1) + (c ^ 48);
	x = f ? x : -x;
}

inline int Log(int x) {
	int t = (int)(log(x) / log(2));
	if ((1 << t) == x) return t;
	return t + 1;
}

inline double get_dis(ll x1, ll Y1, ll x2, ll y2) {return sqrt((x1 - x2) * (x1 - x2) + (Y1 - y2) * (Y1 - y2));}

int main() {
	read(n);
	for (int i = 1; i <= n; ++ i) {
		read(x[i]), read(y[i]);
		if (((x[i] + y[i]) % 2 && vis == 0) || ((x[i] + y[i]) % 2 == 0 && vis == 1)) return puts("-1"), 0;
		vis = (x[i] + y[i]) % 2;
		maxn = max(maxn, abs(x[i]) + abs(y[i]));
	}
	if (vis == 0) a[++ cnt] = 1;
	for (int i = 1; i <= Log(maxn); ++ i) a[++ cnt] = 1LL << i - 1;
	printf("%d\n", cnt);
	for (int i = 1; i <= cnt; ++ i) printf("%lld ", a[i]); putchar('\n');
	for (int i = 1; i <= n; ++ i) {
		ll nx = 0, ny = 0;
		for (int j = cnt; j; -- j) {
			dis[0] = get_dis(nx - a[j], ny, x[i], y[i]);
			dis[1] = get_dis(nx + a[j], ny, x[i], y[i]);
			dis[2] = get_dis(nx, ny - a[j], x[i], y[i]);
			dis[3] = get_dis(nx, ny + a[j], x[i], y[i]);
			int minnum = 0;
			for (int k = 0; k < 4; ++ k) if (dis[minnum] > dis[k]) minnum = k;
			if (minnum == 0) nx -= a[j];
			if (minnum == 1) nx += a[j];
			if (minnum == 2) ny -= a[j];
			if (minnum == 3) ny += a[j];
			ans[j] = dir[minnum];
		}
		for (int j = 1; j <= cnt; ++ j) putchar(ans[j]); putchar('\n');
	}
	return 0;
}

