        std::cout << d[i] << " \n"[i == (int)d.size() - 1];

    std::vector<char> com = { 'L', 'U', 'D', 'R' };
    for (int t = 0; t < n; t++) {
        long long tu = x[t] + y[t];
        long long tv = x[t] - y[t];
        std::string ans = "";
        for (int i = 0; i < (int)d.size(); i++) {
            bool uflag = tu >= 0;
            bool vflag = tv >= 0;
            tu += (uflag ? -1 : 1)*d[i];
            tv += (vflag ? -1 : 1)*d[i];
            ans += com[uflag + 2 * vflag];
        }
