            }
            if (Abs(nowx-a[i].x)+Abs(nowy+v[j]-a[i].y)<now) {
                ch='U';
                now=Abs(nowx-a[i].x)+Abs(nowy+v[j]-a[i].y);
            }
            if (Abs(nowx-a[i].x)+Abs(nowy-v[j]-a[i].y)<now) {
                ch='D';
                now=Abs(nowx-a[i].x)+Abs(nowy-v[j]-a[i].y);
            }
