#include <bits/stdc++.h>
using namespace std;
using i64 = int64_t;
using vi = vector<i64>;
using vvi = vector<vi>;

map<pair<int, int>, char> mp;

i64 sum;
vi arms;

void printvec(vi& x, int size = 0) {
    if (x.size() == 0) {
        cout << endl;
        return;
    }
    cout << x.front();
    for (int i = 1; i < (size == 0 ? x.size() : size); i++) {
        cout << " " << x[i];
    }
    cout << endl;
}

vi make_use(i64 x) {
    vi ret(arms.size());
    i64 p = (x + sum) / 2;
    for (int i = arms.size() - 1; i >= 0; i--) {
        if (p >= arms[i]) {
            ret[i] = 1;
            p -= arms[i];
        }
    }
    assert(p == 0);
    return ret;
}

string make_string(i64 x, i64 y) {
    i64 xx = x - y, yy = x + y;
    string ret = "";

    vi usex = make_use(xx), usey = make_use(yy);
    for (int i = 0; i < arms.size(); i++) {
        ret += mp[make_pair(usex[i], usey[i])];
    }

    return ret;
}

int main() {
    int n;
    cin >> n;
    vi xs, ys;
    int ok = -1;
    for (int i = 0; i < n; i++) {
        i64 x, y;
        cin >> x >> y;
        if (ok == -1) {
            ok = ((x + y) % 2 + 2) % 2;
        } else {
            if (ok != ((x + y) % 2 + 2) % 2) {
                cout << -1 << endl;
                return 0;
            }
        }
        xs.push_back(x);
        ys.push_back(y);
    }

    for (i64 i = 1; i < i64(1) << 35; i <<= 1) {
        sum += i;
        arms.push_back(i);
    }

    if (ok == 0) {
        // 最初にD
        for (int i = 0; i < n; i++) {
            ys[i]++;
        }
        cout << 1 + arms.size() << endl;
        cout << 1 << " ";
    } else {
        cout << arms.size() << endl;
    }
    printvec(arms);

    mp[make_pair(1, 1)] = 'R';
    mp[make_pair(0, 0)] = 'L';
    mp[make_pair(0, 1)] = 'U';
    mp[make_pair(1, 0)] = 'D';

    for (int i = 0; i < n; i++) {
        if (ok == 0) {
            cout << "D";
        }
        cout << make_string(xs[i], ys[i]) << endl;
    }
}

