		getint(X[i]), getint(Y[i]), mx = max(mx, abs(X[i]) + abs(Y[i]));
		if(isodd == -1) isodd = (X[i] ^ Y[i]) & 1;
		else if(isodd != ((X[i] ^ Y[i]) & 1)) return puts("-1"), 0;
