int in() { int x; scanf("%d", &x); return x; }
ll lin() { ll x; scanf("%lld", &x); return x; }

VI count(ll x, VL &d){
    int m = d.size();
    if (x < 0){
        VI ret = count(-x, d);
        REP(i,m) ret[i] *= -1;
        return ret;
    }
    VI ret(m);
    ll s = 0;
    FORR(i,m-1,0){
        if (s + d[i] - x < x - s){
            ret[i] = 1;
            s += d[i];
        }else if (x - s + d[i] - x < s - x){
            ret[i] = -1;
            s -= d[i];
        }
    }
    return ret;
}

int main() {
    int n;
    cin >> n;
    VL x(n), y(n);
    REP(i,n){
        cin >> x[i] >> y[i];
    }

    int p = abs(x[0] + y[0]) % 2;
    REP(i,n){
        if (abs(x[i] + y[i]) % 2 != p){
            cout << -1 << endl;
            return 0;
        }
    }

    int m = 40;
    VL d(m, 1);
    REP(i,m-2){
        d[i+2] = 3 * d[i];
    }
    cout << m << endl;
    REP(i,m) cout << d[i] << " ";
    cout << endl;
    REP(i,n){
        VI px(m), py(m);
        px = count(x[i], d);
        py = count(y[i], d);
        string s;
        REP(j,m){
            if ((px[j] + py[j]) % 2 == 0){
                continue;
            }
            if (px[j] > 0){
                px[j] -= 3;
                px[j+1]++;
            }else if (px[j] < 0){
                px[j] += 3;
                px[j+1]--;
            }else if (py[j] > 0){
                py[j] -= 3;
                py[j+1]++;
            }else if (py[j] < 0){
                py[j] += 3;
                py[j+1]--;
            }
            if (px[j] > 0) s += string(px[j], 'R');
            if (px[j] < 0) s += string(-px[j], 'L');
            if (py[j] > 0) s += string(py[j], 'U');
            if (py[j] < 0) s += string(-py[j], 'D');
            if (px[j] == 0 && py[j] == 0) s += "LR";
        }
        cout << s << endl;
    }
    return 0;
}

