    int c;
    c=abs(x[0]+y[0])%2;
    FOR(i,1,n){
        if(abs(x[i]+y[i])%2!=c){
            c=-1;
            break;
        }
    }
    if(c==-1){
        cout<<-1<<endl;
        return 0;
    }
    if(c==1){
        cout<<31<<endl;
        rep(i,31) cout<<(1<<(30-i))<<" ";
        cout<<endl;
    }
    else{
        cout<<32<<endl;
