        for(int i=30;i>=0;--i){
            ll tmp=1<<i;
            if(tu>=0&&tv>=0){
                ans+="R";
                tu-=tmp,tv-=tmp;
            }
            else if(tu<0&&tv<0){
                ans+="L";
                tu+=tmp,tv+=tmp;
            }
            else if(tu>=0&&tv<0){
                ans+="U";
                tu-=tmp,tv+=tmp;
            }
            else if(tu<0&&tv>=0){
                ans+="D";
                tu+=tmp,tv-=tmp;
            }
        }
        cout<<ans<<endl;
    }
    return 0;
}

