void input()
{
	read(n);
	for(int i=1; i<=n; i++) read(px[i]), read(py[i]);
}

int dis(int x, int y)
{
	return abs(x) + abs(y);
}

void get_seq(int x, int y, int step)
{
	if(!step) step = 1;
	int dr = dis(x-step, y), dl = dis(x+step, y);
	int du = dis(x, y-step), dd = dis(x, y+step);
	int mnd = min(min(dl, dr), min(dd, du));
	if(!x && !y) putchar('\n');
	else if(mnd == dr) putchar('R'), get_seq(x-step, y, step/2);
	else if(mnd == dl) putchar('L'), get_seq(x+step, y, step/2);
	else if(mnd == du) putchar('U'), get_seq(x, y-step, step/2);
	else if(mnd == dd) putchar('D'), get_seq(x, y+step, step/2);
	else assert(0);
}

void work()
{
	bool tag = (px[1]&1) ^ (py[1]&1);
