	else printf("32\n");
	for(int i=30; i>=0; i--) printf("%d ", mov(i));
	if(!tag) printf("%d", mov(0));
	putchar('\n');
	for(int i=1; i<=n; i++) get_seq(px[i], py[i], mov(30));
}

int main()
{
	input();
