int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	int n; cin>>n;
	vector<ii> vec;
	ll sum = 0; 
	for(int i=0;i<n;i++)
	{
		ll x,y; cin>>x>>y; vec.pb(mp(x,y)); sum=(x+y)%2;
		if(sum<0) sum+=2;
	}
	for(int i=0;i<n;i++)
	{
		ll s2 = (vec[i].fi+vec[i].se)%2;
		if(s2<0) s2+=2;
		if(s2!=sum){cout<<-1<<'\n'; return 0;}
	}
