	ma[mp(0,1)] = 'D'; ma[mp(0,-1)] = 'U';
	if(sum==0)
	{
		res.pb(1);
		for(int i=0;i<n;i++)
		{
			vec[i].fi++;
			ans[i]+='L';
		}
