void solve(int a, int b, int x) {
	if(x<0) {printf("\n"); return;}
	if(x==0) {
		if(a==1) printf("R");
		else if(a==-1) printf("L");

		if(b==1) printf("U");
		else if(b==-1) printf("D");

		if(a==0 && b==0) printf("UD");

		printf("\n");
		return;
	}

	int d = 1<<x;

	if(a==d) {
		if(b>0) {
			printf("UR");
			solve(0, b-d, x-1);
		} else if(b<0) {
			printf("DR");
			solve(0, b+d, x-1);
		} else {
			printf("URDD");
			solve(0, 0, x-2);
		}
		return;
	}
	if(a==-d) {
		if(b>0) {
			printf("UL");
			solve(0, b-d, x-1);
		} else if(b<0) {
			printf("DL");
			solve(0, b+d, x-1);
		} else {
			printf("ULDD");
			solve(0, 0, x-2);
		}
		return;
	}
	if(b==d) {
		if(a>0) {
			printf("UR");
			solve(a-d, 0, x-1);
		} else if(a<0) {
			printf("UL");
			solve(a+d, 0, x-1);
		} else {
			printf("ULRR");
			solve(0, 0, x-2);
		}
		return;
	}
	if(b==-d) {
		if(a>0) {
			printf("DR");
			solve(a-d, 0, x-1);
		} else if(a<0) {
			printf("DL");
			solve(a+d, 0, x-1);
		} else {
			printf("DLRR");
			solve(0, 0, x-2);
		}
		return;
	}
	if(a>=d) {
		if(b>=d) {
			printf("UR");
			solve(a-d, b-d, x-1);
		} else if(b>-d) {
			printf("RR");
			solve(a-d-d, b, x-1);
		} else {
			printf("DR");
			solve(a-d, b+d, x-1);
		}
	} else if(a>-d) {
		if(b>=d) {
			printf("UU");
			solve(a, b-d-d, x-1);
		} else if(b>-d) {
			printf("UD");
			solve(a, b, x-1);
		} else {
			printf("DD");
			solve(a, b+d+d, x-1);
		}
	} else {
		if(b>=d) {
			printf("LU");
			solve(a+d, b-d, x-1);
		} else if(b>-d) {
			printf("LL");
			solve(a+d+d, b, x-1);
		} else {
			printf("LD");
			solve(a+d, b+d, x-1);
		}
	}
}

