string Solve(int x, int y, int st)
{
	if (st == -1) {return "";}
	if (abs(y) < abs(x))
	{
		if (x > 0) return Solve(x - (1 << st), y, st - 1) + "R";
		else return Solve(x + (1 << st), y, st - 1) + 'L';
	}
	else
	{
		if (y > 0) return Solve(x, y - (1 << st), st - 1) + "U";
		else return Solve(x, y + (1 << st), st - 1) + "D";
	}
}

