				long long vl = abs(X[i] + (1LL << j)) + abs(Y[i]);
				long long vr = abs(X[i] - (1LL << j)) + abs(Y[i]);
				long long vd = abs(X[i]) + abs(Y[i] + (1LL << j));
				long long vu = abs(X[i]) + abs(Y[i] - (1LL << j));
				long long vm = min({ vl, vr, vd, vu });
				if (vl == vm) X[i] += 1LL << j, ans += "L";
