inline int check(LL x,LL y,char opt,LL d){
	switch(opt){
		case 'R':
			return abs(x - d) + abs(y) <= d - 1;
		case 'L':
			return abs(x + d) + abs(y) <= d - 1;
		case 'U':
			return abs(x) + abs(y - d) <= d - 1;
		case 'D':
			return abs(x) + abs(y + d) <= d - 1; 
	}
}
inline void nxt(int& x,int& y,char opt,int d){
	switch(opt){
		case 'R':
			x -= d;break;
		case 'L':
			x += d;break;
		case 'U':
			y -= d;break;
		case 'D':
			y += d;break;
	}
}
