    Scd(n);

    Rep(i,n){
        Scd2(x[i],y[i]);
        leng[i] = abs(x[i]) + abs(y[i]);
    }

    int odd = leng[0] % 2;

    Rep(i,n){
        if(leng[i] % 2 != odd){
            printf ("%d\n", -1);
            return 0;
        }
    }

    int ans = 31;
    ans += !odd;
    printf ("%d\n", ans);

    if(!odd) printf ("%d ", 1);
    ll longer[32] = {1};
    Rep(i,ans){
        printf("%lld", longer[i]);
        longer[i+1] = longer[i];
        longer[i+1] *= 2;
        if( i+1 != ans) printf (" ");
    }
    printf ("\n");

    ll pow31 = 1;
    Rep(i,31) pow31*=2;

    ll u[1000],v[1000];
    Rep(i,n){
        x[i] -= !odd;
        u[i] = x[i] + y[i];
        v[i] = x[i] - y[i];
        u[i] = (u[i] + (pow31 - 1)) / 2;
        v[i] = (v[i] + (pow31 - 1)) / 2;
        ll xx = 0;
        ll yy = 0;
        Rep(j,ans){
            if( !odd && j == 0) {printf ("R"); xx++ ;continue;}
            if( u[i] % 2 && v[i] % 2){
                printf ("R");
                xx += longer[j-!odd];
            }else if( u[i] % 2 == 0 && v[i] % 2){
                printf ("D");
                yy -= longer[j-!odd];
            }else if( u[i] % 2 && v[i] % 2 == 0 ){
                printf ("U");
                yy += longer[j-!odd];
            }else{
                printf ("L");
