typedef long long ll;

using namespace std;
ll n;
ll x[100005] , y[100005];
bool odd;
vector< ll > sums;
void solve(ll id, vector< ll > arms)
{
        string ret = "";
        ll X = x[id];
        ll Y = y[id];
        for(ll i=30;i>=1;i--) {
                ll ps = sums[i - 1];
                ll XX , YY;
                XX = X + arms[i];
                YY = Y;
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "R";
                }

                XX = X - arms[i];
                YY = Y;
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "L";
                }

                XX = X;
                YY = Y + arms[i];
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "U";
                }

                XX = X;
                YY = Y - arms[i];
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "D";
                }
        }
        if(abs(X) + abs(Y) != 1) assert(1 == 0);
        if(X == 1) {
                ret = ret + "R";
        }
        if(X == -1) {
                ret = ret + "L";
        }
        if(X == 0 && Y == 1) {
                ret = ret + "U";
        }
        if(X == 0 && Y == -1) {
                ret = ret + "D";
        }
        if(!odd) ret = ret + "R";
        reverse(ret.begin(), ret.end());
        cout << ret << "\n";

}
int main()
{
        cin >> n;
        for(ll i=1;i<=n;i++) cin >> x[i] >> y[i];
        odd = false;
        if(((x[1] + y[1])%2 + 2)%2 == 1) odd = true;
        for(ll i=2;i<=n;i++) {
                if((abs(x[i]) +abs(y[i]))%2 != (abs(x[1]) + abs(y[1]))%2) {
                        cout << "-1\n"; return 0;
                }
        }
        if(!odd) {
                for(ll i=1;i<=n;i++) x[i] -= 1;
        }
        vector< ll > arms;
        ll lst = 1;
        //if(!odd) cout << "1 ";
        if(!odd) cout << 31 + 1 << endl;
        else cout << 31 << endl;
        for(ll i=0;i<=30;i++) {

                arms.pb(lst);
                //cout << lst << " ";
                lst = lst * 2LL;
                if(i) {
                        ll X = sums.back();
                        sums.pb(X + arms.back());
                }else sums.pb(1LL);
        }
        for(ll i=30; i>=0;i--) {
                cout << (1LL << i) << " ";
        }
        if(!odd) cout << "1\n";
        cout << "\n";
        for(ll i=1;i<=n;i++) {

                solve(i, arms);
        }
        return 0;
}

