ll get(ll x, vector<ll> &D) {
    int M = D.size();
    if ((x + 10000000000LL) % 2 == 1) {
        return ((1LL << M) - 1 - x) / 2;
    } else {
        return (1LL << (M - 1)) | ((1LL << (M - 1)) - (x + 1)) / 2;
    }
}

void solve() {
    int N;
    cin >> N;
    vector<pii> P;
    set<ll> S;
    for (int i = 0; i < N; i++) {
        ll x, y;
        cin >> x >> y;
        P.push_back({x + y, x - y});
        S.insert((x + y + 10000000000LL) % 2);
        S.insert((x - y + 10000000000LL) % 2);
    }

    if (S.size() == 2) {
        cout << "-1" << endl;
        return;
    }

    int M = 39;
    vector<ll> D(M);
    for (int i = 0; i < M; i++) {
        D[i] = 1LL << i;
    }

    vector<ll> D_ = D;

    if (*S.begin() % 2 == 0) {
        D_.push_back(1);
