ll dis(ll x1, ll y1, ll x2, ll y2) {
    return abs(x1-x2)+abs(y1-y2);
}
void solve(ll x, ll y) {
    Point now={0,0};
    for (int i=1; i<=cnt; i++) {
        ll mi=INF;
        ll pos=0;
        for (int j=0; j<4; j++) {
            ll tx=now.x+dir[j][0]*d[i],ty=now.y+dir[j][1]*d[i];
            ll t=dis(tx,ty,x,y);
