            if ( sum_y < goal_y ) { to_y = 1; sum_y += dist[j]; }
            else { to_y = 0; sum_y -= dist[j]; }

            if (to_x && to_y) cout << "R";
            else if (to_x) cout << "U";
            else if (to_y) cout << "L";
            else cout << "D";
        }
        cout << endl;
    }
    return 0;
}

