ll makes(ll t) {
	ll res = 0;
	ll sum = 0;
	for (int i = 31; i >= 0; i--) {
		ll j = (ll)1 << i;
		ll dif1 = abs(sum+j - t);
		ll dif2 = abs(sum - j - t);
		if (dif1 < dif2) {
			res += j;
			sum += j;
		}
		else {
			sum -= j;
		}
	}
	return res;
}

string move(ll a, ll b) {
	string res;
