int main() {
  struct Point {int x, y;};

  int N;
  cin >> N;
  vector<Point> P(N);
  for(auto& p: P) cin >> p.x >> p.y;

  auto parity = abs(P[0].x+P[0].y)&1;
  for(const auto& p: P) if(abs(p.x+p.y)&1 != parity) {
    cout << -1 << endl;
    exit(0);
  }

  auto m = 31;
  vector<int> d;
  for(auto i=0; i<m; ++i) d.emplace_back(1<<(m-i-1));
  if(!parity) d.emplace_back(1), ++m;

  cout << m << endl;
  for(auto i: d) cout << (i==d.front() ? "" : " ") << i;
  cout << endl;
  for(const auto& p: P) {
    auto x = p.x;
    auto y = p.y;
    for(auto i: d) {
      if(abs(x)<abs(y)) {
        if(y<0) {y += i; cout << "D";}
        else    {y -= i; cout << "U";}
      } else {
        if(x<0) {x += i; cout << "L";}
        else    {x -= i; cout << "R";}
      }
    }
    cout << endl;
  }
}

