    vector<long long> d;
    for(int i = 30; i >= 0; i--) d.push_back(1LL << i);
    if(par1 % 2) d.push_back(1LL);

    //ロボットアームの情報を出力
    cout << d.size() << endl;
    for(int i = 0; i < (int)d.size(); i++){
