using namespace std;

int main() {
  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<int> x(n), y(n);
  for (int i = 0; i < n; i++) {
    cin >> x[i] >> y[i];
  }

  bool odd = true, even = true;
  for (int i = 0; i < n; i++) {
    odd &= abs(x[i] + y[i]) % 2 == 1;
    even &= abs(x[i] + y[i]) % 2 == 0;
  }
  if (!odd && !even) {
    cout << -1 << '\n';
    return 0;
  }

  int k = 30;
  cout << k + even << '\n';
  if (even) cout << 1 << ' ';
  for (int i = k - 1; i >= 0; i--) {
    cout << (1 << i) << ' ';
  }
  cout << '\n';

  auto inside = [](int i, int j, int round) {
    return abs(i) + abs(j) <= ((1 << round) - 1);  
  };

  for (int i = 0; i < n; i++) {
    string ans = "";
    if (even) {
      ans += "D";
      y[i]++;
    }
    for (int j = k - 1; j >= 0; j--) {
      int step = (1 << j); 
      if (inside(x[i], y[i] - step, j)) {
        ans += "U";
        y[i] -= step;
      } else if (inside(x[i], y[i] + step, j)) {
        ans += "D";
        y[i] += step;
      } else if (inside(x[i] - step, y[i], j)) {
        ans += "R";
        x[i] -= step;
      } else if (inside(x[i] + step, y[i], j)) {
        ans += "L";
        x[i] += step;
      } else {
        assert(0);
      }
    }
    cout << ans << '\n';
  }

  return 0;
}

