                posy = -1;
                nowy -= D;
            }else{
                posy = 1;
                nowy += D;
            }

            if (posx == -1 and posy == -1) next = 'L';
            if (posx == -1 and posy == 1) next = 'U';
            if (posx == 1 and posy == 1) next = 'R';
            if (posx == 1 and posy == -1) next = 'D';
