int solve_small() {
    // マンハッタン距離で最大のものを求める
    ll x_max = 0, y_max = 0;
    ll cnt_odd = 0, cnt_even = 0;
    REP(i, N) {
        x_max = max(x_max, abs(X[i]));
        y_max = max(y_max, abs(Y[i]));
        if((abs(X[i]) + abs(Y[i])) % 2 == 0) { cnt_even++; }
        else { cnt_odd++; }
    }

    // 最短マンハッタン距離の偶奇が違うなら不可能
    if(cnt_odd > 0 && cnt_even > 0) {
        printf("-1\n");
        return 0;
    }
    ll m = x_max + y_max;
    //assert(m <= 40);
    printf("%lld\n", m);
    REP(i, m) {
        printf("1");
        if(i != m-1) { printf(" "); }
        else { printf("\n"); }
    }
    REP(i, N) {
        // まず最短で目的地に向かう
        string dir_s = "";
        char dir = 'L';
        if(X[i] > 0) { dir = 'R'; }
        REP(j, abs(X[i])) { dir_s += dir; }
        if(Y[i] > 0) { dir = 'U'; }
        else { dir = 'D'; }
        REP(j, abs(Y[i])) { dir_s += dir; }
        // 目的地に着いたら適当に暇をつぶす
        ll remain = m - abs(X[i]) - abs(Y[i]);
        for(int j = 0; j < remain; j += 2) { dir_s += "LR"; }
        printf("%s\n", dir_s.c_str());
        assert(dir_s.length() == m);
    }
    return 0;
}

