void solve(vector<int> v,int tx,int ty){
	int x=0,y=0;
	for(int len:v){
		if(abs(tx-x)>abs(ty-y)){
			if(tx>x) putchar('R'),x+=len;
			else putchar('L'),x-=len;
		}
		else{
			if(ty>y) putchar('U'),y+=len;
			else putchar('D'),y-=len;
		}
	}
	assert(x==tx&&y==ty);
	puts("");
}
