		scanf("%d%d",&x[i],&y[i]);
		int par2 = (x[i]+y[i])&1;
		if(i == 0) {
			par = par2;
		} else if(par != par2) {
			printf("-1\n");
			return 0;
		}
	}
	if(par == 1) {
		printf("30\n");
		for(int i = 0;i < 30;++i) printf("%d ", 1<<i);
		printf("\n");
	} else {
		printf("31\n1 ");
		for(int i = 0;i < 30;++i) printf("%d ", 1<<i);
		printf("\n");
	}
	for(int i = 0;i < n;++i) {
		if(par == 0) {
			putchar('L');
			--x[i];
		}
		for(int j = 0;j < 29;++j) {
			assert((x[i]^y[i])&1);
			if((x[i]&1)==1) {
				if((y[i]^x[i])&2) {
					putchar('R');
					--x[i];
				} else {
					putchar('L');
					++x[i];
				}
			} else {
				if((y[i]^x[i])&2) {
					putchar('U');
					--y[i];
