using pll = pair<long long, long long>;

int main() {
    int N; cin >> N;
    vector<pll> pos(N);
    for (int i = 0; i < N; ++i) cin >> pos[i].first >> pos[i].second;

    int par = (abs(pos[0].first) + abs(pos[0].second)) % 2;
    for (int i = 0; i < N; ++i) {
        int par2 = (abs(pos[i].first) + abs(pos[i].second)) % 2;
        pos[i] = pll(pos[i].first + pos[i].second, pos[i].first - pos[i].second);
        if (par2 != par) {
            cout << -1 << endl;
            return 0;
        }
    }

    vector<long long> d;
    for (int i = 30; i >= 0; --i) d.push_back(1LL<<i);
    if (par % 2 == 0) d.push_back(1);
    cout << d.size() << endl;
    for (int j = 0; j < d.size(); ++j) cout << d[j] << " ";
    cout << endl;

    for (int i = 0; i < N; ++i) {
        int xdir, ydir;
        long long xsum = 0, ysum = 0;
        for (int j = 0; j < (int)d.size(); ++j) {
            if (xsum <= pos[i].first) xdir = 1, xsum += d[j];
            else xdir = -1, xsum -= d[j];
            if (ysum <= pos[i].second) ydir = 1, ysum += d[j];
            else ydir = -1, ysum -= d[j];

            if (xdir == 1 && ydir == 1) cout << "R";
            else if (xdir == 1 && ydir == -1) cout << "U";
            else if (xdir == -1 && ydir == -1) cout << "L";
            else cout << "D";
        }
        cout << endl;
    }
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using P = pair<int, int>;
const ll MOD = 1000000007;

int main(){
    int N;
    cin >> N;

    vector<ll> X(N), Y(N);
    vector<ll> l1_dist(N);
    for(int i=0;i<N;i++){
        cin >> X[i] >> Y[i];
        l1_dist[i] = abs(X[i]) + abs(Y[i]);
    }

    bool even = true, odd = true;
    for(int i=0;i<N;i++){
        if(l1_dist[i] % 2 == 0){
            odd = false;
        }else{
            even = false;
        }
    }

    if(odd || even){
        ll l1_max = 0;
        for(int i=0;i<N;i++){
            l1_max = max(l1_max, l1_dist[i]);
        }

        if(l1_max <= 20){
            int m = l1_max == 0 ? 2 : l1_max;
            cout << m << endl;
            for(int i=0;i<m-1;i++){
                cout << 1 << " ";
            }
            cout << 1 << endl;
            for(int i=0;i<N;i++){
                for(int j=0;j<abs(X[i]);j++){
                    cout << (X[i] > 0 ? 'R' : 'L');
                }
                for(int j=0;j<abs(Y[i]);j++){
                    cout << (Y[i] > 0 ? 'U' : 'D');
                }
                int no_move = (m - l1_dist[i]) / 2;
                for(int j=0;j<no_move;j++){
                    cout << "LR";
                }
                cout << endl;
            }
        }else{
            set<ll> vs;
            for(int i=0;i<N;i++){
                if(abs(X[i]) > 0){
                    vs.insert(abs(X[i]));
                }
                if(abs(Y[i]) > 0){
                    vs.insert(abs(X[i]) + abs(Y[i]));
                }
                if(l1_max > l1_dist[i]){
                    ll d = (l1_max - l1_dist[i]) / 2;
                    vs.insert(abs(X[i]) + abs(Y[i]) + d);
                    vs.insert(abs(X[i]) + abs(Y[i]) + d + d);
                }
            }

            vector<int> arms;
            ll prev = 0;
            for(ll v : vs){
                arms.push_back(v - prev);
                prev = v;
            }

            assert(arms.size() >= 2 && arms.size() <= 40);
            cout << arms.size() << endl;
            for(int i=0;i+1<arms.size();i++){
                cout << arms[i] << " ";
            }
            cout << arms.back() << endl;

            for(int i=0;i<N;i++){
                ll used = 0;
                int p = 0;
                while(used < abs(X[i])){
                    used += arms[p++];
                    cout << (X[i] > 0 ? 'R' : 'L');
                }
                while(used < abs(X[i]) + abs(Y[i])){
                    used += arms[p++];
                    cout << (Y[i] > 0 ? 'U' : 'D');
                }
                ll d = (l1_max - l1_dist[i]) / 2;
                while(used < abs(X[i]) + abs(Y[i]) + d){
                    used += arms[p++];
                    cout << 'L';
                }
                while(used < abs(X[i]) + abs(Y[i]) + d + d){
                    used += arms[p++];
                    cout << 'R';
                }
                cout << endl;
            }
        }
    }else{
        cout << -1 << endl;
    }
    return 0;
}

