			else if (y<x && y<-x){//え
				ans[i] += 'D';
				y += b;
			}
			else{
				cerr << "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!";
			}
		}
		if (mode == 0) ans[i] += 'R';
	}

	vll arms;
	DEPS(bi, 0, 30){
		ll b = 1LL << bi;
		arms.push_back(b);
	}
	if (mode == 0) arms.push_back(1);

	//出力
