inline void fastin(int &input_number) 
{
  input_number = 0;
  int ch = GETCHAR();
  //if(ch == EOF) exit(0);
  int sign = 1;
  while(ch < '0' || ch > '9'){
    if(ch == '-') sign=-1;
    ch = GETCHAR();
  }
  while(ch >= '0' && ch <= '9'){
    input_number = (input_number << 3)+(input_number << 1) + ch-'0';
    ch = GETCHAR();
  }
  input_number *= sign;
}

