int main() {
	int n; read(n);
	int cnt[2] = {0, 0};
	for (int i = 1; i <= n; i++) {
		read(x[i]), read(y[i]);
		cnt[(x[i] + y[i]) % 2 == 0]++;
	}
	if (cnt[0] != 0 && cnt[1] != 0) {
		puts("-1");
		return 0;
	}
	vector <ll> ans, sum;
	ans.push_back(1);
	if (cnt[1]) ans.push_back(1);
	for (int i = 2; i <= 38; i++)
		ans.push_back(1ll << (i - 1));
	sum.push_back(0);
	for (unsigned i = 1; i < ans.size(); i++)
		sum.push_back(sum.back() + ans[i - 1]);
	cout << ans.size() << endl;
