				nowx += ans[j];
			} else if (check(nowx - ans[j], nowy, sum[j])) {
				res[j] = 'R';
				nowx -= ans[j];
			} else if (check(nowx, nowy + ans[j], sum[j])) {
				res[j] = 'D';
				nowy += ans[j];
			} else if (check(nowx, nowy - ans[j], sum[j])) {
				res[j] = 'U';
				nowy -= ans[j];
			}
		}
		cout << res << endl;
	}
	return 0;
}

