[[noreturn]] void impossible() {
    PRINTLN(-1);
    exit(0);
}

void solve() {
    i64 N = RD();
    auto P = RD_VEC<pair<i64,i64>>(N);
    for(const auto& p : P) {
        i64 x,y; tie(x,y) = p;
        ASSERT(-10 <= x && x <= 10);
        ASSERT(-10 <= y && y <= 10);
    }

    bool even0 = (P[0].first+P[0].second)%2 == 0;
    {
        FOR(i, 1, N) {
            i64 x,y; tie(x,y) = P[i];
            bool even = (x+y)%2 == 0;
            if(even0 != even) impossible();
        }
    }

    i64 M = even0 ? 20 : 19;
    vector<i64> D(M, 1);
    PRINTLN(M);
    PRINTLN(D);

    for(const auto& p : P) {
        i64 x,y; tie(x,y) = p;
        string ans;
        ans += string(ABS(x), x > 0 ? 'R' : 'L');
        ans += string(ABS(y), y > 0 ? 'U' : 'D');
        i64 remain = M - ABS(x) - ABS(y);
        ASSERT(remain >= 0 && remain%2 == 0);
        REP(_, remain/2) {
            ans += "LR";
        }
        PRINTLN(ans);
    }
}

signed main() {


    solve();

    return 0;
}

