{
        string ret = "";
        ll X = x[id];
        ll Y = y[id];
        for(ll i=30;i>=1;i--) {
                ll ps = sums[i - 1];
                ll XX , YY;
                XX = X + arms[i];
                YY = Y;
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "R";
                }

                XX = X - arms[i];
                YY = Y;
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "L";
                }

                XX = X;
                YY = Y + arms[i];
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "U";
                }

                XX = X;
                YY = Y - arms[i];
                if(abs(XX) + abs(YY) <= ps) {
                        X = XX;
                        Y = YY;
                        ret = ret + "D";
                }
        }
        if(abs(X) + abs(Y) != 1) assert(1 == 0);
        if(X == 1) {
                ret = ret + "R";
        }
        if(X == -1) {
                ret = ret + "L";
        }
        if(X == 0 && Y == 1) {
                ret = ret + "U";
        }
        if(X == 0 && Y == -1) {
                ret = ret + "D";
        }
        if(!odd) ret = ret + "R";
        reverse(ret.begin(), ret.end());
