bool flag;

int main()
{
	scanf("%d", &N);
	for (int i = 1;i <= N;++i)
	{
		scanf("%lld%lld", X + i, Y + i);
		if ((Abs(X[1] + Y[1]) & 1) ^ (Abs(X[i] + Y[i]) & 1))
		{
			printf("-1");
			return 0;
		}
	}
	if (((Abs(X[1] + Y[1])) & 1) == 0)
	{
		flag = true;
		for (int i = 1;i <= N;++i)
			--X[i];
	}
	for (int i = 1;i <= N;++i)
	{
		LL x = X[i] + Y[i], y = X[i] - Y[i];
		X[i] = x, Y[i] = y;
	}
	if (flag)
	{
		printf("%d\n", 1 + 31);
		printf("%d ", 1);	
	}
	else
		printf("%d\n", 31);
	for (LL i = 0LL;i <= 30LL;++i)
		printf("%lld ", 1LL << i);
	printf("\n");
	for (int i = 1, gx, gy;i <= N;++i)
	{
