			if (gy)
				c2 = -c2;
			Sumx += (1LL << j) * c1, Sumy += (1LL << j) * c2;
			x = (c1 + c2) / 2LL, y = (c1 - c2) / 2LL;
			if (x == -1LL)
				putchar('L');
			if (x == +1LL)
				putchar('R');
			if (y == -1LL)
				putchar('D');
			if (y == +1LL)
				putchar('U');
		}
