li keta = 0;

li m;

inline vector<bool> solve_(li xx) {
    rep(i, keta)xx += bit(i);
    vector<bool> res(keta, false);
    for (li now = keta - 1; now >= 0; now--) {
        if (bit(now) * 2 <= xx) {
            xx -= bit(now) * 2;
            res[now] = true;
        }
    }
    //p2("", xx);
    //dumpi(res);
    return res;
}

inline string solve(PI xx) {
    string res = "";
    if ((xx.F + xx.S) % 2 == 0) {
        res = "L";
        xx.F++;
    }
    auto v_u = solve_(xx.F + xx.S);
    auto v_v = solve_(xx.F - xx.S);

    rep(i, keta) {
        if (v_u[i]) {
            // RU
            res = res + (v_v[i] ? "R" : "U");
        } else {
            // LD
            res = res + (v_v[i] ? "D" : "L");
        }
    }
    return res;
}

