int get(int x, int y) {
    return (((x + y) % 2) + 2) % 2;
}

void solve() {
    int n;
    cin >> n;
    vector<long long> x(n), y(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        if (i > 0 && get(x[i - 1], y[i - 1]) != get(x[i], y[i])) {
            cout << -1; return;
        }
