        string s;
        if (!parity) s.push_back('D'), y[i]++;
        for (int j = 29; j >= 0; j--) {
            for (int k = 0; k < 4; k++) {
                long long nx = x[i] + 1LL * dx[k] * (1LL << j), ny = y[i] + 1LL * dy[k] * (1LL << j);
