typedef long long ll;

const int MAX_N = 1000;
int N;
int X[MAX_N];
int Y[MAX_N];

void solve() {
    int mod2 = (abs(X[0]) + abs(Y[0])) % 2;
    REP(i,0,N) {
        if (mod2 != (abs(X[i]) + abs(Y[i])) % 2) {
            cout << "-1" << "\n";
            return;
        }
    }

    const int M = 31;
    int m = mod2 == 1 ? M : M + 1;
    ll d[32];
    cout << m << "\n";
    REP(i,0,M) {
        d[M-i-1] = pow(2,i);
        cout << d[M-i-1];
        if (i != M-1) cout << " ";
    }
    if (mod2 == 0) {
        d[31] = 1;
        cout << " 1\n";
    } else {
        cout << "\n";
    }

    REP(i,0,N) {
        ll x = X[i], y = Y[i];
        REP(j,0,m) {
            ll L, R, U, D;
            L = abs(x - d[j]) + abs(y);
            R = abs(x + d[j]) + abs(y);
            U = abs(x) + abs(y + d[j]);
            D = abs(x) + abs(y - d[j]);
            if (min(min(min(L,R),U),D) == L) {
                x = x - d[j];
                cout << "L";
            } else if (min(min(min(L,R),U),D) == R) {
                x = x + d[j];
                cout << "R";
            } else if (min(min(min(L,R),U),D) == U) {
                y = y + d[j];
                cout << "U";
            } else {
                y = y - d[j];
                cout << "D";
            }
        }
        cout << x << y;
        cout << "\n";
    }

    return;
}

