{
	return Abs(x)+Abs(y)<d[t+1]; 
}
void print(LL x,LL y,int step)
{
	if(step==-1)
	{
		return;
	}
	if(judge(x+d[step],y,step-1))
	{
		print(x+d[step],y,step-1);
		printf("L");
		return;
	}
	if(judge(x-d[step],y,step-1))
	{
		print(x-d[step],y,step-1);
		printf("R");
		return;
	}
	if(judge(x,y+d[step],step-1))
	{
		print(x,y+d[step],step-1);
		printf("D");
		return;
	}
	if(judge(x,y-d[step],step-1))
	{
		print(x,y-d[step],step-1);
		printf("U");
		return;
	}
	assert(0);
}
