			else if (y - x >= b - a + d * 2 && y + x >= b + a)
				w = 1, a -= d, b += d;
			ss << c[w];
		}
		ss << '\n';
	}
	cout << 39 + o << '\n';
	for (int i = 0; i < 39 + o; i++)
		cout << (1l << 39 - i) << ' ';
	cout << '\n' << ss.str() << flush;
	return 0;
}

