vi v;
vpl todo;

bool ok(pl x, int k) {
    return abs(x.f)+abs(x.s) <= ((1LL<<k)-1);
}

void solve(pl x) {
    if (a) x.f --;
    string ans; F0R(i,31) ans += 'a';
    if (a) ans += 'R';
    F0Rd(i,31) {
        if (ok({x.f-(1<<i),x.s},i)) {
            ans[i] = 'R';
            x.f -= 1<<i;
        } else if (ok({x.f+(1<<i),x.s},i)) {
            ans[i] = 'L';
            x.f += 1<<i;
        } else if (ok({x.f,x.s-(1<<i)},i)) {
            ans[i] = 'U';
            x.s -= 1<<i;
        } else if (ok({x.f,x.s+(1<<i)},i)) {
            ans[i] = 'D';
            x.s += 1<<i;
        }
    } 
    assert(x == mp(0LL,0LL));
    cout << ans << "\n";
}

