void solve(int num) {
	ll X=0,Y=0;
	if(m==33) X=1;
	ch[33]='R';
	for(int i=1;i<=32;i++) {
		if(gd(num,X+d[i],Y)<=d[i]-1) {
			X=X+d[i];
			ch[i]='R';
			continue;
		}
		if(gd(num,X-d[i],Y)<=d[i]-1) {
			X=X-d[i];
			ch[i]='L';
			continue;
		}
		if(gd(num,X,Y+d[i])<=d[i]-1) {
			Y=Y+d[i];
			ch[i]='U';
			continue;
		}
		if(gd(num,X,Y-d[i])<=d[i]-1) {
			Y=Y-d[i];
			ch[i]='D';
			continue;
		}
	}
	for(int i=1;i<=m;i++) {
		cout<<ch[i];
	}
	cout<<endl;
}

