vector <int> f( i64 m , int p )
{
    if(p==-1)
    {
        vector<int> res ;
        return res ;
    }
    vector <int> res ;
    if( (1LL<<p) > m )
    {
        res = f( (1LL<<p)-m , p-1 ) ;
        for(int i=0 ; i<res.size() ; i++) res[i] *= -1 ;
    }
    else{
        res = f( m-(1LL<<p) , p-1 ) ;
    }
    res.pb(1) ;
    return res ;
}

