    for(i=0;i<n;i++){
      if(ABS(y[i])>ABS(x[i])){
	dir[i]=y[i]>=0?2:3;
      } else {
	dir[i]=x[i]>=0?0:1;
      }
    }
    int min=ABS(x[0])+ABS(y[0]);
    int max=min;
    for(i=1;i<n;i++){
      min=MIN(min,ABS(x[i])+ABS(y[i]));
      max=MAX(max,ABS(x[i])+ABS(y[i]));
    }
    if(max==0) break;
    if((max-min)%2!=0 || (m==40 && max>0)){
      printf("-1\n");
      return;
