    if(max==min){
      min=dir[0]>=2?ABS(y[0]):ABS(x[0]);
      max=min;
      for(i=1;i<n;i++){
	min=MIN(min,dir[i]>=2?ABS(y[i]):ABS(x[i]));
	max=MAX(max,dir[i]>=2?ABS(y[i]):ABS(x[i]));
      }
    }
    int dd=(max+min)/2;
    for(i=0;i<n;i++){
      if(dir[i]==0){
	x[i]-=dd;
      } else if(dir[i]==1){
	x[i]+=dd;
      } else if(dir[i]==2){
	y[i]-=dd;
      } else {
	y[i]+=dd;
      }
      ans[41*i+m]=v[dir[i]];
    }
    d[m++]=dd;
  }
  printf("%d\n",m);
  for(i=0;i<m;i++) printf("%d ",d[i]);
  printf("\n");
  for(i=0;i<n;i++) printf("%s\n",ans+i*41);
}

