#include<stdio.h>
#include<stdlib.h>

typedef long long int int64;

#define ABS(a) ((a)>0?(a):-(a))
#define MIN(a,b) ((a)<(b)?(a):(b))
#define MAX(a,b) ((a)>(b)?(a):(b))

void run(void){
  int n;
  scanf("%d",&n);
  int *x=(int *)malloc(sizeof(int)*n);
  int *y=(int *)malloc(sizeof(int)*n);
  char *ans=(char *)calloc(n*41,sizeof(char));
  int *dir=(int *)calloc(n,sizeof(int));
  char v[4]={'R','L','U','D'};
  int i;
  for(i=0;i<n;i++) scanf("%d%d",x+i,y+i);
  int d[40];
  int m=0;
  while(m<=40){
    for(i=0;i<n;i++){
      if(ABS(y[i])>ABS(x[i])){
	dir[i]=y[i]>=0?2:3;
      } else {
	dir[i]=x[i]>=0?0:1;
      }
    }
    int min=ABS(x[0])+ABS(y[0]);
    int max=min;
    for(i=1;i<n;i++){
      min=MIN(min,ABS(x[i])+ABS(y[i]));
      max=MAX(max,ABS(x[i])+ABS(y[i]));
    }
    if(max==0) break;
    if((max-min)%2!=0 || (m==40 && max>0)){
      printf("-1\n");
      return;
    }
    if(max==min){
      min=dir[0]>=2?ABS(y[0])-ABS(x[0]):ABS(x[0])-ABS(y[0]);
      max=min;
      for(i=1;i<n;i++){
	min=MIN(min,dir[i]>=2?ABS(y[i])-ABS(x[i]):ABS(x[i])-ABS(y[i]));
	max=MAX(max,dir[i]>=2?ABS(y[i])-ABS(x[i]):ABS(x[i])-ABS(y[i]));
      }
    }
    int dd=(max+min)/2;
    for(i=0;i<n;i++){
      if(dir[i]==0){
	x[i]-=dd;
      } else if(dir[i]==1){
	x[i]+=dd;
      } else if(dir[i]==2){
	y[i]-=dd;
      } else {
	y[i]+=dd;
      }
      ans[41*i+m]=v[dir[i]];
    }
    d[m++]=dd;
  }
  printf("%d\n",m);
  for(i=0;i<m;i++) printf("%d ",d[i]);
  printf("\n");
  for(i=0;i<n;i++) printf("%s\n",ans+i*41);
}

int main(void){
  run();
  return 0;
}

