    void solve(){ 
        int n = ni();
        int[][] res = new int[n][2];
        int p = 0;
        for(int i = 0; i < n; i++){
            res[i][0] = ni();
            res[i][1] = ni();
        }
        for(int i = 0; i < n; i++){
            int tmp = Math.abs(res[i][0]+res[i][1]);
            if(i>0){
                if((tmp%2)!=(p%2)){
                    out.println(-1);
                    return;
                }
            }
            p = tmp;
            if(Math.abs(res[i][0])>10||Math.abs(res[i][1])>10){
                out.println(-1);
                return;
            }
        }
        int m = 40;
        if(p%2==1) m = 39;
        out.println(m);
        for(int i = 0; i < m; i++){
            out.print(1+" ");
        }
        out.println();
        for(int i = 0; i < n; i++){
