			int n = in.nextInt();
			long[] x = new long[n], y = new long[n], z = new long[n];
			for (int i = 0; i < n; i++) {
				x[i] = in.nextLong();
				y[i] = in.nextLong();
				z[i] = x[i] + y[i];
				if ((z[i] - z[0]) % 2 != 0) {
					out.println(-1);
