							sb.append("U");
							tu -= d;
							tv += d;
						}
					} else {
						if (tv >= 0) {
							sb.append("D");
							tu += d;
							tv -= d;
						} else {
							sb.append("L");
							tu += d;
							tv += d;
						}
					}
				}
				out.println(sb.toString());
			}
		}
