import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {
	public static int MAXA = 100000;
	public static void main(String[] args) {
		IO io = new IO();
		int n = io.nextInt();
		int[] x = new int[n];
		int[] y = new int[n];
		io.nextIntArrays(x,y);
		int parity0 = (x[0] + y[0]) & 1;
		for(int i=0;i<n;i++) {
			if (parity0 != (x[i] + y[i] & 1)) {
				System.out.println(-1);
				return;
			}
		}
		int[] a = new int[n];
		int[] b = new int[n];
		for(int i=0;i<n;i++) {
			a[i] = x[i] + y[i];
			b[i] = -x[i] + y[i];
		}
		/*
		 *   A B
		 * L - +
		 * R + -
		 * D - -
		 * U + +
		 */
		ArrayList<Long> d = new ArrayList<>();
		for(int i=0;i<32;i++) {
			d.add(1L << (long) i);
		}
		if (parity0 == 0) {
			d.add(1L);
		}
		d.sort(Collections.reverseOrder());
		int m = d.size();
		io.println(m);
		for(int i=0;i<m;i++) {
			if (m > 0) {
				io.print(' ');
			}
			io.print(d.get(i));
		}
		io.println();
		for(int i=0;i<n;i++) {
			long ca = 0;
			long cb = 0;
			for(int j=0;j<m;j++) {
				if (ca < a[i]) {
					if (cb < b[i]) {
						io.print('U');
						ca += d.get(j);
						cb += d.get(j);
					}else {
						io.print('R');
						ca += d.get(j);
						cb -= d.get(j);
					}
				}else {
					if (cb < b[i]) {
						io.print('L');
						ca -= d.get(j);
						cb += d.get(j);
					}else {
						io.print('D');
						ca -= d.get(j);
						cb -= d.get(j);
					}
				}
			}
			io.println();
		}
		io.flush();
	}
}

