	static void solve(){ 
		int n = ni();
		long[] u = new long[n];
		long[] v = new long[n];
		long x0=nl(), y0=nl();
		u[0] = x0+y0; v[0] = x0-y0;
		for(int i=1;i<n;++i){
			long x=nl();
			long y=nl();
			if((Math.abs(x0+y0))%2 != (Math.abs(x+y)%2)){
