			}
			u[i] = x+y;
			v[i] = x-y;
		}
		List<Long> d = new ArrayList<>();
		String pre = "";
		if(Math.abs(x0+y0)%2==0){
			for(int i=0;i<n;++i){
				u[i]-=1;v[i]-=1;
			}
			pre="R";
		}
		for(int i=31;i>=0;--i)d.add((1l<<i));
