					ans+="R";
					uu+=dd; vv+=dd;
				}else if(u[i]>uu && v[i]<vv){
					ans+="U";
					uu+=dd; vv-=dd;
				}else if(u[i]<uu && v[i]>vv){
					ans+="D";
					uu-=dd; vv+=dd;
				}else{
					ans+="L";
					uu-=dd; vv-=dd;
				}
			}
			out.println(ans);

			long xx=0, yy=0;
			for(int k=0;k<d.size();++k){
				switch(ans.charAt(k)){
					case 'R':
						xx+=d.get(k);break;
					case 'L':
						xx-=d.get(k);break;
					case 'U':
						yy+=d.get(k);break;
					case 'D':
						yy-=d.get(k);break;
				}
			}
			assert xx==(u[i]+v[i])/2;
			assert yy==(u[i]-v[i])/2;

		}

	} 




