    static class TaskD {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int[][] p = in.nextIntArray2D(n, 2);
            int parity = 0;
            for (int[] pp : p) {
                parity |= 1 << ((pp[0] + pp[1]) & 1);
            }
            if (parity == 3) {
                out.println(-1);
                return;
            }

            List<Integer> d = new ArrayList<>();
            StringBuilder[] ans = new StringBuilder[n];
            for (int i = 0; i < n; i++) ans[i] = new StringBuilder();
            for (int i = 30; i >= 0; i--) {
                while (true) {
                    List<Integer> cand = new ArrayList<>();
                    for (int j = 0; j < n; j++) {
                        if (((Math.abs(p[j][0]) | Math.abs(p[j][1])) & (1 << i)) != 0) {
                            cand.add(j);
                        }
                    }
//                dump(i, cand, p);
                    if (cand.isEmpty()) break;
                    if (cand.size() == n) {
                        d.add(1 << i);
                        for (int j = 0; j < n; j++) {
                            for (int k = 0; k < 2; k++) {
                                if ((Math.abs(p[j][k]) & 1 << i) != 0) {
                                    if (k == 0) {
                                        ans[j].append(p[j][k] > 0 ? 'R' : 'L');
                                    } else {
                                        ans[j].append(p[j][k] > 0 ? 'U' : 'D');
                                    }

                                    p[j][k] += p[j][k] > 0 ? -(1 << i) : (1 << i);
                                    break;
                                }
                            }
                        }
                    } else {
                        if (i == 0) {
                            throw new RuntimeException();
                        }
                        d.add(1 << (i - 1));
                        d.add(1 << (i - 1));
                        for (int j = 0; j < n; j++) {
                            if (!cand.contains(j)) {
                                ans[j].append('R');
                                ans[j].append('L');
                                continue;
                            }
                            for (int k = 0; k < 2; k++) {
                                if ((Math.abs(p[j][k]) & 1 << i) != 0) {
                                    if (k == 0) {
                                        ans[j].append(p[j][k] > 0 ? 'R' : 'L');
                                        ans[j].append(p[j][k] > 0 ? 'R' : 'L');
                                    } else {
                                        ans[j].append(p[j][k] > 0 ? 'U' : 'D');
                                        ans[j].append(p[j][k] > 0 ? 'U' : 'D');
                                    }

                                    p[j][k] += p[j][k] > 0 ? -(1 << i) : (1 << i);
                                    break;
                                }
                            }
                        }
                    }
                }
            }

            out.println(d.size());
            for (int i = 0; i < d.size(); i++) {
                out.print(d.get(i) + (i == d.size() - 1 ? "\n" : " "));
            }
            for (StringBuilder sb : ans) {
                out.println(sb.toString());
            }
        }

    }

    static class MyInput {
