    void solve(){ 
        int n = ni();
        int[][] res = new int[n][2];
        int p = 0;
        for(int i = 0; i < n; i++){
            res[i][0] = ni();
            res[i][1] = ni();
            int tmp = res[i][0]+res[i][1];
            if(i>0){
                if((tmp+p)%2!=0){
                    out.println(-1);
                    return;
                }
            }
            p = tmp;
        }
        int m = 40;
        if(p%2==1) m = 39;
        out.println(m);
        for(int i = 0; i < m; i++){
            out.print(1+" ");
        }
        out.println();
        for(int i = 0; i < n; i++){
            int x = res[i][0];
            int y = res[i][1];
            int c = 0;
            if(x<0){
                for(int j = 0; j < -x; j++){
                    out.print("L");
                    c++;
                }
            }
            if(x>0){
                for(int j = 0; j < x; j++){
                    out.print("R");
                    c++;
                }
            }
            if(y<0){
                for(int j = 0; j < -y; j++){
                    out.print("D");
                    c++;
                }
