public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[] x = new int[n];
		int[] y = new int[n];
		for (int i = 0; i < n; i++) {
			x[i] = sc.nextInt();
			y[i] = sc.nextInt();

			if (x[i] < -10 || x[i] > 10 || y[i] < -10 || y[i] > 10) {
				throw new RuntimeException();
			}
		}

		int mod = Math.abs(x[0] + y[0]) % 2;
		for (int i = 0; i < n; i++) {
			if (Math.abs(x[i] + y[i]) % 2 != mod) {
				pr.println(-1);
				return;
			}
		}

		int m = 0;
		if (mod % 2 == 0) {
			m = 20;
		} else {
			m = 19;
		}

		pr.println(m);
		for (int i = 0; i < m; i++) {
			if (i > 0) {
				pr.print(' ');
			}
			pr.print('1');
		}
		pr.println();

		for (int i = 0; i < n; i++) {
			StringBuilder w = new StringBuilder();

			if (x[i] > 0) {
				for (int j = 0; j < x[i]; j++) {
					w.append('R');
				}
			} else if (x[i] < 0) {
				for (int j = 0; j < Math.abs(x[i]); j++) {
					w.append('L');
				}
			}
			if (y[i] > 0) {
				for (int j = 0; j < y[i]; j++) {
					w.append('U');
				}
			} else if (y[i] < 0) {
				for (int j = 0; j < Math.abs(y[i]); j++) {
					w.append('D');
				}
			}

			while(m - w.length() > 0) {
				w.append("LR");
			}

			pr.println(w);
		}
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(INPUT == null ? System.in : new ByteArrayInputStream(INPUT.getBytes()));
		pr = new Printer(System.out);

		solve();

//		pr.close();
		pr.flush();
//		sc.close();
	}

	static String INPUT = null;

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	private static class Printer extends PrintWriter {
		Printer(OutputStream out) {
			super(out);
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.NoSuchElementException;

public class Main {
	public static void main(String[] args) throws Exception {
		new Main().run();
	}

	public void run() throws Exception {
		Scanner sc = new Scanner();
		int n = sc.nextInt();
		ArrayList<Integer> len = new ArrayList<>();
		StringBuilder[] sb = new StringBuilder[n];
		for (int i = 0; i < n; ++i)
			sb[i] = new StringBuilder();
		int[] X = new int[n];
		int[] Y = new int[n];
		for (int i = 0; i < n; ++i) {
			X[i] = sc.nextInt();
			Y[i] = sc.nextInt();
			if (X[i] % 2 == 0) {
				sb[i].append("R");
				--X[i];
			}
			if (Y[i] % 2 == 0) {
				sb[i].append("U");
				--Y[i];
			}
		}
		for (int i = 0; i < n; ++i) {
			if (sb[i].length() != sb[0].length()) {
				System.out.println(-1);
				return;
			}
		}
		for (int i = 0; i < sb[0].length(); ++i)
			len.add(1);
		for (int i = 0; i < 19; ++i) {
			len.add(1 << i);
			for (int j = 0; j < n; ++j)
				X[j] += 1 << i;
		}
		for (int i = 0; i < 19; ++i) {
			len.add(1 << i);
			for (int j = 0; j < n; ++j)
				Y[j] += 1 << i;
		}
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < 19; ++j) {
				if ((X[i] & (1L << (j + 1))) > 0) {
					sb[i].append("R");
				} else {
					sb[i].append("L");
				}
			}
		}
		for (int i = 0; i < n; ++i) {
			Y[i] /= 2;
			for (int j = 0; j < 19; ++j) {
				if ((Y[i] & (1L << (j + 1))) > 0) {
					sb[i].append("U");
				} else {
					sb[i].append("D");
				}
			}
		}
		System.out.println(len.size());
		for (int i = 0; i < len.size(); ++i) {
			System.out.print(len.get(i) + (i == len.size() - 1 ? "\n" : " "));
		}
		for (int i = 0; i < n; ++i) {
			System.out.println(sb[i].toString());
		}
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}

	class Scanner {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;

		private boolean hasNextByte() {
			if (ptr < buflen) {
				return true;
			} else {
				ptr = 0;
				try {
					buflen = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
				if (buflen <= 0) {
					return false;
				}
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[ptr++];
			else
				return -1;
		}

		private boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private void skipUnprintable() {
			while (hasNextByte() && !isPrintableChar(buffer[ptr]))
				ptr++;
		}

		public boolean hasNext() {
			skipUnprintable();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			return (int) nextLong();
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (b < '0' || '9' < b) {
				throw new NumberFormatException();
			}
			while (true) {
				if ('0' <= b && b <= '9') {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) {
					return minus ? -n : n;
				} else {
					throw new NumberFormatException();
				}
				b = readByte();
			}
		}
	}
}

import java.io.*;
import java.util.*;
