		int N = sc.nextInt();
		int[] X = new int[N];
		int[] Y = new int[N];
		boolean odd = false;
		boolean even = false;
		for (int i = 0; i < N; i++) {
			X[i] = sc.nextInt();
			Y[i] = sc.nextInt();
			if ((X[i] + Y[i]) % 2 == 0) {
				even = true;
			} else {
				odd = true;
			}
		}
		if (even && odd) {
			System.out.println(-1);
		} else {
			System.out.println(even ? 31 : 30);
