					tmp /= 2L;
				}
				if (even) {
					tmp = 1L;
					int clDir = -1;
					long minDis = Long.MAX_VALUE / 3;
					for (int dir = 0; dir < 4; dir++) {
						long nextDis = Math.abs(X[i] - x - dirX[dir] * tmp) + Math.abs(Y[i] - y - dirY[dir] * tmp);
