public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    // static int mod = 1_000_000_007;
    long inf = Long.MAX_VALUE;

    void solve(){ 
        int n = ni();
        int[][] res = new int[n][2];
        int p = 0;
        for(int i = 0; i < n; i++){
            res[i][0] = ni();
            res[i][1] = ni();
        }
        for(int i = 0; i < n; i++){
            int tmp = res[i][0]+res[i][1];
            if(i>0){
                if((tmp%2)!=(p%2)){
                    out.println(-1);
                    return;
                }
            }
            p = tmp;
            if(Math.abs(res[i][0])>10||Math.abs(res[i][1])>10){
                out.println(-1);
                return;
            }
        }
        int m = 40;
        if(p%2==1) m = 39;
        out.println(m);
        for(int i = 0; i < m; i++){
            out.print(1+" ");
        }
        out.println();
        for(int i = 0; i < n; i++){
            int x = res[i][0];
            int y = res[i][1];
            int c = 0;
            if(x<0){
                for(int j = 0; j < -x; j++){
                    out.print("L");
                    c++;
                }
            }
            if(x>0){
                for(int j = 0; j < x; j++){
                    out.print("R");
                    c++;
                }
            }
            if(y<0){
                for(int j = 0; j < -y; j++){
                    out.print("D");
                    c++;
                }
            }
            if(y>0){
                for(int j = 0; j < y; j++){
                    out.print("U");
                    c++;
                }
            }
            int nokori = m-c;
            for(int j = 0; j < nokori; j++){
                if(j%2==0) out.print("L");
                else out.print("R");
            }
            out.println();
        }
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.Scanner;

public class Main {
    /**
     * @param args
     */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] X = new int[N];
        int[] Y = new int[N];
        for (int i=0; i<N; i++) {
            X[i] = sc.nextInt();
            Y[i] = sc.nextInt();
        }

        Solve ans = solve(N, X, Y);

        if (ans == null) {
            System.out.println(-1);
        } else {
            System.out.println(ans.m);
            for (int i=0; i<ans.m; i++) {
                if (i != 0) System.out.print(" ");
                System.out.print(ans.d[i]);
            }
            System.out.println();
            for (int i=0; i<N; i++) {
                System.out.println(ans.w[i]);
            }
        }

    }

    private static Solve solve(int N, int[] X, int[] Y) {
        int sum = (Math.abs(X[0]) + Math.abs(Y[0]))%2;
        for (int i=1; i<N; i++) {
            if (sum != (Math.abs(X[i]) + Math.abs(Y[i]))%2) {
                return null;
            }
        }

        Solve ans = new Solve(N, 20 - sum);
        for (int i=0; i<ans.m; i++) {
            ans.d[i] = 1;
        }

        for (int i=0; i<N; i++) {
            int dist = Math.abs(X[i]) + Math.abs(Y[i]);
            ans.w[i] = "";

            for (int x=0; x<Math.abs(X[i]); x++) {
                ans.w[i] += X[i] > 0 ? "R" : "L";
            }
            for (int y=0; y<Math.abs(Y[i]); y++) {
                ans.w[i] += Y[i] > 0 ? "U" : "D";
            }
            for (int d = 0; d<ans.m - dist; d+=2) {
                ans.w[i] += "RL";
            }
        }

        return ans;
    }

    static class Solve {
        public int m = 0;
        public int[] d;
        public String[] w;

        public Solve(int N, int m) {
            this.m = m;
            d = new int[m];
            w = new String[N];
        }

    }

}

