import java.io.*;
import java.util.*;

public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[] x = new int[n];
		int[] y = new int[n];
		long max = 0;
		for (int i = 0; i < n; i++) {
			x[i] = sc.nextInt();
			y[i] = sc.nextInt();

			max = Math.abs(x[i]) + Math.abs(y[i]);
		}

		int mod = Math.abs(x[0] + y[0]) % 2;
		for (int i = 0; i < n; i++) {
			if (Math.abs(x[i] + y[i]) % 2 != mod) {
				pr.println(-1);
				return;
			}
		}

		long dd = 1;
		int m = 1;
		while (2 * dd < max) {
			dd *= 2;
			m++;
		}

		if (mod % 2 == 0) {
			m++;
		}

		pr.println(m);
		long[] d = new long[m];
		for (int i = 0; i < m; i++) {
			d[i] = Math.max(1, dd);
			dd /= 2;
			if (i > 0) {
				pr.print(' ');
			}
			pr.print(d[i]);
		}
		pr.println();

		for (int i = 0; i < n; i++) {
			StringBuilder w = new StringBuilder();

			long xx = 0;
			long yy = 0;
			for (int j = 0; j < m; j++) {
				long dx = x[i] - xx;
				long dy = y[i] - yy;

				if (Math.abs(dx) >= Math.abs(dy)) {
