	public void solve() {
		int n = in.nextInt();
		int[] x = new int[n];
		int[] y = new int[n];
		int[] len = new int[n];
		int max = 0;
		for (int i = 0; i < len.length; i++) {
			x[i] = in.nextInt();
			y[i] = in.nextInt();
			len[i] = Math.abs(x[i]) + Math.abs(y[i]);
			max = Math.max(max, len[i]);
		}
		int n0 = 0;
		int n1 = 0;
		for (int i = 0; i < len.length; i++) {
			if (len[i] % 2 == 0) {
