        int z = 0;
        for (int i = 0; i < n; ++i) {
            x[i] = ni();
            y[i] = ni();
            z |= 1 << ((x[i] + y[i]) & 1);
        }
        if (z == 3) {
            out.println(-1);
            return;
        }
        int t = 31 + (z == 1 ? 1 : 0);
        out.println(t);
