public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    // static int mod = 1_000_000_007;
    long inf = Long.MAX_VALUE;

    void solve(){ 
        int n = ni();
        int[][] res = new int[n][2];
        int p = 0;
        for(int i = 0; i < n; i++){
            res[i][0] = ni();
            res[i][1] = ni();
        }
        for(int i = 0; i < n; i++){
            int tmp = res[i][0]+res[i][1];
            if(i>0){
                if((tmp+p)%2!=0){
                    out.println(-1);
                    return;
                }
            }
            p = tmp;
            if(Math.abs(res[i][0])>10||Math.abs(res[i][1])>10){
                out.println(-1);
                return;
            }
        }
        int m = 40;
        if(p%2==1) m = 39;
        out.println(m);
        for(int i = 0; i < m; i++){
            out.print(1+" ");
        }
        out.println();
        for(int i = 0; i < n; i++){
            int x = res[i][0];
            int y = res[i][1];
            int c = 0;
            if(x<0){
                for(int j = 0; j < -x; j++){
                    out.print("L");
                    c++;
                }
            }
            if(x>0){
                for(int j = 0; j < x; j++){
                    out.print("R");
                    c++;
                }
            }
            if(y<0){
                for(int j = 0; j < -y; j++){
                    out.print("D");
                    c++;
                }
            }
            if(y>0){
                for(int j = 0; j < y; j++){
                    out.print("U");
                    c++;
                }
            }
            int nokori = m-c;
            for(int j = 0; j < nokori; j++){
                if(j%2==0) out.print("L");
                else out.print("R");
            }
            out.println();
        }
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.io.*;
import java.util.*;

public class Main {

    static int N;
    static int[] X;
    static int[] Y;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        X = new int[N];
        Y = new int[N];
        for (int i = 0; i < N; i++) {
            X[i] = sc.nextInt();
            Y[i] = sc.nextInt();
        }

        Answer answer = solve();
        PrintWriter pw = new PrintWriter(System.out);
        if( answer != null ) {
            pw.println(answer.m);
            StringJoiner j = new StringJoiner(" ");
            for (int i : answer.d) {
                j.add(String.valueOf(i));
            }
            pw.println(j.toString());
            for (String w : answer.w) {
                pw.println(w);
            }
        } else {
            pw.println(-1);
        }
        pw.flush();
    }

    static class Answer {
        int m;
        int[] d;
        String[] w;

        public Answer(int m, int[] d, String[] w) {
            this.m = m;
            this.d = d;
            this.w = w;
        }
    }

    static Answer solve() {
        int max = Math.abs(X[0]) + Math.abs(Y[0]);
        boolean even = max % 2 == 0;
        for (int i = 1; i < N; i++) {
            int xy = Math.abs(X[i]) + Math.abs(Y[i]);
            if( xy % 2 == 0 != even ) {
                return null;
            }
            max = Math.max(xy, max);
        }

        int bit;
        int m;
        int[] d;
        if( even ) {
            bit = Integer.toBinaryString(max-1).length();
            m = bit+1;
            d = new int[m];
            for (int b = bit-1; b >= 0 ; b--) {
                d[bit-b-1] = 1 << b;
            }
            d[m-1] = 1;

        } else {
            bit = Integer.toBinaryString(max).length();
            m = bit;
            d = new int[m];
            for (int b = bit-1; b >= 0 ; b--) {
                d[bit-b-1] = 1 << b;
            }
        }

        String[] w = new String[N];
        for (int i = 0; i < N; i++) {
            int x = X[i];
            int y = Y[i];

            StringBuilder sb = new StringBuilder();
            for (int arm : d) {
                if( Math.abs(x) > Math.abs(y) ) {
                    if( x > 0 ) {
                        x = x - (arm);
                        sb.append("R");

                    } else {
                        x = x + (arm);
                        sb.append("L");
                    }
                } else {
                    if( y > 0 ) {
                        y = y - (arm);
                        sb.append("U");

                    } else {
                        y = y + (arm);
                        sb.append("D");
                    }
                }
            }

            if( x == 0 && y == 0 ) {
                w[i] = sb.toString();
            } else {
                throw new RuntimeException("?????!?!? : (" + x + " " + y + ")");
            }
        }

        return new Answer(m, d, w);
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

