        for (int i = n-1 ; i >= 0 ; i--) {
            long v = a[i];
            if (Math.abs(y) > Math.abs(x)) {
                if (y < 0) {
                    y += v;
                    mv[i] = 'D';
                } else {
                    y -= v;
                    mv[i] = 'U';
                }
            } else {
                if (x < 0) {
                    x += v;
                    mv[i] = 'L';
                } else {
                    x -= v;
                    mv[i] = 'R';
                }
            }
        }
        if (y == 0 && x == 0) {
            return String.valueOf(mv);
        }
        throw new RuntimeException("wrong arms");
    }

