		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[] X = new int[N];
		int[] Y = new int[N];
		boolean odd = false;
		boolean even = false;
		for (int i = 0; i < N; i++) {
			X[i] = sc.nextInt();
			Y[i] = sc.nextInt();
			if ((X[i] + Y[i]) % 2 == 0) {
				even = true;
			} else {
				odd = true;
			}
		}
		if (even && odd) {
			System.out.println(-1);
		} else {
			System.out.println(even ? 31 : 30);
			if (even) {
				System.out.print("1 ");
			}
			System.out.print(1);
			long tmp = 2;
			for (int i = 2; i < 30; i++) {
				System.out.print(" " + tmp);
				tmp *= 2;
			}
			System.out.println();
			for (int i = 0; i < N; i++) {
				int x = Math.abs(X[i]);
				int y = Math.abs(Y[i]);
				if (even) {
					if (X[i] > 0) {
						System.out.print("R");
