					} else if (X[i] < 0) {
						System.out.print("L");
						x--;
					} else {
						System.out.print("R");
						x++;
					}
				}
				int minus = (1073741823 - x - y) / 2;
				int sum = x + minus;
				int and = sum & minus;
				int xplus = sum - and;
				int xminus = minus - and;
				int bit = 1;
				for (int j = 1; j <= 30; j++) {
					if ((xplus & bit) > 0) {
						System.out.print(X[i] >= 0 ? "R" : "L");
					} else if ((xminus & bit) > 0) {
						System.out.print(X[i] >= 0 ? "L" : "R");
