			int[] dirX = {1, 0, -1, 0};
			int[] dirY = {0, 1, 0, -1};
			for (int i = 0; i < N; i++) {
				long x = 0;
				long y = 0;
				long tmp = 536870912L;
				for (int j = 29; j >= 0; j--) {
					int clDir = -1;
					long minDis = Long.MAX_VALUE / 3;
					for (int dir = 0; dir < 4; dir++) {
						long nextDis = Math.abs(X[i] - x - dirX[dir] * tmp) + Math.abs(Y[i] - y - dirY[dir] * tmp);
						if (minDis > nextDis) {
							minDis = nextDis;
							clDir = dir;
						}
					}
					x += dirX[clDir] * tmp;
					y += dirY[clDir] * tmp;
