	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			long[] z = new long[n];
			long[] x = new long[n];
			long[] y = new long[n];

			long max = 0;
			for (int i = 0; i < n; i++) {
				x[i] = in.nextLong();
				y[i] = in.nextLong();
				z[i] = abs(x[i]) + abs(y[i]);
				max = Math.max(max, z[i]);
			}

			if (!check(z)) {
				out.println(-1);
				return;
			}

			out.println(max);
			for (int i = 0; i < max; i++) {
				if (i > 0) {
					out.print(" ");
				}
				out.print(1);
			}
			out.print("\n");

			for (int i = 0; i < n; i++) {
				StringBuilder sb = new StringBuilder();
				long count = max;
				for (int j = 0; j < abs(x[i]); j++) {
					if (x[i] < 0) {
						sb.append("L");
					} else {
						sb.append("R");
					}
					count--;
				}
				for (int j = 0; j < abs(y[i]); j++) {
					if (y[i] < 0) {
						sb.append("D");
					} else {
						sb.append("U");
					}
					count--;
				}
				while (count > 0) {
					if (count % 2 == 0) {
						sb.append("U");
					} else {
						sb.append("D");
					}
					count--;
				}

				out.println(sb.toString());
			}

		}
	}

	static boolean check(long[] z) {

		int n = z.length;
		boolean even = true, odd = true;
		for (int j = 0; j < n; j++) {
			// all add
			if (z[j] % 2 == 1) {
			} else {
				odd = false;
			}

			// all even
			if (z[j] % 2 == 0) {
			} else {
				even = false;
			}
		}

		return (even | odd);

	}

