			}
		}
		for (int i = 0; i < sb[0].length(); ++i)
			len.add(1);
		for (int i = 0; i < 19; ++i) {
			len.add(1 << i);
			for (int j = 0; j < n; ++j)
				X[j] += 1 << i;
		}
		for (int i = 0; i < 19; ++i) {
			len.add(1 << i);
			for (int j = 0; j < n; ++j)
				Y[j] += 1 << i;
		}
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < 19; ++j) {
				if ((X[i] & (1L << (j + 1))) > 0) {
					sb[i].append("R");
				} else {
					sb[i].append("L");
				}
			}
		}
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < 19; ++j) {
				if ((Y[i] & (1L << (j + 1))) > 0) {
