            max = abs > max ? abs : max;

            if (type == 0) {
                type = abs%2 == 1 ? 1 : 2;
            }
            if (type == 1 && abs%2 == 0 || type == 2 && abs%2 == 1) {
                type = 0;
                break;
            }
        }

        if (type == 0) {
            System.out.println(-1);
        } else {
            int[] exp = new int[1];
            setExp(exp, max);

            int m = exp[0] + type;
            System.out.println(m);

            long[] d = new long[m];
            for (int i = 0; i < m; i++) {
                if (i < exp[0]) {
                    long pow = pow(2, exp[0]-i);
                    d[i] = pow;
                } else {
                    d[i] = 1;
                }
            }

            String dm = "";
            for (int i = 0; i < exp[0]; i++) {
                dm += d[i]+" ";
            }
