            System.out.println(dm);

            for (int i = 0; i < N; i++) {
                long x = 0;
                long y = 0;
                String w = "";
                for (int j = 0; j < m; j++) {
                    long dx = X[i] - x;
                    long dy = Y[i] - y;
                    if (Math.abs(dx) > Math.abs(dy)) {
                        x += dx > 0 ? d[j] : -d[j];
                        w += dx > 0 ? "R" : "L";
                    } else {
                        y += dy > 0 ? d[j] : -d[j];
                        w += dy > 0 ? "U" : "D";
                    }
                }
                System.out.println(w);
            }
        }
    }

    public static int nextInt(InputStreamReader r) throws Exception {
        String str = "";
        while (true) {
            int c = r.read();
            if (c == 32 || c == 10 || c == -1) {
                break;
            }
            str += (char)c;
        }
        return Integer.parseInt(str);
    }

    public static void setExp(int[] exp, long max) {
        max = max/2;
        exp[0]++;
        if (max != 1) {
            setExp(exp, max);
        }
    }

    public static long pow(int r, int i) {
        if (i == 0) {
            return 1;
        } else {
            return r * pow(r, i-1);
        }
    }
