					for(int j = 1;j < i;j++) {
						System.out.print(" "+1);
					}
					System.out.println();
					for(int j = 0;j < N;j++) {
						System.out.println(S[j]);
					}
					return 0;
				}
			}
			return -1;
		}
	}
}

