    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static Tuple<int[], string[]> Solve(int[][] P)
        {
            int[] C = new int[2];
            foreach (int[] p in P) { ++C[(p[0] + p[1]) & 1]; }
            if (C[0] != 0 && C[1] != 0) { return null; }
            int N = (C[0] == 0) ? 19 : 20;
            var S = new string[P.Length];
            for (int i = 0; i < P.Length; ++i)
            {
                int[] p = P[i];
                var sb = new StringBuilder();
                if (p[0] < 0) { sb.Append('L', Math.Min(-p[0], 10)); }
                if (p[0] > 0) { sb.Append('R', Math.Min( p[0], 10)); }
                if (p[1] < 0) { sb.Append('D', Math.Min(-p[1], 10)); }
                if (p[1] > 0) { sb.Append('U', Math.Min( p[1], 10)); }
                while (sb.Length < N) { sb.Append("LR"); }
                S[i] = sb.ToString();
            }
            return new Tuple<int[], string[]>(Enumerable.Repeat(1, N).ToArray(), S);
        }
        static void Main(string[] args)
        {
            int N = ReadInt();
            int[][] P = new int[N][];
            for (int i = 0; i < N; ++i) { P[i] = ReadInts(); }
            var ans = Solve(P);
            if (ans == null) { Console.WriteLine(-1); }
            else
            {
                Console.WriteLine(ans.Item1.Length);
                Console.WriteLine(string.Join(" ", ans.Item1));
                foreach (string s in ans.Item2) { Console.WriteLine(s); }
            }
        }
    }
}

