    static void Solve()
    {
        var num = Input.num;
        var xy = Input.ar2D(num);
        if(xy.Any(ar=>(Abs(ar[0])+Abs(ar[1]))%2!=(Abs(xy[0][0])+Abs(xy[0][1]))%2))
        { WriteLine(-1);return; }
        var res = new List<int>() { 1 };
        for (var i = 0; i < 30; i++)
            res.Add(res.Last() << 1);
        if ((Abs(xy[0][0]) + Abs(xy[0][1])) % 2 == 0)
            res.Add(1);
        WriteLine($"{res.Count}\n{string.Join(" ", res)}");
        foreach (var ar in xy)
        {
            var x = ar[0] + ar[1];
            var y = ar[0] - ar[1];
            var xsum = 0L;
            var ysum = 0L;
            for(var j = 0; j < res.Count; j++)
            {
                var bx = xsum <= x;var by = ysum <= y;
                if (bx&&by)
                    Write("R");
                else if (bx)
                    Write("U");
                else if (by)
                    Write("D");
                else Write("L");
                xsum += bx ? res[j] : -res[j];
                ysum += by ? res[j] : -res[j];
            }
            WriteLine();//WriteLine($"{xsum} {ysum}");
        }
    }
