namespace Competitive
{
    internal class Solution
    {
        public int N;
        public long MOD = 1000000007;
        public long[] X, Y;
        public int H = 36;

        public void Run()
        {
            N = Input.ReadInt();
            X = new long[N];
            Y = new long[N];
            for (int i = 0; i < N; i++)
            {
                var line = Input.ReadIntArray();
                X[i] = line[0];
                Y[i] = line[1];
            }

            // 偶奇が合っていない例
            long md = (X[0] + Y[0]) % 2;
            for (int i = 0; i < N; i++)
            {
                if ((X[i] + Y[i] + md) % 2 != 0)
                {
                    Console.WriteLine(-1);
                    return;
                }
            }

            // 腕の本数
            var arms = new List<long>();
            if (md == 0) arms.Add(1);
            {
                long x = 1;
                for (int i = 0; i < H; i++)
                {
                    arms.Add(x);
                    x *= 2;
                }
            }

            Console.WriteLine(arms.Count);
            Console.WriteLine(string.Join(" ", arms));
            for (int i = 0; i < N; i++)
            {
                Console.WriteLine(AnsString(X[i], Y[i]));
            }

        }

        public string AnsString(long x, long y)
        {
            string ret = "";
            if ((x + y) % 2 == 0)
            {
                ret += "R";
                x -= 1;
            }

            long u = x + y;
            long v = x - y;
            var ansu = Ans(u);
            var ansv = Ans(v);

            for (int i = 0; i < ansu.Count; i++)
            {
                int au = ansu[i];
                int av = ansv[i];
                if (au == 1 && av == 1) ret += "R";
                if (au == 1 && av == -1) ret += "U";
                if (au == -1 && av == 1) ret += "D";
                if (au == -1 && av == -1) ret += "L";
            }

            return ret;
        }

        public List<int> Ans(long a)
        {
            var ret = new List<int>();
            long x = 1;
            for (int i = 0; i < H - 1; i++)
            {
                long aa = a - x;
                if (Math.Abs(aa) % (4 * x) == 2 * x)
                {
                    a -= x;
                    ret.Add(1);
                }
                else
                {
                    a += x;
                    ret.Add(-1);
                }
                x *= 2;
            }

            if(a == x) ret.Add(1);
            else ret.Add(-1);

            return ret;
        }
    }

