// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()

	type Point struct {
		x int
		y int
	}

	ps := make([]Point, N)

	for i := range ps {
		x := io.NextInt()
		y := io.NextInt()

		ps[i] = Point{x, y}
	}

	m := Abs(ps[0].x+ps[0].y) % 2

	for _, p := range ps {
		if Abs(p.x+p.y)%2 != m {
			io.Println(-1)
			return
		}
	}

	// 任意の整数 n は十分大きな m のもとで 2^0 + .. + 2^m の各項の符号を適当に反転させたもので表すことができる。
	// どの符号を変えればよいかについては、 n = -(2^0 + .. + 2^m) + 2 * (符号を反転させるものの 2^i 和) と表せることより
	// （符号を反転させるものの 2^i 和） = (n + 2^0 + .. + 2^m) / 2 と表せ、 2 進表記で bit の立っている桁を見ることで一意に定まる。
	// また、一意に表せるという前提のもとで、 2^0 + .. + 2^m-1 = 2^m-1 < 2^m より、大きい方 2^m から見ていって、目指す値との差を縮める方に倒さなければいけないことがわかる。
	// 差を大きくする方に倒してしまうと、それ以降全ての値を逆方向に倒しても 2^m で倒した差を埋めることはできないことから、求める値にすることができない。

	ds := []int{}

	for i := 30; i >= 0; i-- {
		d := Pow(2, i)
		ds = append(ds, d)
	}

	if m == 0 {
		ds = append(ds, 1)
	}

	M := len(ds)
	io.Println(M)

	io.PrintInts(ds)

	for _, p := range ps {
		// 45 度変換することで独立に考えることができる
		u := p.x + p.y
		v := p.x - p.y

		curU := 0
		curV := 0

		for _, d := range ds {
			var uDir int
			var vDir int

			if curU < u {
				curU += d
				uDir = 1
			} else {
				curU -= d
				uDir = -1
			}

			if curV < v {
				curV += d
				vDir = 1
			} else {
				curV -= d
				vDir = -1
			}

			x := (uDir + vDir) / 2
			y := (uDir - vDir) / 2

			if x == 1 {
				io.Print("R")
			} else if x == -1 {
				io.Print("L")
			} else if y == 1 {
				io.Print("U")
			} else if y == -1 {
				io.Print("D")
			}
		}

		io.Println()
	}
}

