func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

	n := scanInt(sc)
	xs := make([]int64, n)
	ys := make([]int64, n)
	ps := make([]int, n)
	maxDist := int64(0)

	for i := 0; i < n; i++ {
		xs[i] = int64(scanInt(sc))
		ys[i] = int64(scanInt(sc))
		absSum := abs(xs[i]) + abs(ys[i])
		ps[i] = int(absSum % 2)
		if ps[i] != ps[0] {
			fmt.Println("-1")
			return
		}
		if maxDist < absSum {
			maxDist = absSum
		}
	}

	m := int(math.Ceil(math.Log2(float64(maxDist))))
	ds := make([]int64, m, m+1)
	for i := uint(0); i < uint(m); i++ {
		ds[i] = int64(1 << (uint(m-1) - i))
	}
	if ps[0] == 0 {
		ds = append(ds, 1)
	}

	fmt.Println(len(ds))
	for _, d := range ds {
		fmt.Printf("%d ", d)
	}
	fmt.Println()

	for a := 0; a < n; a++ {
		s := ""
		for b := 0; b < len(ds); b++ {
			if abs(xs[a]) >= abs(ys[a]) {
				if xs[a] >= 0 {
					s += "R"
					xs[a] -= ds[b]
				} else {
					s += "L"
					xs[a] += ds[b]
				}
			} else {
				if ys[a] >= 0 {
					s += "U"
					ys[a] -= ds[b]
				} else {
					s += "D"
					ys[a] += ds[b]
				}
			}
		}
		fmt.Println(s)
	}
}

