let () =
	let n = get_i64 0 in
	let a = init (i32 n) (fun _ -> get_2_i64 0) in
	let par,m = fold_left (fun (u,mx) (x,y) ->
		if (labs (x+y)) mod 2L <> u then (
			printf "-1\n"; exit 0
		) else (u, max mx (labs x+labs y))
	) ((labs (fst a.(0)+snd a.(0))) mod 2L,0L) a
	in
	let pow =
		let pow = init 35 (fun i -> Int64.shift_left 1L (35-$i-$1))
		|> to_list
		in of_list @@
			if par=0L then 1L::(pow |> List.rev) |> List.rev
			else pow
	in
	printf "%Ld\n" @@ alen pow;
	print_array ist pow;
	iter (fun (x,y) ->
		let u,v = fold_left (fun (u,v) p -> 
			if labs (x - u) >= labs (y - v) then (
				if x > u then (
					print_char 'R'; (u+p,v)
				) else (
					print_char 'L'; (u-p,v)
				)
			) else (
				if y > v then (
					print_char 'U'; (u,v+p)
				) else (
					print_char 'D'; (u,v-p)
				)
			)
		) (0L,0L) pow in
