enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

struct P {
  long x, y;
}
struct Q {
  long u, v;
}
Q f(P p) {
  return Q(p.x + p.y, p.x - p.y);
}
P g(Q q) {
  return P((q.u + q.v)/2, (q.u - q.v)/2);
}
void main() {
  long N;
  scanln(N);
  P[] ps = new P[N];
  Q[] qs = new Q[N];
  foreach(i; 0..N) {
    scanln(ps[i].x, ps[i].y);
    qs[i] = f(ps[i]);
  }

  long M = 40;
  long[] ds = (M-1).iota.retro.map!(i => 1L<<i).array ~ [1L];

  Q[][] xss = new Q[][](N, M+1);
  P[][] yss = new P[][](N, M+1);

  bool exists = false;
  foreach(i; 0..N) {
    xss[i][0] = f(P(0, 0));
    foreach(j; 0..M-1) {
      xss[i][j+1].u = xss[i][j].u + ds[j]*(qs[i].u > xss[i][j].u ? 1 : -1);
      xss[i][j+1].v = xss[i][j].v + ds[j]*(qs[i].v > xss[i][j].v ? 1 : -1);
      yss[i][j+1] = g(xss[i][j+1]);
    }
    exists |= yss[i][M-1] != ps[i];
  }
  if (!exists) {
    writeln(M-1);
    ds[0..M-1].map!(d => d.to!string).join(" ").writeln;
    foreach(i; 0..N) {
      (M-1).iota.map!(
        j => P(yss[i][j+1].x - yss[i][j].x, yss[i][j+1].y - yss[i][j].y)
      ).map!(
        diff => diff.x>0 ? 'R' : diff.x<0 ? 'L' : diff.y>0 ? 'U' : 'D'
      ).array.to!string.writeln;
    }
  } else {
    exists = false;
    foreach(i; 0..N) {
      xss[i][M].u = xss[i][M-1].u + ds[M-1]*(qs[i].u > xss[i][M-1].u ? 1 : -1);
      xss[i][M].v = xss[i][M-1].v + ds[M-1]*(qs[i].v > xss[i][M-1].v ? 1 : -1);
      yss[i][M] = g(xss[i][M]);
      exists |= yss[i][M] != ps[i];
    }
    if (!exists) {
      writeln(M);
      ds[0..M].map!(d => d.to!string).join(" ").writeln;
      foreach(i; 0..N) {
        M.iota.map!(
          j => P(yss[i][j+1].x - yss[i][j].x, yss[i][j+1].y - yss[i][j].y)
        ).map!(
          diff => diff.x>0 ? 'R' : diff.x<0 ? 'L' : diff.y>0 ? 'U' : 'D'
        ).array.to!string.writeln;
      }
    } else {
      writeln(-1);
    }
  }
}

