// popcnt with ulongs was added in D 2.071.0
static if (__VERSION__ < 2071) {
  ulong popcnt(ulong x) {
    x = (x & 0x5555555555555555L) + (x>> 1 & 0x5555555555555555L);
    x = (x & 0x3333333333333333L) + (x>> 2 & 0x3333333333333333L);
    x = (x & 0x0f0f0f0f0f0f0f0fL) + (x>> 4 & 0x0f0f0f0f0f0f0f0fL);
    x = (x & 0x00ff00ff00ff00ffL) + (x>> 8 & 0x00ff00ff00ff00ffL);
    x = (x & 0x0000ffff0000ffffL) + (x>>16 & 0x0000ffff0000ffffL);
    x = (x & 0x00000000ffffffffL) + (x>>32 & 0x00000000ffffffffL);
    return x;
  }
}

import std.stdio, std.algorithm, std.conv, std.array, std.string, std.math, std.typecons, std.numeric;

alias XY = Tuple!(long, "x", long, "y");

XY[1000] XYS;

void main()
{
    auto N = readln.chomp.to!int;
    int c = -1;
    foreach (i; 0..N) {
        auto xy = readln.split.to!(long[]);
        auto x = xy[0];
        auto y = xy[1];
        XYS[i] = XY(x, y);
        if (c < 0) c = (x + y) % 2;
        if (c != (x + y) % 2) c = 2;
    }
    if (c == 2) {
        writeln("-1");
        return;
    }
    writeln(39 + (c ? 0 : 1));

    long[] ds;
    ds.length = 39;
    foreach (i; 0..39) {
        ds[i] = 1L<<i;
    }
    if (!c) ds = [1L] ~ ds;
    writeln(ds.map!(to!string).join(" "));

    foreach (xy; XYS[0..N]) {
        auto u = -xy.x - xy.y;
        auto v = -xy.x + xy.y;
        string r;
        foreach_reverse (d; ds) {
            auto a = u < 0 ? 1 : -1;
            auto b = v < 0 ? 1 : -1;
            u += a * d;
            v += b * d;
            if (a == 1 && b == 1) {
                r = "R" ~ r;
            } else if (a == 1 && b == -1) {
                r = "U" ~ r;
            } else if (a == -1 && b == 1) {
                r = "D" ~ r;
            } else {
                r = "L" ~ r;
            }
        }
        writeln(r);
    }
}

import std.stdio;

void main()
{
  writeln("-1");
}

void main() {
  import std.stdio, std.string, std.conv, std.algorithm;

  import std.exception : enforce;
  import std.math : abs;

  int n;
  rd(n);
  auto xs=new int[](n);
  auto ys=new int[](n);
  int odd, even;
  foreach(i; 0..n){
    rd(xs[i], ys[i]);
    if((abs(xs[i])+abs(ys[i]))&1) odd++;
    else even++;
  }
  if(odd*even>0){
    writeln(-1);
    return;
  }
  int m=40;
  int[] d;
  if(odd>0){
    foreach(i; 0..m){
      if(i==0) d~=2;
      else d~=1;
    }
  }else{
    foreach(i; 0..m){
      d~=1;
    }
  }
  writeln(m);
  writefln("%(%s %)", d);
  foreach(i; 0..n) {
    auto x=xs[i], y=ys[i];
    enforce(-10 <= x && x <= 10);
    enforce(-10 <= y && y <= 10);
    char[] moves;
    if ((abs(x) + abs(y)) & 1) {
      moves ~= 'R';
      moves ~= 'L';
      // (0, 0) -> (1, 0)
      foreach (_; 0 .. abs(x - 1)) {
        moves ~= (x < 1 ? 'L' : 'R');
      }
    } else {
      foreach (_; 0 .. abs(x)) {
        moves ~= (x < 0 ? 'L' : 'R');
      }
    }
    foreach (_; 0 .. abs(y)) {
      moves ~= (y < 0 ? 'D' : 'U');
    }
    int r = m - moves.length.to!(int);
    assert(r >= 0 && r % 2 == 0);
    foreach (_; 0 .. (r / 2)) {
      moves ~= 'L';
      moves ~= 'R';
    }
    writeln(moves);
  }
}

void rd(T...)(ref T x) {
  import std.stdio : readln;
  import std.string : split;
  import std.conv : to;

  auto l = readln.split;
  assert(l.length == x.length);
  foreach (i, ref e; x)
    e = l[i].to!(typeof(e));
}

import std.stdio, std.conv, std.string, std.algorithm.iteration, std.math, std.range, std.algorithm.sorting, std.algorithm.searching, std.algorithm.mutation, std.array, std.typecons;

struct Point
{
    int x, y;
    int range()
    {
        return abs(x) + abs(y);
    }
}

void main()
{
    int N = readln.chomp.to!int;
    Point[] pointList;
    int[] connectPoint;
    foreach(i; 0..N)
    {
        int[] xy = readln.split.to!(int[]);
        pointList ~= Point(xy[0], xy[1]);
    }
    int maxRange = pointList.reduce!((a,b)=>a.range>b.range?a:b).range;

    if(pointList.length == 1 && pointList[0].range == 0)
    {
        writeln("2");
        writeln("1 1");
        writeln("RL");
        return;
    }
    foreach(point; pointList)
    {
        int outRange = maxRange - point.range;
        if(outRange % 2 == 1)
        {
            writeln("-1");
            return;
        }
        if(point.range == 0)
        {
            connectPoint ~= maxRange / 2;
            continue;
        }
        int firstConnectPos = firstConnectPos(point);
        if(firstConnectPos != 0)
            connectPoint ~= firstConnectPos;
        connectPoint ~= point.range;
        if(outRange == 0)
        {
            continue;
        }
        connectPoint ~= point.range + outRange / 2;
    }
    connectPoint.sort;
    connectPoint.length -= connectPoint.uniq.copy(connectPoint).length;
    auto sortedConnectPoint = assumeSorted(connectPoint);
    // writeln("pointList: ", pointList);
    // writeln("connectList: ", sortedConnectPoint);

    int prev = 0;
    writeln(sortedConnectPoint.length);
    foreach(c; sortedConnectPoint)
    {
        write(c - prev," ");
        prev = c;
    }
    writeln("");
    foreach(point; pointList)
    {
        int xCount;
        int yCount; 
        //座標まで
        if(abs(point.x) < abs(point.y))
        {
            if(point.x != 0)
            {
                xCount = sortedConnectPoint.lowerBound(abs(point.x)).length.to!int + 1;
            }
            yCount = sortedConnectPoint.lowerBound(point.range).length.to!int + 1 - xCount;
        }else{
            if(point.y != 0)
            {
                yCount = sortedConnectPoint.lowerBound(abs(point.y)).length.to!int + 1;
            }
            xCount = sortedConnectPoint.lowerBound(point.range).length.to!int + 1 - yCount;
        }
        if(abs(point.x) < abs(point.y))
        {
            foreach(i; 0..xCount)
            {
                write(point.x > 0 ? "R" : "L");
            }
            foreach(i; 0..yCount)
            {
                write(point.y > 0 ? "U" : "D");
            }
        }else{
            foreach(i; 0..yCount)
            {
                write(point.y > 0 ? "U" : "D");
            }
            foreach(i; 0..xCount)
            {
                write(point.x > 0 ? "R" : "L");
            }
        }
        //あまりの処理
        if(point.range != maxRange)
        {
            int overRange = maxRange - point.range;
            int nowRange;
            prev = sortedConnectPoint[xCount+yCount - 1];
            foreach(p; sortedConnectPoint[xCount+yCount..$])
            {
                write(nowRange < overRange / 2 ? "R" : "L");
                nowRange += p - prev;
                prev = p;
            }
        }
        writeln("");
   }
}
int firstConnectPos(Point point)
{
    return abs(point.x) < abs(point.y) ? abs(point.x) : abs(point.y);
}

