        foreach (d; D) {
            if (abs(x) >= abs(y)) {
                if (x >= 0) {
                    x -= d;
                    ans ~= 'R';
                } else {
                    x += d;
                    ans ~= 'L';
                }
            } else {
                if (y >= 0) {
                    y -= d;
                    ans ~= 'U';
                } else {
                    y += d;
                    ans ~= 'D';
                }
            }
        }
        ans.reverse();
        ans.writeln;
    }
}

