        int xCount;
        int yCount; 
        //座標まで
        if(abs(point.x) < abs(point.y))
        {
            if(point.x != 0)
            {
                xCount = sortedConnectPoint.lowerBound(abs(point.x)).length.to!int + 1;
            }
            yCount = sortedConnectPoint.lowerBound(point.range).length.to!int + 1 - xCount;
        }else{
            if(point.y != 0)
            {
                yCount = sortedConnectPoint.lowerBound(abs(point.y)).length.to!int + 1;
            }
            xCount = sortedConnectPoint.lowerBound(point.range).length.to!int + 1 - yCount;
        }
        if(abs(point.x) < abs(point.y))
        {
            foreach(i; 0..xCount)
