                write(point.y > 0 ? "U" : "D");
            }
            foreach(i; 0..xCount)
            {
                write(point.x > 0 ? "R" : "L");
            }
        }
        //あまりの処理
        if(point.range != maxRange)
        {
            int overRange = maxRange - point.range;
            int nowRange;
            prev = sortedConnectPoint[xCount+yCount - 1];
            foreach(p; sortedConnectPoint[xCount+yCount..$])
            {
                write(nowRange < overRange / 2 ? "R" : "L");
                nowRange += p - prev;
                prev = p;
            }
        }
        writeln("");
   }
