def solve(n, ps):
    if len({(x + y) % 2 for x, y in ps}) != 1:
        return None
    m = max(abs(x) + abs(y) for x, y in ps)
    ds = [1 for _ in range(m)]
    commands = ["" for _ in range(n)]
    for i, (x_f, y_f) in enumerate(ps):
        dx = abs(x_f)
        dy = abs(y_f)
        if x_f < 0:
            commands[i] += "L" * dx
        elif x_f > 0:
            commands[i] += "R" * dx
        if y_f < 0:
            commands[i] += "D" * dy
        elif y_f > 0:
            commands[i] += "U" * dy
        rest_m = m - dx - dy
        assert rest_m % 2 == 0
        if rest_m > 0:
            commands[i] += "L" * (rest_m // 2) + "R" * (rest_m // 2)
    return m, ds, commands



