import numpy as np


class Point(np.ndarray):
    def __new__(cls, t):
        new = super(Point, cls).__new__(cls, shape=(len(t),))
        return new

    def __init__(self, t):
        assert len(t) == 2
        super(Point, self).__init__()
        self[:] = t

    @property
    def x(self):
        return self[0]

    @property
    def y(self):
        return self[1]


def distance(p1, p2):
    return abs(p1.x - p2.x) + abs(p1.y - p2.y)


class Solutions(object):
    sm = {
        'U': Point([0, 1]),
        'D': Point([0, -1]),
        'L': Point([-1, 0]),
        'R': Point([1, 0]),
    }
    sk = 'UDLR'

    def __init__(self, first):
        self._arms = []
        solution = []
        if first.x > 0:
            self._arms.append(Arm(first.x, len(self._arms)))
            solution.append('R')
        if first.y > 0:
            self._arms.append(Arm(first.y, len(self._arms)))
            solution.append('U')
        self.arms = None
        self.n = len(self._arms)
        self.sort_arms()

        self._solutions = {first.index: solution}
        self.report()

    @property
    def solutions(self):
        return self._solutions.values()

    def get_solution(self, i):
        return self._solutions[i]

    def sort_arms(self):
        self.arms = sorted(self._arms, key=lambda arm: arm.length, reverse=True)

    def split_arm(self, index, chunk):
        assert chunk < self._arms[index].length
        self._arms[index].length -= chunk
        self._arms.append(Arm(length=chunk, index=len(self._arms)))
        self.sort_arms()
        self.n = len(self._arms)

        for solution in self.solutions:
            solution.append(solution[index])

    def get_closest(self, pos, t, w):
        min_d = distance(pos + np.array([w, 0]), t)
        dx, dy = t - pos
        res_k = None
        for k in self.sk:
            d = distance(pos + self.sm[k] * w, t)
            if d < min_d:
                res_k = k
                min_d = d
            elif d == min_d:
                if abs(dx) > abs(dy) and k in 'LR':
                    res_k = k
                elif k in 'UD':
                    res_k = k
        return res_k

    def add_target(self, target):
        while not self._add_target(target):
            pass

    def _add_target(self, target):
        # step 1 - try to go as close as possible
        solution = []
        t = Point((target.x, target.y))
        pos = Point([0, 0])

        for i in range(self.n):
            k_min = self.get_closest(pos, t, self.arms[i].length)
            solution.append(k_min)
            pos += self.sm[k_min] * self.arms[i].length

        # step 2 - fix the error.
        dx, dy = t - pos
        if DEBUG:
            print("Initial solution:", solution)
        if DEBUG:
            print(dx, dy)

        m = {}
        m['U'] = m['D'] = 'R' if dx > 0 else 'L'
        m['R'] = m['L'] = 'U' if dy > 0 else 'D'

        while abs(dx) + abs(dy) > 0:
            # find what we can break
            brw = {}
            td = abs(dx) + abs(dy)
            if abs(dx) > abs(dy):
                brw['U'] = brw['D'] = 1
                brw['L'] = 2 if dx > 0 else 0
                brw['R'] = 2 if dx < 0 else 0
            else:
                brw['L'] = brw['R'] = 1
                brw['D'] = 2 if dy > 0 else 0
                brw['U'] = 2 if dy < 0 else 0

            for i, k in list(enumerate(solution))[::-1]:
                if brw[k] * self.arms[i].length > td:
                    w = td // brw[k]
                    self.split_arm(self.arms[i].index, w)
                    pos -= self.sm[k] * w
                    if DEBUG:
                        print "Old direction", k
                        print "Removing: ", self.sm[k] * w
                    k1 = self.get_closest(pos, t, w)
                    if k1 == k:
                        return False
                    if DEBUG:
                        print "New direction", k1
                        print "Adding: ", self.sm[k1] * w
                    pos += self.sm[k1] * w
                    solution.append(k1)
                    break
                if i == 0:
                    return False

            dx, dy = t - pos

            self.report()
            if DEBUG:
                print "New solution:", solution
                print "Distance:" ,(dx, dy), 'Position', (pos.x, pos.y), 'target:',  (t.x, t.y)

            if DEBUG:
                import time
                time.sleep(1)

        sd = {self.arms[i].index: solution[i] for i in range(len(solution))}
        solution = [sd[i] for i in range(len(solution))]

        self._solutions[target.index] = solution

        return True

    f_x = {'L': 'R', 'R': 'L', 'D': 'D', 'U': 'U'}
    f_y = {'L': 'L', 'R': 'R', 'U': 'D', 'D': 'U'}

    def report(self):
        if DEBUG:
            print("Arms: ", [a.length for a in self.arms])
        # if DEBUG:
        #     print("Solutions:", self.solutions)

    def get_flipped_solution(self, index, x, y):
        s = ''.join(self.get_solution(index))
        if x < 0:
            s = ''.join(self.f_x[c] for c in s)
        if y < 0:
            s = ''.join(self.f_y[c] for c in s)
        return s


