from typing import List, Tuple


def get_distance(point: Tuple[int, int]) -> int:
    return abs(point[0]) + abs(point[1])


def answer():
    n = int(input())
    points = []  # type: List[Tuple[int, int]]
    for i in range(n):
        tmp = input()
        x, y = [int(w) for w in tmp.split()]
        points.append((x, y))

    MAX_HAND_NUM = 40

    all_even_or_odd = True
    mod2 = None
    for point in points:
        now_mod2 = (point[0] + point[1]) % 2
        if mod2 is None:
            mod2 = now_mod2
        if mod2 != now_mod2:
            all_even_or_odd = False
            break
    if not all_even_or_odd:
        print('-1')
        return

    # partial answer
    max_distance = max([get_distance(point) for point in points])
    if max_distance > MAX_HAND_NUM:
        print('TODO!')
        return

    hand_num = max_distance
    print(hand_num)
    print(' '.join(['1' for _ in range(hand_num)]))
    for point in points:
        ans = ''
        distance = get_distance(point)
        ans += 'LR' * ((hand_num - distance) // 2)
        # horizontal
        for val, direc_plus, direc_minus in zip(point, ['R', 'U'], ['L', 'D']):
            if val > 0:
                ans += direc_plus * val
            else:
                ans += direc_minus * abs(val)
        print(ans)


if __name__ == '__main__':
    answer()

