from itertools import product


def helper(dx,dy):
  if (dx,dy) == (0,0):
    return 'LR',0,0
  elif (dx,dy) == (0,1):
    return 'DD',0,1
  elif (dx,dy) == (0,2):
    return 'UU',0,0
  elif (dx,dy) == (1,0):
    return 'LL',1,0
  elif (dx,dy) == (1,1):
    return 'RU',0,0
  elif (dx,dy) == (1,2):
    return 'DR',0,1
  elif (dx,dy) == (2,0):
    return 'RR',0,0
  elif (dx,dy) == (2,1):
    return 'LU',1,0
  elif (dx,dy) == (2,2):
    return 'LD',1,1

def validate(D,solution):
  x,y = 0,0
  for d,m in zip(D,solution):
    if m == 'L':
      x -= d
    elif m == 'R':
      x += d
    elif m == 'D':
      y -= d
    else:
      y += d
  return x,y

def solve(x,y):

  result = []
  for i in range(19):
    xx = x%3
    yy = y%3

    s,a,b = helper(xx,yy)
    result.append(s)
    x = (x-xx)//3 + a
    y = (y-yy)//3 + b

  result = ''.join(result)
  return result


