DEBUG = False


def inp():
    return sys.stdin.readline().rstrip()


def dprint(*value, sep=' ', end='\n'):
    if DEBUG:
        print(*value, sep=sep, end=end)


def solve(N, A):
    par = abs(A[0][0] + A[0][1]) % 2
    for (x, y) in A:
        if abs(x + y) % 2 != par:
            return None

    m = [1] * (10 + par)
    S = []

    for (x, y) in A:
        assert abs(x) <= 10
        assert abs(y) <= 10
        s = []
        if x >= 0:
            for _ in range(x):
                s.append('R')
        else:
            for _ in range(-x):
                s.append('L')

        if y >= 0:
            for _ in range(y):
                s.append('U')
        else:
            for _ in range(-y):
                s.append('D')

        while len(s) < len(m):
            s.append('R')
            s.append('L')

        S.append(''.join(s))

    return (m, S)


def main():
    N = int(inp())
    A = []
    for _ in range(N):
        x, y = [int(e) for e in inp().split()]
        A.append((x, y))

    ans = solve(N, A)
    if ans is None:
        print('-1')
        return

    m, s = ans
    print(len(m))
    print(*m)
    for t in s:
        print(t)


if __name__ == '__main__':
    main()

