    arm = 3 ** k
    arms = (3 ** k - 1)//2
    if k == -1:
        return ""
    if x + y > 2 * arms:
        if y - x > 2 * arms:
            return "UU" + zahyou(x, y- 2*arm, k-1)
        elif -2 * arms <= y - x <= 2 * arms:
            return "UR" + zahyou(x- arm, y- arm, k-1)
        else:
            return "RR" + zahyou(x- 2 *arm, y, k-1)
    elif -2 * arms <= x + y <= 2 * arms:
        if y - x > 2 * arms:
            return "UL" + zahyou(x+ arm, y- arm, k-1)
        elif -2 * arms <= y - x <= 2 * arms:
            return "UD" + zahyou(x, y, k-1)
        else:
            return "DR" + zahyou(x- arm, y+ arm, k-1)
    else:
        if y - x > 2 * arms:
            return "LL" + zahyou(x+ 2*arm, y, k-1)
        elif -2 * arms <= y - x <= 2 * arms:
            return "LD" + zahyou(x+ arm, y+ arm, k-1)
        else:
            return "DD" + zahyou(x, y+ 2*arm, k-1)



