def recursiveOdd(x, y, str):
    p = 31 - len(str)
    if x == 0 and y == 0:
        return str
    elif abs(x) > abs(y):
        if x > 0:
            return recursiveOdd(x - 2**p, y, str + 'R')
        else:
            return recursiveOdd(x + 2**p, y, str + 'L')
    else:
        if y > 0:
            return recursiveOdd(x, y - 2**p, str + 'U')
        else:
            return recursiveOdd(x, y + 2**p, str + 'D')

