    def decide(x, pos, neg):
        if x < 0:
            posneg = [pos, neg]
        else:
            posneg = [neg, pos]
        a = abs(x) // 2
        buf = []
        for _ in range(18):
            buf.append(posneg[a & 1])
            a >>= 1
        buf.append(posneg[1])
        return ''.join(buf), posneg[0]

    ans = []
    for x, y in targets:
        xbuf, xfrc = decide(x, 'R', 'L')
        ybuf, yfrc = decide(y, 'U', 'D')
        tmp = xbuf + ybuf
        if x % 2 == 0:
            tmp += xfrc
        if y % 2 == 0:
            tmp += yfrc
        if x % 2 == 1 and y % 2 == 1:
            tmp += 'LR'
        ans.append(tmp)
    return arms, ans


