fn main() {
    input!{
        n: usize,
        ps: [(i64, i64); n],
    }

    let even = ps.iter().all(|&(x, y)| (x.abs() + y.abs()) % 2 == 0);
    let odd = ps.iter().all(|&(x, y)| (x.abs() + y.abs()) % 2 == 1);

    if !even && !odd {
        println!("-1");
        return;
    }

    let m = if even { 40 } else { 39 };

    println!("{}", m);
    for i in 0..m {
        if i != 0 {
            print!(" ");
        }
        print!("{}", 1);
    }
    println!("");

    for (x, y) in ps.into_iter() {
        let mut x = x;
        let mut y = y;
        let mut rest = m;
        loop {
            if x < 0 {
                print!("L");
                x += 1;
            } else if x > 0 {
                print!("R");
                x -= 1;
            } else if y < 0 {
                print!("D");
                y += 1;
            } else if y > 0 {
                print!("U");
                y -= 1;
            } else {
                break;
            }
            rest -= 1;
        }
        assert!(rest >= 0 && rest % 2 == 0);

        while rest > 0 {
            print!("LR");
            rest -= 2;
        }

        println!("");
    }
