fn main() {
    input!{
        n: usize,
        v: [[i64; 2]; n]
    }
    let odd = (v[0][0] + v[0][1]).abs() % 2;
    for i in 1..n {
        let x = v[i][0];
        let y = v[i][1];
        if (x + y).abs() % 2 != odd {
            println!("-1");
            return;
        }
    }
    let m = 31;
    if odd == 0 {
        println!("{}", m + 1);
        print!("1 ");
    } else {
        println!("{}", m);
    }
    for i in 0..m-1 {
        print!("{} ", 1 << i);
    }
    println!("{}", 1 << m-1);
    for i in 0..n {
        let mut x = v[i][0];
        let y = v[i][1];
        let mut moves: Vec<char> = Vec::new();
        if odd == 0 {
            x -= 1;
            moves.push('R');
        }
        let u = x + y;
        let v = x - y;
        let mut tu = ((1 << 31) - 1 - u) >> 1;
        let mut su = vec![false; 31];
        for j in 0..31 {
            su[j] = tu & 1 == 0;
            tu >>= 1;
        }
        let mut tv = ((1 << 31) - 1 - v) >> 1;
        let mut sv = vec![false; 31];
        for j in 0..31 {
            sv[j] = tv % 2 == 0;
            tv >>= 1;
        }
        for j in 0..31 {
            if su[j] {
                if sv[j] {
                    moves.push('R');
                } else {
                    moves.push('U');
                }
            } else if sv[j] {
                moves.push('D');
            } else {
                moves.push('L');
            }
        }
        println!("{}",moves.into_iter().collect::<String>());
    }
}

