fn doit(a: &Vec<i64>, mut x: i64, mut y: i64)  {
    let n = a.len();
    let mut dirs = vec![' '; n];
    let dx = vec![0, -1, 0, 1];
    let dy = vec![1, 0, -1, 0];
    let dc = vec!['D', 'R', 'U', 'L'];
    for i in 0..n {
        let d = a[i];

        let mut best = (x.abs()+y.abs()+d*2, x, y, 4);
        for j in 0..4 {
            let tx = x + d * dx[j];
            let ty = y + d * dy[j];
            let to_dist = tx.abs() + ty.abs();
            if to_dist < best.0 {
                best = (to_dist, tx, ty, j);
            }
        }
        x = best.1;
        y = best.2;
        dirs[n-1-i] = dc[best.3];
    }

