#[fastout]
fn main() {
    input! {
        n: usize,
        xy: [(i64, i64); n]
    }
    let m = (xy[0].0 + xy[0].1).rem_euclid(2);
    for &(x, y) in xy.iter() {
        if (x + y).rem_euclid(2) != m {
            println!("-1");
            return;
        }
    }
    let d = (0..N).map(|i| 1i64 << i).collect::<Vec<_>>();
    if m == 1 {
        println!("{}", N);
    } else {
        println!("{}", N + 1);
        print!("1 ");
    }
