            v -= 1;
            print!("R");
        }
        let mut xs = vec![false; N];
        u += 1 << N;
        u -= 1;
        u /= 2;
        while u != 0 {
            xs[u.trailing_zeros() as usize] = true;
            u &= u - 1;
        }
        let mut ys = vec![false; N];
        v += 1 << N;
        v -= 1;
        v /= 2;
        while v != 0 {
            ys[v.trailing_zeros() as usize] = true;
            v &= v - 1;
        }
        println!(
            "{}",
            xs.iter()
                .zip(ys.iter())
                .map(|(&u, &v)| {
                    if u && v {
                        "R"
                    } else if !u && !v {
                        "L"
                    } else if u && !v {
                        "D"
                    } else {
                        "U"
                    }
                })
                .format("")
        );
    }
}

use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn with_stdout_lock<F: FnOnce(std::io::BufWriter<std::io::StdoutLock>)>(f: F) {
    let out = std::io::stdout();
    let w = std::io::BufWriter::new(out.lock());
    f(w);
}

fn main() {
    let n: usize = input();
    let xy: Vec<(i64, i64)> = (0..n).map(|_| (input(), input())).collect();

    let ok = xy.windows(2).all(|p| {
        let (p0, p1) = (p[0], p[1]);
        let p0 = p0.0.abs() + p0.1.abs();
        let p1 = p1.0.abs() + p1.1.abs();
        p0 % 2 == p1 % 2
    });
    if !ok {
        println!("-1");
        return;
    }

    let mx = xy
        .iter()
        .map(|&(x, y)| std::cmp::max(x.abs(), y.abs()))
        .max()
        .unwrap();
    let mut k = 1;
    let mut a = vec![1];
    while k < mx {
        k *= 2;
        a.push(k);
    }
    if mx % 2 == 0 {
        a.push(1);
    }
    a.sort_by_key(|&a| -a);

    let mut ans = vec![];
    for &(x, y) in &xy {
        let mut temp = String::new();
        let goal = (x, y);
        let mut cur = (0, 0);
        for &a in &a {
            if i64::abs(goal.0 - cur.0) > i64::abs(goal.1 - cur.1) {
                if goal.0 > cur.0 {
                    temp.push('R');
                    cur.0 += a;
                } else {
                    temp.push('L');
                    cur.0 -= a;
                }
            } else {
                if goal.1 > cur.1 {
                    temp.push('U');
                    cur.1 += a;
                } else {
                    temp.push('D');
                    cur.1 -= a;
                }
            }
        }
        ans.push(temp);
    }

    with_stdout_lock(|mut w| {
        writeln!(w, "{}", a.len()).unwrap();
        for i in 0..a.len() {
            write!(w, "{}{}", a[i], if i == a.len() - 1 { '\n' } else { ' ' }).unwrap();
        }
        for ans in ans {
            writeln!(w, "{}", ans).unwrap();
        }
    });
}

