fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($format:expr) => (write!(out,$format).unwrap());
        ($format:expr, $($args:expr),+) => (write!(out,$format,$($args),*).unwrap())
    }
    input!{
        n: usize,
        xy: [(i64, i64); n],
    }
    let mut even = 0;
    let mut odd = 0;
    for &(x, y) in xy.iter() {
        if (x + y) % 2 == 0 {
            even += 1;
        } else {
            odd += 1;
        }
    }
    if even > 0 && odd > 0 {
        puts!("-1\n");
        return;
    }
    const W: usize = 35;
    let mut gadget: Vec<i64> = vec![];
    let mut ox = 0;
    let oy = 0;
    for i in 0 .. W {
        gadget.push(1 << i);
        // Assume all arms are R
        ox += 1 << i;
    }
    if even > 0 {
        gadget.push(1);
        ox += 1;
    }
    puts!("{}\n", gadget.len());
    for i in 0 .. gadget.len() {
        puts!("{}{}", if i == 0 { "" } else { " " }, gadget[i]);
    }
    puts!("\n");
    for i in 0 .. n {
        let (dx, dy) = (xy[i].0 - ox, xy[i].1 - oy);
        let (du, dv) = ((dy - dx) / 2, (-dy - dx) / 2);
        //puts!("{:?} {:?}", (dx, dy), (du, dv));
        let mut sol = vec![];
        for i in 0 .. W {
            let c = match (du & 1 << i, dv & 1 << i) {
                (0, 0) => 'R',
                (0, _) => 'D',
                (_, 0) => 'U',
                (_, _) => 'L',
            };
            sol.push(c);
        }
        if even > 0 { sol.push('R'); }
        puts!("{}\n", sol.into_iter().collect::<String>());
    }
}

