use std::io::Write;

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    input! {
        n: usize,
        p: [(i32, i32); n],
    }
    let s = p.iter().fold(0, |s, p| s + (p.0.abs() + p.1.abs()) % 2);
    if 0 < s && s < n as i32 {
        writeln!(out, "-1").unwrap();
        return;
    }
    let mut d = vec![];
    if s == n as i32 {
        d.push(1i32);
    }
    d.push(1);
    for i in 0..31 {
        d.push(1 << i);
    }
    d.reverse();
    writeln!(out, "{}", d.len()).unwrap();
    for (i, d) in d.iter().enumerate() {
        if i > 0 {
            write!(out, " ").unwrap();
        }
        write!(out, "{}", *d).unwrap();
    }
    writeln!(out, "").unwrap();
    for (mut x, mut y) in p {
        for &d in d.iter() {
            if x.abs() >= y.abs() {
                if x < 0 {
                    write!(out, "L").unwrap();
                    x += d;
                } else {
                    write!(out, "R").unwrap();
                    x -= d;
                }
            } else {
                if y < 0 {
                    write!(out, "D").unwrap();
                    y += d;
                } else {
                    write!(out, "U").unwrap();
                    y -= d;
                }
            }
        }
        assert!(x == 0 && y == 0);
        writeln!(out, "").unwrap();
    }
}

