fn solve_(uvs: Vec<(i64, i64)>, ds: Vec<i64>) -> Vec<String> {
    let mut ans = Vec::new();

    let dir = [["R", "U"], ["D", "L"]];

    for (u,v) in uvs {
        let mut cu = 0;
        let mut cv = 0;

        let mut s = String::new();
        for &d in ds.iter() {
            let ud = if cu < u { cu += d; 0} else { cu -= d; 1};
            let vd = if cv < v { cv += d; 0} else { cv -= d; 1};
            s.push_str(dir[ud][vd]);
        }
        ans.push(s);
    }

    ans
}

fn solve(xys: Vec<(i64, i64)>) -> Option<(Vec<i64>, Vec<String>)> {
    let parity = (xys[0].0 + xys[0].1).abs() % 2;
    let mut uvs = Vec::new();
    for &(x, y) in xys.iter() {
        if (x+y).abs() % 2 != parity {
            return None
        }
        uvs.push((x+y, x-y));
    }

    let mut ds = Vec::new();

    for i in (0..31).rev() {
        ds.push(2i64.pow(i));
    }

    if parity == 0 {
        ds.push(1);
    }

    Some((ds.clone(), solve_(uvs, ds)))
}

fn main() {
    let n = parse_line!(usize);
    let xys = (0..n).map(|_| parse_line!(i64, i64)).collect::<Vec<_>>();

    match solve(xys) {
