            println!("{}", ds.len());
            println!("{}", ds.iter().map(|d| format!("{}", d)).collect::<Vec<_>>().join(" "));
            ws.iter().map(|w| println!("{}", w));
        },
        _ => {
            println!("-1");
        }
    }
}

