    for &(x, y) in xy.iter() {
        if (x + y).rem_euclid(2) != m {
            println!("-1");
            return;
        }
    }
    let mut d = (0..N - 1)
        .scan(1i64, |a, _| {
            *a *= 2;
            Some(*a)
        })
        .collect::<Vec<_>>();
    d.insert(0, 1);
