fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };
    let n: usize = sc.read();
    let mut xy = vec![];
    for _ in 0..n {
        let x: i64 = sc.read();
        let y: i64 = sc.read();
        xy.push((x, y));
    }

    if xy.iter().any(|&(x, y)| (x + y).abs() % 2 == 0)
        && xy.iter().any(|&(x, y)| (x + y).abs() % 2 == 1)
    {
        println!("-1");
        return;
    }

    let mut arms: Vec<i64> = (0..31).rev().map(|i| 1 << i).collect::<Vec<_>>();
    if (xy[0].0 + xy[0].1).abs() % 2 == 0 {
        arms.push(1);
    }

    let arms_sum = arms.iter().sum::<i64>();

    println!("{}", arms.len());
    for (i, &arm) in arms.iter().enumerate() {
        if i > 0 {
            print!(" ");
        }
        print!("{}", arm);
    }
    println!();

    for &(x, y) in xy.iter() {
        let p = x + y;
        let mut cur_sum = arms_sum;
        let mut x_dir = vec![];
        for &arm in arms.iter() {
            if cur_sum - 2 * arm >= p {
                cur_sum -= 2 * arm;
                x_dir.push(-1);
            } else {
                x_dir.push(1);
            }
        }

        let q = x - y;
        let mut cur_sum = arms_sum;
        let mut y_dir = vec![];
        for &arm in arms.iter() {
            if cur_sum - 2 * arm >= q {
                cur_sum -= 2 * arm;
                y_dir.push(-1);
            } else {
                y_dir.push(1);
            }
        }

        let n = x_dir.len();
        for i in 0..n {
            match (x_dir[i], y_dir[i]) {
                (1, 1) => print!("R"),
                (1, -1) => print!("U"),
                (-1, 1) => print!("D"),
                (-1, -1) => print!("L"),
                _ => unreachable!(),
            }
        }
        println!();
    }
}

pub struct Scanner<R> {
    reader: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .reader
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::{self, BufRead};
use std::collections::BTreeSet;
use Dir::*;

#[derive(Copy, Clone)]
enum Dir {
  Up, Down, Left, Right
}

impl Dir {
  fn to_char(self) -> u8 {
    match self {
      Up => 'U' as u8,
      Down => 'D' as u8,
      Left => 'L' as u8,
      Right => 'R' as u8,
    }
  }
}

fn main() {
  let stdin = io::stdin();
  let mut lines = stdin.lock().lines();
  let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
  let mut ps: Vec<(i32, i32)> = Vec::new();
  for _ in 0..n {
    let xs: Vec<i32> = lines.next().unwrap().unwrap().split(' ').map(|x| x.parse().unwrap()).collect();
    ps.push((xs[0], xs[1]));
  }
  let even = ps.iter().filter(|(px, py)| (px.abs() + py.abs()) % 2 == 0).count();
  if even != 0 && even != ps.len() {
    println!("-1");
    return;
  }
  let len = ps.iter().map(|(px, py)| px.abs() + py.abs()).max().unwrap();
  let mut joints: BTreeSet<i32> = BTreeSet::new();
  for (px, py) in &ps {
    if *px != 0 {
      joints.insert(px.abs() as i32);
    }
    let dist = px.abs() + py.abs();
    if dist != len {
      joints.insert((dist + len) / 2);
    }
  }
  let joints: Vec<i32> = joints.into_iter().collect();
  let mut temp = 0;
  for i in 0..joints.len() {
    print!("{} ", joints[i] - temp);
    temp = joints[i];
  }
  println!("{}", if joints.is_empty() { len } else { len - joints[joints.len()-1] });
  for (px, py) in ps {
    let mut d = if px == 0 {
      if py >= 0 { Up } else { Down }
    } else if px >= 0 {
      Right
    } else {
      Left
    };
    let mut ds: Vec<u8> = vec![d.to_char()];
    let p1 = px.abs();
    let p2 = py.abs();
    let p3 = (len + p1 + p2) / 2;
    for i in 0..joints.len() {
      if p1 == joints[i] {
        d = if py >= 0 { Up } else { Down };
      } else if p3 == joints[i] {
        d = match d {
          Up => Down,
          Down => Up,
          Left => Right,
          Right => Left,
        };
      }
      ds.push(d.to_char());
    }
    println!("{}", String::from_utf8(ds).unwrap());
  }
}

