fn solve(xys: Vec<(i64, i64)>) -> Option<(Vec<i64>, Vec<String>)> {
    let parity = (xys[0].0 + xys[0].1).abs() % 2;
    let mut uvs = Vec::new();
    for &(x, y) in xys.iter() {
        if (x+y).abs() % 2 != parity {
