const N: usize = 35;

#[fastout]
fn main() {
    input! {
        n: usize,
        xy: [(i64, i64); n]
    }
    let m = (xy[0].0 + xy[0].1).rem_euclid(2);
    for &(x, y) in xy.iter() {
        if (x + y).rem_euclid(2) != m {
            println!("-1");
            return;
        }
    }
    let mut d = (0..N - 1)
        .scan(1i64, |a, _| {
            *a *= 2;
            Some(*a)
        })
        .collect::<Vec<_>>();
    d.insert(0, 1);
    if m == 1 {
        println!("{}", N);
    } else {
        println!("{}", N + 1);
        print!("1 ");
    }
    println!("{}", d.iter().format(" "));
    for &(x, y) in xy.iter() {
        let mut u = x - y;
        let mut v = x + y;
        if m == 0 {
            u -= 1;
            v -= 1;
            print!("R");
        }
        let mut xs = vec![false; N];
        u += 1 << N;
        u -= 1;
        u /= 2;
        while u != 0 {
            xs[u.trailing_zeros() as usize] = true;
            u &= u - 1;
        }
        let mut ys = vec![false; N];
        v += 1 << N;
        v -= 1;
        v /= 2;
        while v != 0 {
            ys[v.trailing_zeros() as usize] = true;
            v &= v - 1;
        }
        for (u, v) in (0..N).map(|i| (xs[i], ys[i])) {
            if u && v {
                print!("R");
            } else if !u && !v {
                print!("L");
            } else if u && !v {
                print!("D");
            } else {
                print!("U");
            }
        }
        println!("");
    }
}

extern crate core;

use std::io::{self, Read};

#[macro_export]
macro_rules! input {
  ($s:expr=>$($t:tt)*) => {
    let mut lines=$s.split("\n");
    $(
        line_parse!(lines,$t);
    )*
  };
}

macro_rules! line_parse {
  ($lines:expr,($($name:ident:$t:tt)*)) => {
    let mut line=$lines.next().unwrap().split_whitespace();
    $(value_def!(line,$name,$t);)*
  };

  //複数行
  ($lines:expr,{$n:expr;$name:ident:$t:tt}) => {
    values_def!($lines,$n,$name,$t);
  };
}

macro_rules! value_def {
    ($line:expr, $name:ident, $t:tt) => {
        let $name = value!($line, $t);
    };
}

macro_rules! values_def {
    ($lines:expr, $n:expr, $name:ident, $t:tt) => {
        let $name = {
            let mut vec = Vec::new();
            for i in 0..$n {
                let mut next = $lines.next().unwrap().split_whitespace();
                vec.push(value!(next, $t));
            }
            vec
        };
    };
}

macro_rules! value {
  //配列
  ($line:expr,[$t:tt]) => {
    $line.map(|x|{
      let mut iter=::std::iter::once(x);
      value!(iter,$t)
    }).collect::<Vec<_>>()
  };
  //タプル
  ($line:expr,($($t:tt),*)) => {
    ($(value!($line,$t),)*)
  };
  //文字列
  ($line:expr,#) => {
    $line.next().unwrap()
  };
  //インデックス(-1)
  ($line:expr,@) => {
    $line.next().unwrap().parse::<usize>().unwrap()-1
  };
  //単一値
  ($line:expr,$t:ty) => {
    $line.next().unwrap().parse::<$t>().unwrap()
  };
}

