        let list = list
            .clone()
            .into_iter()
            .map(|(a, b)| a + b)
            .collect::<Vec<_>>();
        let g = list[0] % 2;
        for x in list {
            if x % 2 != g {
                return "-1".to_string();
            }
        }
    }
    panic!();
}

