    test2: "5\n0 0\n1 0\n2 0\n3 0\n4 0" => "-1",
    test3: "2\n1 1\n1 1" => "2\n1 1\nRU\nUR",
    test4: "3\n-7 -3\n7 3\n-3 -7" => "5\n3 1 4 1 5\nLRDUL\nRDULR\nDULRD",
