const N: usize = 5;

#[fastout]
fn main() {
    input! {
        n: usize,
        xy: [(i64, i64); n]
    }
    let m = (xy[0].0 + xy[0].1).rem_euclid(2);
    for &(x, y) in xy.iter() {
        if (x + y).rem_euclid(2) != m {
            println!("-1");
            return;
        }
    }
    let mut d = (0..N - 1)
        .scan(1i64, |a, _| {
            *a *= 2;
            Some(*a)
        })
        .collect::<Vec<_>>();
    d.insert(0, 1);
    if m == 1 {
        println!("{}", N);
    } else {
        println!("{}", N + 1);
        print!("1 ");
    }
    println!("{}", d.iter().format(" "));
    for &(x, y) in xy.iter() {
        let mut u = x - y;
        let mut v = x + y;
        if m == 0 {
            u += 1;
            v += 1;
            print!("R");
        }
        let mut xs = vec![true; N];
        u += 1 << N;
        u -= 1;
        u /= 2;
        while u != 0 {
            xs[u.trailing_zeros() as usize] = false;
            u &= u - 1;
        }
        let mut ys = vec![true; N];
        v += 1 << N;
        v -= 1;
        v /= 2;
        while v != 0 {
            ys[v.trailing_zeros() as usize] = false;
            v &= v - 1;
        }
        for (u, v) in (0..N).map(|i| (xs[i], ys[i])) {
            if u && v {
                print!("L");
            } else if !u && !v {
                print!("R");
            } else if u && !v {
                print!("U");
            } else {
                print!("D");
            }
        }
        println!("");
    }
}

