    for i in 0..m {
        if i > 0 {
            print!(" ");
        }
        print!("{}", edges[i]);
    }
    println!();

    let sum = edges.iter().sum::<i64>();

    for &(x, y) in xy.iter() {
        let u = x + y;
        let mut arms_u = vec![false; m];
        let v = x - y;
        let mut arms_v = vec![false; m];

        let u = u + sum;
        let v = v + sum;
        let mut cur_u = 0;
        let mut cur_v = 0;
        for i in (0..m).rev() {
            let edge = edges[i];
            if cur_u + 2 * edge <= u {
                cur_u += 2 * edge;
                arms_u[i] = true;
            }
            if cur_v + 2 * edge <= v {
                cur_v += 2 * edge;
                arms_v[i] = true;
            }
