fn validate(s: &Vec<char>, edges: &Vec<i64>, x: i64, y: i64) {
    let mut cur_x = 0;
    let mut cur_y = 0;
    assert_eq!(s.len(), edges.len());
    let n = s.len();
    for i in 0..n {
        match s[i] {
            'R' => {
                cur_x += edges[i];
            }
            'L' => {
                cur_x -= edges[i];
            }
            'D' => {
                cur_y -= edges[i];
            }
            'U' => {
                cur_y += edges[i];
            }
            _ => unreachable!(),
        }
    }
    assert_eq!((cur_x, cur_y), (x, y));
}

